INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('a3815fa2-7e35-4147-8912-2bd64b3fc066', 'Fleet Insurance', 'en/fleet-insurance', '2026-09-24 20:56:22.29436+00', '{"Title": null, "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": null, "ImageUrl": null, "Description": null}, "Description": null, "CanonicalUrl": null}', '2026-08-19 12:04:43.566585+00', false, false, 'en', '316e0273-30ca-4cf6-a752-3e331b52d196', 'fleet-insurance', '{"type": "page", "children": [{"id": "e7bbcabc-4048-4293-a0cf-5268767e22d2", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Add a clear introduction for this page.", "items": [{"href": "/contact", "label": "Learn more", "variant": "inverse"}], "eyebrow": "Section label", "heading": "New page heading", "imageAlt": "", "mobileImageUrl": "/uploads/20260924205005-9296b40e78d14346bc47c622a6af075c.webp", "desktopImageUrl": "/uploads/20260924205005-9296b40e78d14346bc47c622a6af075c.webp"}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "d1799d52-5b34-4645-a51d-cf46fc7eca1b", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Choose a service to learn more.", "items": [{"href": "", "imageAlt": "", "imageUrl": "", "position": 1, "solutionSlug": "health"}], "heading": "Insurance services"}, "visible": true, "children": [], "settings": {"sectionType": "solution-cards"}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('42335d10-346e-4e19-b876-bef35d160269', 'Fidelity Guarantee Insurance | Triple H Insurance Broker', 'en/solutions/fidelity-guarantee-insurance', '2026-09-24 11:49:23.594138+00', '{"Title": "Fidelity Guarantee Insurance Lebanon | Triple H Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Fidelity Guarantee Insurance in Lebanon | Triple H Broker", "ImageUrl": null, "Description": "Fidelity guarantee insurance for losses caused by employee theft, fraud or dishonesty, arranged around your business by Triple H Insurance Broker."}, "Description": "Fidelity guarantee insurance in Lebanon for employee theft, fraud and dishonesty. Compare insurers, limits and terms with Triple H Insurance Broker.", "CanonicalUrl": "https://www.triplehbroker.com/en/solutions/fidelity-guarantee-insurance"}', '2026-09-21 13:19:21.006858+00', false, false, 'en', '18bb4eb0-d1b4-4d60-b48f-9594407ae155', 'builder', '{"type": "page", "children": [{"id": "cfa354e5-0432-45ff-8a51-cfe0195e40a4", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Protect your business against direct financial loss caused by fraudulent or dishonest acts committed by employees, including theft or embezzlement, with cover arranged around your business and required limits.", "items": [{"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}], "eyebrow": "BUSINESS & EMPLOYEE INSURANCE", "heading": "Fidelity Guarantee Insurance", "imageAlt": "", "mobileImageUrl": "", "desktopImageUrl": ""}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "2ef5b03c-d5a8-4884-a03c-b885dcee875e", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Fidelity guarantee insurance protects a business against direct financial loss caused by fraudulent or dishonest acts committed by employees, including theft, embezzlement or misappropriation of money or property. Triple H compares suitable insurers and arranges cover around your employee roles, financial exposure and required limits.", "eyebrow": "FIDELITY GUARANTEE INSURANCE", "heading": "What is fidelity guarantee insurance?", "audience": "Retailers, wholesalers, restaurants, hotels, pharmacies, manufacturers, distributors and other businesses whose employees handle cash, stock, payments, accounts or company assets.", "buttonHref": "/en/contact", "buttonLabel": "Request a Quote", "audienceHeading": "Who it is for"}, "visible": true, "children": [], "settings": {"sectionType": "solution-introduction"}}, {"id": "7554a2d5-04ee-4b32-af21-eec958db6d24", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "b76dc06e-3375-4dde-8d9f-c4059bfbdf6a", "type": "container", "visible": true, "children": [{"id": "4109c178-8516-42a4-9a77-a14b2b2f2fa7", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "How can fidelity guarantee cover be structured?", "level": 2}, "visible": true}, {"id": "207e0abc-c3e9-4343-a099-4a56cc35e917", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Fidelity guarantee cover can be structured around specific employees, job positions, selected employee groups or the wider workforce, depending on how your business manages money and assets."}, "visible": true}, {"id": "70bda0aa-7489-4c7c-b5e9-4fed431bab52", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "9ebf9053-921d-4694-8232-2844be88e864", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "76c88995-f968-4b4a-a88b-871e85ea0701", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Named Employee Cover", "level": 3}, "visible": true}, {"id": "523c9f93-c733-48c5-841a-cbc281a81016", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Cover for specific employees named in the policy, with an agreed limit for each person or for the group."}, "visible": true}]}, {"id": "04522331-6029-4cb7-be45-9a41124c0f54", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "2e433914-a72d-44e9-b231-e53ea69daf45", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Position-Based Cover", "level": 3}, "visible": true}, {"id": "52d7e574-cb99-4b30-ba0d-4be407455342", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Cover arranged by job role rather than employee name, such as cashier, accountant, storekeeper or finance manager."}, "visible": true}]}, {"id": "c1680499-6760-4bda-b28c-e70341edecd1", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "a99510de-1a6c-449b-b8a4-6de53e81f92b", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Selected Employee Groups", "level": 3}, "visible": true}, {"id": "eddc094a-1e63-4549-8a8c-96f6f3cdcf7e", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Cover for defined categories of employees whose duties involve money, stock, payments, accounts or other company assets."}, "visible": true}]}, {"id": "76afacc2-3bb5-4229-860b-df156b7ecca5", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "87a1b57c-97b4-4c53-b5d4-5d93e79989f6", "type": "heading", "content": {"text": "Blanket Employee Cover", "level": 3}, "visible": true}, {"id": "d440abc1-6d47-47b8-b31f-4f061044a95f", "type": "text", "content": {"text": "Broader cover for the workforce without listing each employee individually, subject to the limits and terms agreed with the insurer."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "2125cb97-caee-4f50-8440-2621b2fa0695", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"help": "We compare insurers, employee or position-based structures, limits, deductibles, discovery periods, extensions and exclusions, arrange suitable cover for your business, and handle claims with the insurer from notification through assessment and settlement.", "intro": "Depending on the policy, fidelity guarantee insurance can cover direct financial loss caused by fraudulent or dishonest acts committed by employees, including theft, embezzlement or misappropriation of money, goods or other company property.", "items": [{"text": "Employee Theft & Dishonesty"}, {"text": "Fraud & Embezzlement"}, {"text": "Misappropriation of Money or Funds"}, {"text": "Loss of Goods or Other Company Property"}, {"text": "Forgery, Where Covered"}, {"text": "Loss Involving Employee Collusion, Where Covered"}], "heading": "What can fidelity guarantee insurance cover?", "helpHeading": "How Triple H helps"}, "visible": true, "children": [], "settings": {"sectionType": "coverage-details"}}, {"id": "a01151ca-1465-41a6-a01a-44d1e4b64d9d", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "The right fidelity guarantee policy depends on more than premium. The employees covered, insured property, limits, discovery terms and policy conditions can all affect how the cover responds.", "items": [{"text": "Insurer reputation, fidelity experience and claims settlement record"}, {"text": "Named, position-based, selected-group or blanket employee cover"}, {"text": "Definition of employee and which roles are insured"}, {"text": "Limits per employee or position and overall policy limit"}, {"text": "Deductibles or excesses applying to a loss"}, {"text": "Money, securities, stock and other company property covered"}, {"text": "Treatment of collusion, forgery and other dishonest acts"}, {"text": "Discovery period for identifying an insured loss"}, {"text": "Accounting, audit and reconciliation requirements under the policy"}, {"text": "Key exclusions and conditions affecting employee dishonesty claims"}], "heading": "What to compare before choosing fidelity guarantee insurance"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "50f3c134-60c7-4f8e-bcd7-bb95ba506b2f", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We review where employee dishonesty could create a financial loss, compare suitable insurers in the Lebanese market and structures, then arrange cover around the roles and limits your business needs.", "items": [{"body": "We review which employees handle cash, payments, stock, accounts or other company assets, together with the controls already in place.", "title": "Review Your Employee Exposure"}, {"body": "We compare cover structures, insured employees or positions, limits, deductibles, discovery periods, conditions, exclusions and premium.", "title": "Compare Suitable Insurers"}, {"body": "We place the selected policy, confirm the employees or positions covered and make sure the agreed limits and policy terms match your business.", "title": "Arrange the Selected Cover"}, {"body": "We handle claims, changes and renewals as employee roles, responsibilities, limits or business operations change.", "title": "Keep the Cover Up to Date"}], "layout": "grid", "heading": "How we arrange fidelity guarantee insurance"}, "visible": true, "children": [], "settings": {"sectionType": "steps"}}, {"id": "195eadaf-7527-4dac-b529-1f8caad7e03a", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Contact Triple H as soon as suspected fraud, theft or dishonesty is discovered. We notify the insurer, help organize the evidence and manage the claim through assessment and settlement.", "items": [{"text": "We help you gather the records needed to establish what happened and quantify the loss, such as accounting records, bank statements, stock records, transaction histories and internal investigation findings."}, {"text": "We coordinate with the insurer and any appointed loss adjuster or investigator, respond to requests for further information and follow the assessment of the dishonest act and the resulting financial loss."}, {"text": "We review the insurer’s response and any proposed settlement against the policy terms, limits and applicable deductible, and continue following the claim until the process is concluded."}], "heading": "When employee dishonesty causes a financial loss"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "f7b24bd2-9d86-480d-a908-267d2eb6e205", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Practical answers about employee dishonesty, theft, fraud, insured employees, discovery periods, limits and what to do when a loss is suspected.", "items": [{"answer": "Fidelity guarantee covers financial loss caused by dishonest or fraudulent acts committed by employees. Money insurance generally covers money against risks such as robbery, burglary or loss while in transit, depending on the policy.", "question": "Q1 – What is the difference between fidelity guarantee and money insurance?"}, {"answer": "Cover can be arranged for named employees, particular job positions, selected employee groups or a broader workforce, depending on the insurer and how the policy is structured.", "question": "Q2 – Which employees can be covered?"}, {"answer": "The policy can cover direct financial loss arising from acts such as theft, fraud, embezzlement or misappropriation of money or company property. The exact insured acts depend on the policy wording.", "question": "Q3 – What types of employee dishonesty can be covered?"}, {"answer": "Loss involving stock or other company property may be covered under fidelity guarantee, depending on the insurer and policy wording. Before arranging the policy, we explain exactly which assets are covered, the applicable limits and whether any additional cover is needed.", "question": "Q4 – What if an employee steals stock or other company property?"}, {"answer": "Collusion between employees can be covered under fidelity guarantee insurance. Before placing the policy, we explain how the insurer treats collusion, what limits apply and how a loss involving several employees would be covered.", "question": "Q5 – What if more than one employee is involved in the fraud?"}, {"answer": "The claim may still be covered if the dishonest act and its discovery fall within the policy’s applicable terms and discovery period. We check this carefully when comparing policies.", "question": "Q6 – What if the loss is discovered after the employee has left the company?"}, {"answer": "This depends on the policy wording. Some policies may require the responsible employee to be identified, while cover for losses caused by unidentified employees may be available under specific terms. Before placement, we explain how this is treated and what evidence would be required.", "question": "Q7 – Does the business have to identify the employee responsible?"}, {"answer": "Not usually. Fidelity guarantee is primarily designed for dishonest acts by employees. External fraud or cyber-related losses may require Crime, Cyber or another appropriate policy.", "question": "Q8 – Does fidelity guarantee cover fraud committed by customers, suppliers or hackers?"}, {"answer": "Not automatically. The loss normally needs to be supported by evidence showing that it resulted from an insured dishonest or fraudulent act rather than an ordinary accounting or inventory discrepancy.", "question": "Q9 – Does an unexplained cash or stock shortage automatically count as a fidelity claim?"}, {"answer": "The appropriate limit depends on how much money or property employees can access, their responsibilities, transaction values and the potential financial loss from a dishonest act. We review these exposures before comparing limits.", "question": "Q10 – How much fidelity guarantee cover does our business need?"}, {"answer": "Preserve the relevant records and contact Triple H promptly. We notify the insurer, confirm what information is required and handle the claim on your behalf from notification through assessment and settlement.", "question": "Q11 – What should we do if we suspect employee fraud or theft?"}, {"answer": "We usually need your business activity, number of employees, the roles to be covered, the money or property they handle, required limits and details of the financial controls and checking procedures in place.", "question": "Q12 – What information do we need for a fidelity guarantee quote?"}], "heading": "Fidelity Guarantee Insurance FAQs", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "d519265a-2eca-4b9b-9e53-8877dc4f39a0", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Explore other cover that can protect your business against cyber incidents, physical asset losses and third-party liability alongside fidelity guarantee insurance.", "heading": "Other Business Insurance", "buttonHref": "/en/solutions/business", "buttonLabel": "Explore Business Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "callout"}}, {"id": "9c82e05f-a715-4285-9ec6-9200d30798c0", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "697ff39e-8eb9-41cd-a5a6-d0bcce30cae6", "type": "container", "visible": true, "children": [{"id": "4db50016-64b9-472a-8a18-6c39ed9a4b44", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Get a fidelity guarantee insurance quote", "level": 2}, "visible": true}, {"id": "0171fb9c-cadb-43af-80c6-9e69da6d253d", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us about your business, the employee roles you want to cover, the money or property they handle and the limits you need. We’ll compare suitable insurers in the Lebanese market and come back with clear written options."}, "visible": true}, {"id": "952ce0a0-c662-4224-a9b1-ff57561eaea5", "type": "button", "content": {"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, "visible": true}, {"id": "2835935f-83ef-4347-9b91-fcda43a97250", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('69791354-e97b-4e45-9748-85beb89a67cd', 'Insurance Guides & Resources in Lebanon | Triple H Broker', 'en/resources', '2026-09-25 14:15:15.641299+00', '{"Title": "Insurance Guides & Resources in Lebanon | Triple H Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Insurance Guides & Resources in Lebanon | Triple H Broker", "ImageUrl": null, "Description": "Clear, practical insurance guidance for individuals, families and businesses in Lebanon—from choosing cover and comparing policies to renewals and claims."}, "Description": "Practical insurance guides for Lebanon. Understand cover, compare policies, prepare for renewal and claims, and see how Triple H Insurance Broker helps.", "CanonicalUrl": "https://www.triplehbroker.com/en/resources"}', '2026-08-23 21:22:12.508216+00', false, false, 'en', '74bfdfd0-278f-4ee1-b8af-8da459e0dd89', 'builder', '{"type": "page", "children": [{"id": "f5b51a9f-5ae7-44d3-accb-afcd190d909d", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Practical insurance guides, checklists and clear explanations from Triple H Insurance Broker to help individuals, families and businesses in Lebanon understand cover, compare policies, prepare for renewal and know what to do when a claim occurs.", "items": [], "eyebrow": "INSURANCE RESOURCES", "heading": "Insurance Guides & Resources in Lebanon", "imageAlt": "", "mobileImageUrl": "/uploads/20260925141503-6650def5fa2b4d60b263cf6d6b198c0a.webp", "desktopImageUrl": "/uploads/20260925141205-77e105c9aaba4cebb473afddc12587d6.webp"}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "1c20f999-6c50-4d5d-99c6-8d09edd36c22", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "a5b01900-619f-4a64-9f2f-19956f733e73", "type": "container", "visible": true, "children": [{"id": "32dc89b1-bcd4-4cbf-9fbc-858cd3e6d4d6", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Start With What You Need", "level": 2}, "visible": true}, {"id": "28cc4e26-c985-4c20-8b2e-42d9b7c52945", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Choose where you want to start, whether you are exploring insurance, dealing with a claim or looking at cover for your business."}, "visible": true}, {"id": "576863d6-9db5-4000-b6f9-8beb56c4582d", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "52102b50-3aa3-4e84-ae2c-9e020e27bef2", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c60f7024-0a37-4abe-b259-d56363229d82", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Explore Insurance Solutions", "level": 3}, "visible": true}, {"id": "fb764497-2dfc-418b-aed8-e8e8c1d63b72", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Browse personal, family, business and specialist insurance solutions available through Triple H."}, "visible": true}, {"id": "7299bcf8-f12c-49f3-a1e8-501ea36c02e8", "type": "button", "content": {"href": "/en/solutions", "label": "Explore Insurance Solutions", "variant": "primary"}, "visible": true}]}, {"id": "c04e8d32-9deb-470f-b835-a7bf0bfee283", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c51af4ce-2df2-4cd3-a243-cba0c0486bce", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Claims Support", "level": 3}, "visible": true}, {"id": "5fbe2b6e-6c31-4a28-9cfb-767ed6eeeddd", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "See what to do when a loss occurs, what may be required and how Triple H handles claims with the insurer."}, "visible": true}, {"id": "dcb0fb4e-828b-47ef-ba5f-c684fddaa971", "type": "button", "content": {"href": "/en/claims", "label": "View Claims Support", "variant": "primary"}, "visible": true}]}, {"id": "a3e35ee0-9cdc-4269-9ecd-136a8c06ba28", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "7a965a2a-6a1f-4cab-a33a-f95d0e736e7c", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Insurance by Industry", "level": 3}, "visible": true}, {"id": "4a5ce121-2a69-4344-a6e3-44202fa78873", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Explore how insurance needs differ across industries and the types of cover commonly considered for different businesses."}, "visible": true}, {"id": "83986d51-ba15-4c83-b2cf-3f9346eaae50", "type": "button", "content": {"href": "/en/industries", "label": "Explore Industries", "variant": "primary"}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "d1036f1f-4fce-456e-91d9-cb3b0106c413", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Two insurance policies can look similar and still provide very different protection. Premium, limits, deductibles, exclusions, conditions and policy wording can all affect what happens when you actually need to use the cover.", "items": [{"text": "Start with what you need to protect. For individuals and families, this may include health, motor, home, life or travel insurance. For businesses, it may include property, employees, vehicles, liability, cargo, cyber and other specialist risks."}, {"text": "The cheapest option is not always the most suitable one. Insurers can differ in what they cover, the limits they offer, the deductibles they apply, the exclusions and conditions in the policy and how particular risks are treated."}, {"text": "That is where Triple H comes in. We assess your needs, compare suitable insurers and explain the meaningful differences before you choose. After placement, we handle policy changes and renewals. If a claim occurs, we notify the insurer, confirm what information is required and handle the claim on your behalf from notification through assessment and settlement."}], "heading": "Insurance in Lebanon: What to Compare Before You Choose Cover"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "3406b6ce-63e9-4d27-8764-3edec9729e27", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "430421a0-910e-4c3f-9308-6ebc70e2f0be", "type": "container", "visible": true, "children": [{"id": "0ef1ce78-34d1-4e26-8d29-a7d1b4c39491", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Insurance Guides", "level": 2}, "visible": true}, {"id": "5cef92c5-9537-44c2-88ba-184cfce708c1", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Practical guides to help you understand insurance in Lebanon, compare cover more carefully and make informed decisions before you buy, at renewal and when a claim occurs."}, "visible": true}, {"id": "5262e334-5e46-4e8e-8945-0b47f6d7d6be", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "eb1d19ae-ca79-47cc-8084-f013f25ee8a7", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "bf59669e-2090-4196-bbe8-e5e8789f6a50", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Insurance Broker vs Insurance Company: What’s the Difference?", "level": 3}, "visible": true}, {"id": "0daca018-c85a-4865-bf18-e7549166b161", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Understand the difference between buying directly from an insurer and working with an insurance broker that assesses your needs, compares suitable options and represents you throughout the policy lifecycle."}, "visible": true}]}, {"id": "e742b89f-8000-4c5b-a7fe-db561d3918cf", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "e7cafc62-964e-4bf3-9d5a-69ca59d58a78", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "How to Read an Insurance Policy", "level": 3}, "visible": true}, {"id": "d48def27-14e3-4d0f-8d2b-5c3b16ef2fb4", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Learn how to understand your cover, limits, deductibles, exclusions and policy conditions — and what to check before accepting a policy."}, "visible": true}]}, {"id": "0a450dfa-919a-45be-bc7e-c7c7ab2bd673", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "18ecb08c-a944-441c-b3e1-972cdd2237b4", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "How to Compare Insurance Quotes Properly", "level": 3}, "visible": true}, {"id": "1d461033-1ca9-4867-a8e1-f85a9a24be0b", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Learn how to compare insurance quotations beyond price, including cover, limits, deductibles, exclusions, conditions, insurer terms and the differences that may matter at claim time."}, "visible": true}]}, {"id": "22d03446-38f7-4b39-a7f1-f7fc56f485d3", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "627e2949-f26a-4566-bc14-67ddcb9778ea", "type": "heading", "content": {"text": "Insurance Limits, Deductibles, Exclusions and Conditions Explained", "level": 3}, "visible": true}, {"id": "fee8af1f-2191-4a84-8fe2-531e4a8170e0", "type": "text", "content": {"text": "Understand the key parts of an insurance policy that determine what is covered, how much may be paid and what requirements or restrictions apply."}, "visible": true}]}, {"id": "fa1d29cf-676e-4367-80ed-547bf2e8063a", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "a22c5f14-0e85-4343-af65-5518300e0d67", "type": "heading", "content": {"text": "What Is Underinsurance and How Can It Affect a Claim?", "level": 3}, "visible": true}, {"id": "56f9bb29-ecef-4e77-8e69-0df5690b9ec2", "type": "text", "content": {"text": "Understand what underinsurance means, why insured values matter and how insuring property or assets below the appropriate value can affect a claim."}, "visible": true}]}, {"id": "27981ecf-c662-4f8c-9979-2358e1bc13d7", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "eea92e04-abac-4488-8548-26e5613720f3", "type": "heading", "content": {"text": "What Can Affect an Insurance Claim?", "level": 3}, "visible": true}, {"id": "9622894d-ef37-497f-b50d-bc0358fefe6d", "type": "text", "content": {"text": "Understand how cover, exclusions, inaccurate or incomplete information, notification requirements, documentation, deductibles, limits and policy conditions can affect a claim."}, "visible": true}]}, {"id": "c1cf8621-42ad-4f1c-b22d-7c9538406f21", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "787f329d-5132-4d6f-a26d-dc7811ef4bbb", "type": "heading", "content": {"text": "Health Insurance in Lebanon: A Buyer’s Guide", "level": 3}, "visible": true}, {"id": "02c9b088-b5a0-4fb5-bfbc-8f7d3892f29e", "type": "text", "content": {"text": "Understand hospital networks and classes, in-patient and out-patient cover, waiting periods, pre-existing conditions, limits and other points to compare when choosing health insurance in Lebanon."}, "visible": true}]}, {"id": "96274f00-91c8-4f1e-a12c-78e75a19ccd9", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c6009b2b-9966-4cb1-a6fb-551e20719c56", "type": "heading", "content": {"text": "Motor Insurance in Lebanon: Third Party vs Comprehensive", "level": 3}, "visible": true}, {"id": "24e19f3f-a724-48fb-aa6d-e5f0246735d1", "type": "text", "content": {"text": "Understand the difference between third-party and comprehensive motor insurance, what each type of cover protects and what to compare before choosing motor insurance in Lebanon."}, "visible": true}]}, {"id": "17266354-5eeb-4187-b2d0-e136574f0658", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "1dec4569-bd6d-47c7-a5a2-228f89b2d56d", "type": "heading", "content": {"text": "Home Insurance in Lebanon: A Buyer’s Guide", "level": 3}, "visible": true}, {"id": "40cfd191-b1cf-47c8-a7a7-ee85a5e746b2", "type": "text", "content": {"text": "Understand how to protect your home, building, contents and belongings, how insured values are set and what to compare for fire, water damage, theft, natural events and liability."}, "visible": true}]}, {"id": "a273a8ea-9170-4fa6-91d0-0a637062bb24", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "ef2f2725-3dd0-4c66-b278-49581c5f90f5", "type": "heading", "content": {"text": "Life Insurance in Lebanon: A Buyer’s Guide", "level": 3}, "visible": true}, {"id": "6bd9f0da-c63d-4b4d-aa4f-b4e8fdce2809", "type": "text", "content": {"text": "Understand the main types of life insurance and family protection, how cover amounts are determined and what to compare when protecting income, debts and long-term financial obligations."}, "visible": true}]}, {"id": "c2002d05-12e8-4537-b622-ae6defafedcf", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "0c624b3e-f741-4db3-890f-55a55c0f72b0", "type": "heading", "content": {"text": "Travel Insurance in Lebanon: A Buyer’s Guide", "level": 3}, "visible": true}, {"id": "996abb55-8d24-4d8f-8447-f0fa8720f5dc", "type": "text", "content": {"text": "Understand emergency medical cover, evacuation and repatriation, trip cancellation, baggage, policy limits and visa requirements when comparing travel insurance in Lebanon."}, "visible": true}]}, {"id": "52dade64-2c0d-41b2-ae22-11a903e14052", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "1452f1e2-22b0-4517-a7c6-c63c487bcf2e", "type": "heading", "content": {"text": "Business Insurance in Lebanon: What Should a Company Consider?", "level": 3}, "visible": true}, {"id": "17f20919-9f81-4b07-89c8-6b75351e78ce", "type": "text", "content": {"text": "Understand the main risks a business may need to insure, including property, employees, liability, vehicles, cargo, cyber exposures and other risks depending on how the business operates."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "dd9ae510-a04b-4883-b156-f8c1dc7167d2", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "36653077-6beb-438b-ba13-3915af168cb1", "type": "container", "visible": true, "children": [{"id": "4434c2b3-39e2-490a-9d7a-89c50176cfcc", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Practical Insurance Guides & Checklists", "level": 2}, "visible": true}, {"id": "af901afe-7c11-43d3-aeba-e8596adc91dc", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Know what information to prepare and what to review. Triple H handles the comparison, placement, policy changes, renewals and claims with the insurer on your behalf."}, "visible": true}, {"id": "6b8c1583-2161-4b13-bd37-d6a8d32cfca9", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "9536ac20-1bdd-4357-8bd0-e2b661b17c99", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "b416aa70-cba2-4e11-a32f-47bcdf369b79", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Preparing for an Insurance Quote", "level": 3}, "visible": true}, {"id": "98ffbee2-5b74-41cb-a732-302d05eabbfb", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "See what information helps us understand your needs before we approach insurers in Lebanon, compare suitable options and explain the differences in cover, limits, deductibles, exclusions and terms."}, "visible": true}]}, {"id": "b29176bc-c8aa-493e-93b6-6a6c98412d7d", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "5a99253a-9168-4ebd-8200-8714d9eee1f8", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Preparing for Your Insurance Renewal", "level": 3}, "visible": true}, {"id": "482ba00d-9ec7-499a-9a20-4c75bc07756e", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Review what has changed since your policy was arranged, then let Triple H reassess your needs, check whether the existing cover still fits and compare renewal terms where appropriate."}, "visible": true}]}, {"id": "1281b24d-19c8-40b0-babc-3e77262a9bdc", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c1b2a892-037c-4b5c-b704-29f628abf9db", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "What to Prepare When You Have a Claim", "level": 3}, "visible": true}, {"id": "1c5f3eff-e5a9-4e59-9a4a-5b23082b6366", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "See what information and documents may be useful after a loss. Contact Triple H promptly and we’ll notify the insurer, confirm what is required and handle the claim on your behalf through assessment and settlement."}, "visible": true}]}, {"id": "ca25a67c-c609-44cf-9bba-73c88e8a6a59", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "b8d0768a-8bb1-481c-8b12-1df9c32305c2", "type": "heading", "content": {"text": "Reviewing Your Sums Insured", "level": 3}, "visible": true}, {"id": "df50a78e-a9a4-4a6d-af6a-3e4242b747dd", "type": "text", "content": {"text": "Understand which values may need reviewing for buildings, contents, equipment, stock and other assets. Triple H can help identify what needs to be declared and explain how the insurer’s valuation and underinsurance terms apply."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "2589a0ea-ecf3-42c4-b2a7-d39c62f20861", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "These resources help you understand insurance. Triple H applies that knowledge to your actual circumstances by assessing your needs, comparing suitable insurers and explaining the differences before cover is arranged.", "items": [{"text": "Insurance decisions depend on more than knowing what a policy is called. The appropriate cover, limits, deductibles and conditions depend on what you need to protect, the risks involved and how different insurers are prepared to cover them."}, {"text": "Before placement, Triple H reviews your needs, approaches suitable insurers and compares the options beyond premium. We explain meaningful differences in cover, limits, deductibles, exclusions, conditions and policy wording so you understand what you are choosing before you commit."}, {"text": "After placement, we handle policy changes and renewals. If a claim occurs, we notify the insurer, confirm what information is required and handle the claim on your behalf from notification through assessment and settlement."}], "heading": "How Triple H Helps You Apply What You Learn"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "7d175b7a-b679-4a79-80fa-2fa3fb42fd92", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Clear answers to common insurance questions and terms you may encounter when comparing cover, reviewing a policy or dealing with a claim.", "items": [{"answer": "The premium is the amount you pay for an insurance policy. It can vary according to the type of cover, the risk being insured, the limits selected, deductibles, underwriting information and the insurer’s terms. Triple H compares suitable insurers and explains the differences before you choose.", "question": "Q1 – What is an insurance premium?"}, {"answer": "A deductible, sometimes called an excess, is the amount of a covered loss that you are responsible for before the insurer pays the remaining amount, subject to the policy terms. Different policies may apply different deductibles, so we explain them when comparing your options.", "question": "Q2 – What is a deductible or excess?"}, {"answer": "A policy limit is the maximum amount the insurer will pay under a particular section of cover or for a particular type of claim, subject to the policy wording. Some policies also contain sub-limits for specific benefits or losses.", "question": "Q3 – What is a policy limit?"}, {"answer": "The sum insured is the value or amount stated in the policy for insured property or another insured interest. Using an inappropriate value can contribute to underinsurance, so the basis of valuation should be understood before cover is arranged.", "question": "Q4 –  What is a sum insured?"}, {"answer": "An exclusion identifies a circumstance, cause of loss, activity or type of damage that the policy does not cover. Exclusions vary between policies and insurers, which is why Triple H identifies and explains relevant differences before placement.", "question": "Q5 – What is an exclusion?"}, {"answer": "An endorsement is a written amendment to an insurance policy that adds, removes or changes part of the standard cover or policy wording. Endorsements can materially affect how a policy responds and should be reviewed together with the main wording.", "question": "Q6 – What is an endorsement?"}, {"answer": "Underwriting is the insurer’s process of assessing a risk and deciding whether to insure it, at what premium and on what terms, limits, deductibles or conditions. Triple H presents the required information to suitable insurers and compares the terms they offer.", "question": "Q7 – What is underwriting?"}, {"answer": "Indemnity generally refers to restoring an insured, financially, to the position they were in immediately before a covered loss, subject to the policy basis, limits, deductibles and other terms. The way indemnity is calculated can differ depending on the type of insurance.", "question": "Q8 – What does indemnity mean in insurance?"}, {"answer": "Underinsurance occurs when an insured value or level of cover is lower than the actual exposure or value that should have been insured. Depending on the policy, this can reduce the amount payable after a loss, including in some partial-loss situations.", "question": "Q9 – What is underinsurance?"}, {"answer": "The policy wording is the contractual document that sets out what the insurance covers, its definitions, limits, exclusions, conditions and other terms. Triple H reviews relevant wording and explains material differences before you select an option.", "question": "Q10 – What is a policy wording?"}, {"answer": "Compare more than the premium. Look at the insurer, cover, limits, deductibles or excesses, exclusions, conditions and other terms that can affect how the policy responds. Triple H compares suitable options and explains the meaningful differences before you choose.", "question": "Q11 – What should I compare before choosing insurance in Lebanon?"}, {"answer": "Review your cover at renewal and whenever something important changes in your personal, family or business circumstances. Triple H reviews those changes and arranges any necessary adjustments with the insurer.", "question": "Q12 – When should I review my insurance cover?"}], "heading": "Insurance Questions & Terms Explained", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "305577fe-4f18-486e-a0b2-aeb9a7438c0d", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "2d96839f-b2d0-4fc6-b60a-0fd97e6c0873", "type": "container", "visible": true, "children": [{"id": "6ba140f7-695f-4f36-b634-a978baa45f58", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Have a Question About Your Insurance?", "level": 2}, "visible": true}, {"id": "f2df0a7e-6d20-4aa9-9dc8-7fdbca4bc569", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Whether you are comparing policies, reviewing existing cover, preparing for renewal or dealing with a claim, speak with Triple H for clear guidance on what matters and what to do next."}, "visible": true}, {"id": "d80cb724-fe8f-4e50-8680-de3dea0aa585", "type": "button", "content": {"href": "/en/contact", "label": "Contact Triple H", "variant": "inverse"}, "visible": true}, {"id": "d5fa5483-05df-45a0-b450-1048fcf45454", "type": "button", "content": {"href": "/en/solutions", "label": "Explore Insurance Solutions", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('10000000-0000-0000-0000-000000000003', 'Insurance Solutions | Triple H Insurance Broker', 'en/solutions', '2026-09-26 19:43:14.251562+00', '{"Title": "Insurance Solutions in Lebanon | Triple H Insurance Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Insurance for Individuals, Families & Businesses | Triple H", "ImageUrl": "", "Description": "Explore personal, family, business and specialist insurance solutions arranged around your needs by Triple H Insurance Broker."}, "Description": "Explore health, life, motor, home, business and specialist insurance in Lebanon. Triple H compares suitable insurers and arranges cover around your needs.", "CanonicalUrl": "https://triplehbroker.com/en/solutions"}', '2026-08-16 20:59:01.341949+00', false, true, 'en', 'fc15e60b-9973-38e9-7073-c12f7d01f4c2', 'solutions', '{"type": "page", "children": [{"id": "11000000-0003-0001-0000-000000000001", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "cinematic-tall", "bordered": false}, "content": {"intro": "From personal and family protection to business and specialist risks, our team approaches suitable insurers, compares the available offers and explains the cover, limits, conditions, exclusions and price clearly before arranging the policy.", "items": [], "eyebrow": "INSURANCE SOLUTIONS", "heading": "Insurance solutions for individuals, families and businesses in Lebanon", "imageAlt": "Insurance advisor meeting with a client", "mobileImageUrl": "/uploads/20260924211631-f077f335d69d4ff7b34918432416a6d4.webp", "desktopImageUrl": "/uploads/20260924210420-23bddb5c34b34487b2acf157cfa46b5a.webp"}, "visible": true, "position": 0, "settings": {"sectionType": "hero-banner"}}, {"id": "f4ee005b-1311-4a8e-b3a8-7a4dc757e3b9", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Insurance for your health, family, vehicle, travel and other personal needs, arranged around your circumstances and the protection that matters to you.", "items": [{"href": "/en/solutions/health", "title": "Health Insurance", "summary": "Medical insurance for individuals and families, with cover for hospital treatment, outpatient care and other healthcare needs according to the selected policy and insurer terms.", "imageAlt": "", "imageUrl": "/uploads/20260925160942-71dafadce2b94c07b8c90a8ef32a794f.webp", "linkLabel": "Explore Health Insurance"}, {"href": "/en/solutions/life", "title": "Life & Family Protection", "summary": "Life insurance and family protection for death, critical illness, disability and personal accident, with selected plans also supporting education, retirement and other long-term financial needs.", "imageAlt": "", "imageUrl": "/uploads/20260925162142-b76192ddfba5445ca80b6540d294e37d.webp", "linkLabel": "Explore Life & Family Protection"}, {"href": "/en/solutions/motor", "title": "Motor Insurance", "summary": "Motor insurance for private vehicles, including compulsory bodily injury, third-party liability, all-risks cover, total loss and other protection depending on the selected policy.", "imageAlt": "", "imageUrl": "/uploads/20260925163129-a8a2f1de39e34aaeae30aec96f1a196e.webp", "linkLabel": "Explore Motor Insurance"}, {"href": "/en/solutions/home", "title": "Home Insurance", "summary": "Home insurance for your property, contents and personal belongings, with protection that can include fire, water damage, theft, liability and other covered household risks.", "imageAlt": "", "imageUrl": "/uploads/20260925163459-aa3b773540174334acb8b806c141d4c7.webp", "linkLabel": "Explore Home Insurance"}, {"href": "/en/solutions/travel", "title": "Travel Insurance", "summary": "Travel insurance for short, extended or frequent travel, including emergency medical care, trip cancellation or interruption, luggage-related risks, travel delays and other travel protection.", "imageAlt": "", "imageUrl": "/uploads/20260925164107-c4c19666ac8e47158fd19af72390c823.webp", "linkLabel": "Explore Travel Insurance"}, {"href": "/en/contact", "title": "Pet Insurance", "summary": "Pet insurance with protection that can include veterinary treatment, accident-related care, illness-related expenses and other eligible healthcare costs, depending on the selected policy.", "imageAlt": "", "imageUrl": "/uploads/20260925164419-5dfe2dfce4c34fddbe89443c960cc3a5.webp", "linkLabel": "Enquire"}], "heading": "Personal & Family Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "da725f6a-6a54-4007-b89f-a101017089ac", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Insurance for businesses, employees, vehicles, property and operational risks, arranged around how your organisation works and what it needs to protect.", "items": [{"href": "/en/solutions/commercial-property", "title": "Commercial Property Insurance", "summary": "Commercial property insurance for buildings, offices, contents, stock and equipment, with protection against fire, burglary, accidental damage and other covered property risks.", "imageAlt": "", "imageUrl": "/uploads/20260925165803-0f82427f23034b749b9863e756fe641f.webp", "linkLabel": "Explore Property Insurance"}, {"href": "/en/solutions/group-health", "title": "Group Health Insurance", "summary": "Health insurance for employees and their families, with cover that can include hospital treatment, outpatient care and other medical benefits depending on the selected plan.", "imageAlt": "", "imageUrl": "/uploads/20260925170216-9bff3b762e9740faab6bd11deda187cb.webp", "linkLabel": "Explore Group Health Insurance"}, {"href": "/en/solutions/group-life", "title": "Group Life Insurance", "summary": "Group life insurance providing financial protection for employees’ families in the event of death, with additional insured benefits available depending on the selected group policy.", "imageAlt": "", "imageUrl": "/uploads/20260925192620-b216d9f2341c47d9907ae20b43529fa8.webp", "linkLabel": "Explore Group Life Insurance"}, {"href": "/en/solutions/commercial-motor-fleet", "title": "Commercial Motor & Fleet Insurance", "summary": "Motor insurance for company vehicles and fleets, with protection that can include all-risks cover, third-party liability, total loss and other commercial vehicle risks.", "imageAlt": "", "imageUrl": "/uploads/20260925193430-6299faa660334686aca8480a8ce28a36.webp", "linkLabel": "Explore Commercial Motor & Fleet Insurance"}, {"href": "/en/solutions/commercial-liability-insurance", "title": "Liability Insurance", "summary": "Liability insurance protecting businesses against covered claims for injury, property damage and other third-party liabilities arising from their operations.", "imageAlt": "", "imageUrl": "/uploads/20260925194949-b0a71896953c4c93b05bfc686fc0d146.webp", "linkLabel": "Explore Liability Insurance"}, {"href": "/en/solutions/workmen-compensation", "title": "Workmen Compensation Insurance", "summary": "Insurance for work-related injuries and occupational accidents, helping protect employees and businesses against covered medical expenses, compensation and other employer liabilities.", "imageAlt": "", "imageUrl": "/uploads/20260925200127-02b747cba35e4c1d8231cb1720a79655.webp", "linkLabel": "Explore Workmen Compensation Insurance"}, {"href": "/en/solutions/marine-insurance", "title": "Marine Insurance", "summary": "Marine insurance for vessels and other marine risks, with protection that can include hull damage, machinery, third-party liability and other covered marine exposures.", "imageAlt": "", "imageUrl": "/uploads/20260925201227-97b80d95c4be45bd9692b31eaea793fb.webp", "linkLabel": "Explore Marine Insurance"}, {"href": "/en/solutions/cargo-insurance", "title": "Cargo Insurance", "summary": "Cargo insurance protecting goods in transit by sea, air or road against covered loss or damage during transportation, including other transit-related risks depending on the selected policy.", "imageAlt": "", "imageUrl": "/uploads/20260925202036-22647f5fee8843cfa1cfb572dbdca107.webp", "linkLabel": "Explore Cargo Insurance"}, {"href": "/en/solutions/fidelity-guarantee-insurance", "title": "Fidelity Guarantee Insurance", "summary": "Insurance protecting businesses against covered financial losses caused by employee fraud, theft or dishonesty, depending on the selected policy terms and limits.", "imageAlt": "", "imageUrl": "/uploads/20260925202626-1b0e5a6646e149ca839398a50a4d4a0a.webp", "linkLabel": "Explore Fidelity Guarantee Insurance"}], "heading": "Business & Employee Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "9c3a781c-a666-402c-841f-11d8d00bd138", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Insurance for professional, management, cyber and workforce-related risks, arranged around the responsibilities, activities and exposures involved.", "items": [{"href": "/en/contact", "title": "Medical Malpractice Insurance", "summary": "Professional liability insurance for doctors and other healthcare professionals, protecting against covered claims related to errors or omissions in their professional work.", "imageAlt": "", "imageUrl": "/uploads/20260925205300-1ddec19da0464362a31c579526512594.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Professional Indemnity Insurance", "summary": "Professional liability insurance for consultants, lawyers, engineers, accountants, IT professionals and other specialists, protecting against covered claims related to errors or omissions in their professional services.", "imageAlt": "", "imageUrl": "/uploads/20260926185850-be92ca735278412ca827f46c64da7d75.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Cyber Insurance", "summary": "Cyber insurance for businesses facing digital and data-related risks, with protection that can include cyber incidents, data breaches, liability and other covered technology-related losses.", "imageAlt": "", "imageUrl": "/uploads/20260926193428-1b60cfe9ca11495c895cc47822383797.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Directors & Officers Insurance", "summary": "Liability insurance for company directors and officers, protecting against covered claims related to decisions, actions or responsibilities carried out in their management roles.", "imageAlt": "", "imageUrl": "/uploads/20260926193458-644892ab1bb042fc96aac73cde8403bd.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Expat / Foreign Workers Insurance", "summary": "Insurance for expatriates and foreign workers, with protection that can include hospital and medical expenses following a covered work-related accident, as well as death or disability benefits where applicable.", "imageAlt": "", "imageUrl": "/uploads/20260926194305-c1ba6eed35f84c578bd9520938dc06f6.webp", "linkLabel": "Enquire"}], "heading": "Professional & Specialist Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "5a355cdc-76fe-4d70-9c43-909661336bfd", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Additional cover for specific risks, assets and activities, from specialist motor and liability needs to valuables, money, equipment and construction risks.", "items": [{"text": "Rental Motor Insurance"}, {"text": "School Liability Insurance"}, {"text": "Jewellery & Valuables Protection"}, {"text": "Cash in Safe"}, {"text": "Cash in Transit"}, {"text": "Contractors All Risks"}, {"text": "Erection All Risks"}, {"text": "Contractors Plant & Machinery"}, {"text": "Electronic Equipment Protection"}, {"text": "Orange Card"}, {"text": "Plate Glass Insurance"}], "heading": "More insurance covers we arrange"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "66dd3a16-9502-4471-a4db-321d36a725ab", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "e01b684d-1c50-4f33-9cfe-95845a4ecbf6", "type": "container", "visible": true, "children": [{"id": "27da4415-937f-4429-94ec-9b1574cd614d", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Arrange your insurance with confidence.", "level": 2}, "visible": true}, {"id": "c8138107-57c1-4b36-b4d5-47d3baed377b", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us what you need to protect, and our team will compare suitable options, explain the differences clearly and arrange the cover that fits your needs."}, "visible": true}, {"id": "915cdbc8-897f-4871-9124-2d4d522f5ed7", "type": "button", "content": {"href": "/en/quote", "label": "Get an Instant Quote", "variant": "inverse"}, "visible": true}, {"id": "c34344c1-7e40-490e-ad86-41c106c1ff26", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "solutions", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('983a73e8-de50-43a6-b549-12df727c080a', 'Group Health Insurance in Lebanon | Triple H', 'en/solutions/group-health', '2026-09-24 11:50:16.64185+00', '{"Title": "Group Health Insurance in Lebanon | Triple H", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Group Health Insurance in Lebanon | Triple H", "ImageUrl": null, "Description": "Provide employees and eligible dependents with group health insurance arranged by Triple H around your company’s medical benefit needs."}, "Description": "Group health insurance in Lebanon for employees and dependents, with hospital, outpatient and optional benefits. Triple H compares insurers and arranges cover.", "CanonicalUrl": "https://triplehbroker.com/en/solutions/group-health"}', '2026-09-12 13:52:28.74982+00', false, false, 'en', 'ed2cc62b-2e0b-46ea-b35f-fec7f8c4ea18', 'builder', '{"type": "page", "children": [{"id": "e21fcc45-cd6c-4dba-bb67-b379dfda347d", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Provide your employees and eligible dependents with medical insurance structured around your workforce, hospital network, benefits and level of cover.", "items": [{"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}], "eyebrow": "BUSINESS & EMPLOYEE INSURANCE", "heading": "Group Health Insurance in Lebanon", "imageAlt": "", "mobileImageUrl": "", "desktopImageUrl": ""}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "c85c823b-d23c-4e1e-a11c-f01b7a0d854f", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Group health insurance provides medical cover for employees and eligible dependants under one company plan. We assess the workforce, approach suitable insurers in the Lebanese market, compare benefits, hospital networks and terms, and arrange the plan around the company’s needs.", "eyebrow": "GROUP HEALTH INSURANCE", "heading": "What is group health insurance?", "audience": "Companies, SMEs, institutions and other employers that want to provide employees with structured medical benefits and manage their health insurance under one group arrangement.", "buttonHref": "/en/contact", "buttonLabel": "Request a quote", "audienceHeading": "Who it is for"}, "visible": true, "children": [], "settings": {"sectionType": "solution-introduction"}}, {"id": "e524a27e-cb6d-4662-a1f9-e9585621afe4", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "451c4879-1d93-40b0-b515-918eb26eea6b", "type": "container", "visible": true, "children": [{"id": "5a404ab3-9157-49bc-8497-00aede404113", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "How can a group health plan be structured?", "level": 2}, "visible": true}, {"id": "93e18037-ce89-47b0-882c-27bd9296d08a", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "The plan can be arranged around the size of the workforce, who needs to be covered and the level of medical protection the company wants to provide."}, "visible": true}, {"id": "750220ed-bbd4-4aed-ade9-6ae01eeb7765", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "42546ac0-4a58-4559-8920-c59fd73bed65", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "1af56473-b90e-42c3-85d7-ceca77faa8eb", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Employees", "level": 3}, "visible": true}, {"id": "0e21f016-f83a-457a-94d9-3458832638d7", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Medical cover for eligible employees under one company policy."}, "visible": true}]}, {"id": "6e763884-573b-41fd-8545-4e69a3a70058", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "aa3efc97-4860-419f-b29f-0b0f4f036306", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Employees & Dependents", "level": 3}, "visible": true}, {"id": "1675161a-0a27-48fd-b4ac-0ed07cc7ba9c", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Cover can also include eligible spouses and children, depending on the company’s requirements and insurer terms."}, "visible": true}]}, {"id": "744d495f-00a9-452e-bebd-17095d957625", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "9d0c682f-bd57-4960-bd2f-00b6d596114f", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Different Employee Classes", "level": 3}, "visible": true}, {"id": "f31f1597-7488-4cd4-a5ad-d666a41695d8", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Different benefit levels or hospitalization classes can be arranged for defined employee categories within the same group."}, "visible": true}]}, {"id": "013ecf6d-104f-4be9-8d61-55b0d33ef7cc", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "d089946e-0732-4424-bc62-501a689dab05", "type": "heading", "content": {"text": "Core & Optional Benefits", "level": 3}, "visible": true}, {"id": "872354e8-8c3f-440b-a434-4272b08d9617", "type": "text", "content": {"text": "The company can combine essential medical protection with additional benefits according to its budget and employee needs."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "48291a28-cc73-4ac1-89f0-5b323063c54e", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"help": "We identify the benefits the workforce needs, compare suitable insurers in the Lebanese market and arrange the plan around the hospital network, limits, optional benefits and terms that matter to the company.", "intro": "A group health plan can combine core medical protection with additional benefits according to the company’s needs, workforce and selected level of cover.", "items": [{"text": "Hospital admission and surgery"}, {"text": "Emergency medical treatment"}, {"text": "Diagnostic, scans and laboratory tests"}, {"text": "Doctor consultations and specialist visits"}, {"text": "Prescription medicines"}, {"text": "Physiotherapy and outpatient treatment"}, {"text": "Maternity and childbirth benefits"}, {"text": "Dental care"}, {"text": "Optical and vision care"}, {"text": "Treatment for chronic and ongoing medical conditions, subject to the plan terms"}], "heading": "What can group health insurance cover?", "helpHeading": "How Triple H helps"}, "visible": true, "children": [], "settings": {"sectionType": "coverage-details"}}, {"id": "8294d847-e829-4cb9-8704-62daff051e7a", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "The right plan depends on more than price. The insurer, hospital network, benefits, limits, administration and policy terms all affect the protection employees receive.", "items": [{"text": "The insurer’s reputation, financial strength and reliability"}, {"text": "Hospital network and geographic coverage"}, {"text": "TPA service and speed of approvals"}, {"text": "Hospitalization class, annual limits and benefit limits"}, {"text": "Outpatient care, prescription medicines, dental, and optical benefits"}, {"text": "Pre-existing, maternity and chronic condition terms"}, {"text": "NSSF coordination and the basis of medical cover"}, {"text": "Employee and dependent eligibility requirements"}, {"text": "Medical underwriting and enrolment requirements"}, {"text": "Premium, deductibles, exclusions and other policy conditions"}], "heading": "What to compare before choosing a group health plan"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "37c3d27b-810a-43c4-9e12-a00a859bf595", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We assess your workforce, structure the benefits and compare suitable insurers in Lebanon before arranging the selected plan.", "items": [{"body": "We review the number of employees, eligible dependents, age profile and the level of medical protection the company wants to provide.", "title": "Review the group profile"}, {"body": "We define the hospitalization class, medical limits, outpatient benefits and any additional protection required for the group.", "title": "Structure the benefits"}, {"body": "We approach suitable insurers in the Lebanese market and compare their benefits, hospital networks, underwriting terms, exclusions, reputation and price.", "title": "Compare suitable insurers"}, {"body": "We explain the differences, negotiate with insurers where appropriate and arrange the selected group health plan for the company.", "title": "Arrange the plan"}], "layout": "grid", "eyebrow": "", "heading": "How we arrange your group health insurance"}, "visible": true, "children": [], "settings": {"sectionType": "steps"}}, {"id": "7d744ebe-153c-48ef-ae09-b745bef145c8", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "When an insured employee or dependent needs support using the plan, contact us and we coordinate the required arrangements and approvals.", "items": [{"text": "For hospital admission, tests, scans, physiotherapy or other services requiring approval, we coordinate with the medical provider, TPA and insurer to secure the required pre-approval."}, {"text": "If any issue arises, we handle the communication and follow-up on behalf of the company and insured member, helping the treatment proceed without unnecessary delay."}, {"text": "For reimbursement claims, we guide the required documents, submit the claim where applicable and follow it through to settlement under the policy terms."}], "heading": "What to do when an employee needs treatment"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "3179abcd-ae6a-47ac-a24a-9d1aa10da012", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Answers to common questions about arranging and managing medical insurance for employees.", "items": [{"answer": "Yes. We handle employee additions and removals and arrange the required policy updates with the insurer.", "question": "Q1 – Can employees be added or removed during the policy year?"}, {"answer": "Yes. The contribution can be structured according to the company’s employee benefits policy and the selected group arrangement.", "question": "Q2 – Can the company pay all or part of the premium?"}, {"answer": "The plan can be arranged with NSSF coordination or on another basis, depending on the company, employees and insurer terms. We compare how each option affects the cover and cost.", "question": "Q3 – How does NSSF affect group health insurance?"}, {"answer": "Coverage depends on the insurer, group profile and policy terms. We compare the available conditions and explain any restrictions before the plan is arranged.", "question": "Q4 – Can pre-existing or chronic conditions be covered?"}, {"answer": "Not always. Requirements vary by insurer, group size and employee profile, and some group arrangements may offer simplified enrolment or underwriting.", "question": "Q5 – Is medical underwriting required for every employee?"}, {"answer": "We usually need the number of employees and dependents, ages, requested benefits, hospitalization class, current insurance details and claims history where available.", "question": "Q6 – What information do you need for a quotation?"}, {"answer": "Yes. We can review the current benefits, network, limits, exclusions, underwriting terms and premium, then compare suitable alternatives in the Lebanese market.", "question": "Q7 – Can you review an existing group health plan?"}, {"answer": "Yes. Depending on the plan, medical cover can be arranged for Lebanon only, regional territories or worldwide. We compare the available geographic options according to where employees travel and work.", "question": "Q8 – Can employees be covered while travelling outside Lebanon?"}, {"answer": "Yes, depending on the country, employee location and insurer requirements. For companies with employees or branches abroad, we can coordinate regional or international medical insurance arrangements suited to the workforce.", "question": "Q9 – Can employees based outside Lebanon be covered?"}, {"answer": "Minimum group requirements vary by insurer and plan. We review the company size and employee profile and identify the suitable group options available.", "question": "Q10 – Is there a minimum number of employees for group health insurance?"}], "heading": "Group Health Insurance FAQs", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "2f024ff9-f6e9-48d9-8052-9b636ebd3584", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Protect your employees, property, vehicles, goods, liabilities and other business risks with insurance arranged around your operations.", "heading": "Explore more business insurance", "buttonHref": "/en/solutions/business", "buttonLabel": "Explore Business Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "callout"}}, {"id": "3c4df80a-0a81-4cd0-afc6-92a15a4b5ac3", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "7845609d-8f1e-42af-98c9-ac406dde6d84", "type": "container", "visible": true, "children": [{"id": "21f15c7e-aaca-4d72-88ea-b19ff5fa759c", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Provide your employees with the right medical cover.", "level": 2}, "visible": true}, {"id": "fa197ffe-246b-433b-a060-b4a63c2f2149", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us about your workforce and the benefits you want to provide. We’ll compare suitable insurers in the Lebanese market and arrange the group health plan that fits your company."}, "visible": true}, {"id": "42d91fd6-a0e4-4813-b26b-f72e501901a2", "type": "button", "content": {"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, "visible": true}, {"id": "7011e971-bf93-4c2f-924b-677b6b25e04b", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('0320724c-bd9c-40ea-943e-57a595cafbbf', 'Group Life Insurance in Lebanon | Triple H', 'en/solutions/group-life', '2026-09-24 11:51:22.119064+00', '{"Title": "Group Life Insurance in Lebanon | Triple H Insurance Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Group Life Insurance in Lebanon | Triple H Insurance Broker", "ImageUrl": null, "Description": "Provide employees with life, disability and long-term financial benefits through group life insurance arranged by Triple H around your company’s needs."}, "Description": "Group life insurance in Lebanon for employee life, disability, critical illness and long-term benefits. Triple H compares insurers and arranges suitable plans.", "CanonicalUrl": "https://triplehbroker.com/en/solutions/group-life"}', '2026-09-18 13:16:00.909531+00', false, false, 'en', '7e6b60ec-5bc5-44ff-92dc-7f00610044e1', 'builder', '{"type": "page", "children": [{"id": "e5682e24-7abb-4225-85c8-2989bbe53417", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Provide employees with life protection and long-term financial benefits, with cover structured around your workforce and the benefits your company wants to provide.", "items": [{"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}], "eyebrow": "BUSINESS & EMPLOYEE INSURANCE", "heading": "Group Life Insurance in Lebanon", "imageAlt": "", "mobileImageUrl": "", "desktopImageUrl": ""}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "930a48a4-c471-4396-8177-9e5ab4424c3b", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Group life insurance provides financial protection for employees and their beneficiaries through life, disability and other selected benefits. It can also include savings, retirement or other long-term financial benefits depending on the plan. We assess the workforce, compare suitable insurers in the Lebanese market and arrange the benefits around the company’s needs.", "eyebrow": "GROUP LIFE INSURANCE", "heading": "What is group life insurance?", "audience": "Companies, SMEs, institutions and other employers that want to provide employees with life and disability protection as part of their benefits package.", "buttonHref": "/en/contact", "buttonLabel": "Request a quote", "audienceHeading": "Who it is for"}, "visible": true, "children": [], "settings": {"sectionType": "solution-introduction"}}, {"id": "f38c8d43-9efa-4f67-aafb-f49ce50a5db7", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "9ea7cd3c-eff4-489a-a283-d00ff16fc56f", "type": "container", "visible": true, "children": [{"id": "542977ea-3157-42dc-8ef3-4aaa5f5e4f10", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "How can employee life benefits be structured?", "level": 2}, "visible": true}, {"id": "b3195407-01b5-43e3-a21c-cc33ef212317", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "The company can combine protection with longer-term financial benefits according to its workforce, objectives and budget."}, "visible": true}, {"id": "236b5ded-be5d-4008-b21f-ecb0d9337803", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "bf5ecc1d-dcd9-4d17-9508-8fbfb37c3b12", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c741fe81-63db-4800-91d0-d2e11e446a2a", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Life & Disability Protection", "level": 3}, "visible": true}, {"id": "490646ee-0e56-438b-8bd3-9f86635f25ae", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Financial protection for employees and their beneficiaries in the event of death, disability or other covered events."}, "visible": true}]}, {"id": "1e8d1dac-2b4d-42e1-8766-42b408a9436f", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "dc681dfe-164e-4c1d-860a-c96df1145f4a", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Savings & Investment", "level": 3}, "visible": true}, {"id": "056dd5e4-021b-4009-a52c-1d9e329dc9e9", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Long-term savings or investment benefits can be arranged to help employees build financial value while maintaining life protection."}, "visible": true}]}, {"id": "4f889d68-2008-4dd3-91a4-61aedf2f1cc8", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "81f8e373-ddc3-4e7b-8218-55339c8b7cb8", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Retirement & Pension", "level": 3}, "visible": true}, {"id": "20dfad9f-16df-4c44-8b32-9e07e6ade1e1", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Structured retirement benefits can help employees build funds for later life while strengthening the company’s employee benefits package."}, "visible": true}]}, {"id": "53a7eb9d-7ced-4a10-88fa-e51780eafa44", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "0c7f2104-06b3-45e2-9159-9100df56681b", "type": "heading", "content": {"text": "Education Protection", "level": 3}, "visible": true}, {"id": "f8e5e12e-d88d-4b97-b395-5cd4436f4153", "type": "text", "content": {"text": "Education-focused benefits can help build funds for schooling or university costs, with additional protection available if death, disability or critical illness occurs."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "c03e922a-7883-4f1e-a674-a82b882771aa", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "aec84a70-0f4c-4e56-8bc0-8f76ecdae58d", "type": "container", "visible": true, "children": [{"id": "aa2865f2-3b09-4bf0-8a5b-9faefc4fb84a", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Group Life Insurance and financial protection plans", "level": 2}, "visible": true}, {"id": "88fd25a8-bcc0-43e8-9d27-82ab394c8b37", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Choose from protection, savings and long-term planning solutions designed for your employees'' different financial needs and life stages."}, "visible": true}, {"id": "9259d9ae-df00-4b77-b018-2f19d7f55d88", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "ae568be0-2ae7-42c3-ac68-b4865263c562", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "55a0b9cf-b328-4fbe-a510-f31f8a2ad8e1", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Personal Accident Insurance", "level": 3}, "visible": true}, {"id": "530bac7c-afb9-417a-a4a2-6c358fa182f8", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Provides financial compensation following an accident, including benefits for accidental death, permanent total or partial disability, and weekly income support during temporary total disability, with other benefits available depending on the plan."}, "visible": true}]}, {"id": "067ac7e4-a95a-4756-9fbf-cbec6047b606", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c1cedd5a-b5eb-44d1-ad42-a8efa9a72900", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Critical Illness Insurance", "level": 3}, "visible": true}, {"id": "a1a3a387-ae9f-48a3-a1fe-27ad9d1418bb", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Provides financial compensation following diagnosis of a covered critical illness, helping cover lost income and other unexpected expenses during treatment and recovery, with benefits and conditions depending on the selected plan."}, "visible": true}]}, {"id": "40cc48f4-02e0-4b41-a8d5-c2f66d79f0c3", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "4e70d4d3-040b-4d18-88b6-e4b8c8c994e1", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Refundable Life Insurance", "level": 3}, "visible": true}, {"id": "34cbe139-b614-4d44-abe5-08773941db07", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Provides life protection during the policy term, with financial benefits in case of death or permanent total disability, while allowing the premiums paid to be returned at maturity if the insured outlives the term, subject to the selected plan."}, "visible": true}]}, {"id": "e34627b3-a7cd-49c5-8805-823da39d5df7", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "f6c6b141-ba34-4112-9e66-74ab8256de7a", "type": "heading", "content": {"text": "Education Plan", "level": 3}, "visible": true}, {"id": "b71be12d-a04d-4f0c-9ac1-94f7f6ba1a70", "type": "text", "content": {"text": "Builds funds for your employees'' children''s future education through long-term savings and investments, while protection features can help keep the plan on track if death, permanent total disability or covered critical illness affects the person funding it, usually a parent."}, "visible": true}]}, {"id": "f70f1250-df94-4f79-802c-5aefabb69570", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "3cedb4f0-a24a-4ed8-ab37-562038a57873", "type": "heading", "content": {"text": "Retirement Plan", "level": 3}, "visible": true}, {"id": "7a044772-bb08-44d1-b0a5-0a85139b4f3e", "type": "text", "content": {"text": "Builds funds specifically for retirement through long-term contributions, with the option to receive the accumulated value as retirement capital or income, while protection benefits can help keep the plan on track if death or permanent total disability occurs."}, "visible": true}]}, {"id": "6ace0467-8f3b-4df3-b26b-a3d7f05ef4d3", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "a1f35629-5e1a-4890-a012-89c5361dc439", "type": "heading", "content": {"text": "Investment Plans", "level": 3}, "visible": true}, {"id": "5a822a27-83d8-41c5-8f24-1e1e37e08e61", "type": "text", "content": {"text": "Provides long-term access to selected global investment funds through an insurance-based plan, allowing your employees to build and diversify savings according to their goals and risk profile. Investment values can increase or decrease depending on fund performance."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "1cea1311-d979-49be-adcd-6ed1d36b851d", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"help": "We structure the benefits and insured amounts around the company’s workforce and objectives, then compare suitable insurers in the Lebanese market by cover, definitions, limits, exclusions, underwriting and price before arranging the selected plan.", "intro": "Group life insurance can protect employees and their families against the financial impact of death, disability and serious illness. Depending on the plan, additional benefits can also protect ongoing savings, retirement or education commitments.", "items": [{"text": "Death from natural or accidental causes"}, {"text": "Additional accidental death benefit"}, {"text": "Permanent total disability"}, {"text": "Permanent partial disability"}, {"text": "Critical illness lump-sum benefit"}, {"text": "Terminal illness benefit"}, {"text": "Waiver of future premiums following certain covered events"}, {"text": "Continuation of planned savings, retirement or education contributions following certain covered events"}, {"text": "Education or schooling benefits following death, disability or critical illness"}, {"text": "Other life and disability benefits available under the selected plan"}], "heading": "What can group life insurance cover?", "helpHeading": "How Triple H helps"}, "visible": true, "children": [], "settings": {"sectionType": "coverage-details"}}, {"id": "34853666-0b11-4b2d-bc36-7c651c3dfbb9", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "The right plan depends on the protection provided, how benefits are calculated and any savings, investment or retirement features included.", "items": [{"text": "The insurer’s reputation, financial strength and reliability"}, {"text": "Fixed benefits, salary multiples and benefit levels by employee class"}, {"text": "Death, disability and critical illness definitions and limits"}, {"text": "Employee eligibility, age limits and underwriting requirements"}, {"text": "Worldwide cover and territorial conditions"}, {"text": "Savings, investment and maturity benefits"}, {"text": "Retirement benefits and contribution structure"}, {"text": "Investment options, charges and whether returns are guaranteed or market-linked"}, {"text": "Education and other additional employee benefits"}, {"text": "Premium levels and how contributions may increase over time"}, {"text": "Exclusions and other policy terms and conditions"}], "heading": "What to compare before choosing a group life plan"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "98ba9d5b-dfb2-4317-acb0-4c9025e0972f", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We define the protection and long-term benefits your company wants to provide, compare suitable insurers in Lebanon and arrange the selected plan.", "items": [{"body": "We review the number of employees, age profile, employee categories and the benefits the company wants to provide.", "title": "Review the group profile"}, {"body": "We define the life, disability, critical illness and any savings, retirement or education benefits required for the group.", "title": "Structure the benefits"}, {"body": "We approach suitable insurers in the Lebanese market and compare their cover, benefit structures, underwriting, exclusions, investment terms and price.", "title": "Compare suitable insurers"}, {"body": "We explain the differences, negotiate with insurers where appropriate and arrange the selected group life plan for the company.", "title": "Arrange the plan"}], "layout": "grid", "eyebrow": "", "heading": "How we arrange your group life insurance"}, "visible": true, "children": [], "settings": {"sectionType": "steps"}}, {"id": "43789137-e97f-468d-a3ac-395a232e66ac", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Contact us as soon as possible. We coordinate the claim, required documents and insurer communication on behalf of the company, employee or beneficiary.", "items": [{"text": "For death, disability or critical illness claims, we explain the documents required and help prepare the medical, employment and supporting information needed by the insurer."}, {"text": "We submit and follow the claim, handle insurer questions and work to secure the covered benefit due under the policy."}, {"text": "We remain involved until the claim is concluded and keep the company and beneficiary informed throughout."}], "heading": "What to do when a life or disability claim occurs"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "f3a8f2eb-08c7-4062-97d6-d5934f36efa4", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Answers to common questions about arranging and managing life, disability and long-term employee benefits.", "items": [{"answer": "Yes. We arrange employee additions and removals and update the plan with the insurer as the workforce changes.", "question": "Q1 – Can employees be added or removed during the policy year?"}, {"answer": "Yes. Benefits can be structured by employee class, position, salary level or another agreed basis.", "question": "Q2 – Can different employee categories have different benefit levels?"}, {"answer": "The insured amount can be a fixed benefit, a multiple of salary or another structure agreed between the company and insurer.", "question": "Q3 – How is the life insurance benefit calculated?"}, {"answer": "Before the policy is issued, each insured employee designates one or more beneficiaries. If a covered death occurs, the benefit is paid to the designated beneficiary or beneficiaries according to the policy terms.", "question": "Q4 – Who receives the life insurance benefit?"}, {"answer": "Not always. Underwriting requirements depend on the insurer, group size, benefit amount, employee profile and plan structure.", "question": "Q5 – Is medical underwriting required for every employee?"}, {"answer": "Yes, depending on the countries involved and insurer terms. We compare the available territorial and international cover for the group.", "question": "Q6 – Can employees working or travelling outside Lebanon be covered?"}, {"answer": "Yes. Depending on the plan, the company can arrange savings, investment or retirement benefits alongside life and disability protection.", "question": "Q7 – Can savings or retirement benefits be included?"}, {"answer": "Depending on the plan, benefits may include guaranteed elements, market-linked returns or a combination of both. We explain the investment structure, charges, projected values and guarantees before the plan is arranged.", "question": "Q8 – How do investment returns work?"}, {"answer": "Yes. We can review the current benefits, insured amounts, underwriting, exclusions, investment features and cost, then compare suitable alternatives in the Lebanese market.", "question": "Q9 – Can you review an existing group life plan?"}, {"answer": "Yes. Passive war risk can be added as an additional benefit where available, providing protection for specified death or disability events related to war, subject to the insurer and policy terms.", "question": "Q10 – Can war risk protection be added?"}, {"answer": "Yes, depending on the country, employee location and insurer requirements. We can coordinate regional or international group arrangements for companies with employees or operations outside Lebanon.", "question": "Q11 – Can employees based outside Lebanon be covered?"}], "eyebrow": "", "heading": "Group Life Insurance FAQs", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "07182443-5e5f-48e2-89ba-9b2eecf9bfed", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Protect your employees, property, vehicles, goods, liabilities and other business risks with insurance arranged around your operations.", "heading": "Explore more business insurance", "buttonHref": "/en/solutions/business", "buttonLabel": "Explore Business Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "callout"}}, {"id": "13d2da92-9d1a-4959-8f5f-548c17ea4ccd", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "10f245ac-e88b-4a0f-b3ab-84b44986e897", "type": "container", "visible": true, "children": [{"id": "d966559a-6ea8-421d-930e-3a5ab01ec951", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Build stronger financial protection for your employees.", "level": 2}, "visible": true}, {"id": "4f9c63ed-0991-4ce1-a1c9-4fc4514be212", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us about your workforce and the benefits you want to provide. We’ll compare suitable insurers in the Lebanese market and arrange the group life plan that fits your company."}, "visible": true}, {"id": "cc4a8da6-f512-413e-af33-ead73ea21ab9", "type": "button", "content": {"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, "visible": true}, {"id": "2a7f13ac-8a6e-4b74-8a74-fbf7f26c2dac", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('257d1a45-da7e-484c-bf34-3f8e2279d75a', 'Marine Insurance | Triple H Insurance Broker', 'en/solutions/marine-insurance', '2026-09-24 11:58:03.532253+00', '{"Title": "Marine Insurance in Lebanon | Triple H Insurance Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Marine Insurance in Lebanon | Triple H Insurance Broker", "ImageUrl": null, "Description": "Protect your yacht, boat or commercial vessel with marine insurance arranged by Triple H Insurance Broker in Lebanon."}, "Description": "Marine insurance in Lebanon for yachts, boats and commercial vessels. Compare hull, machinery and liability cover with Triple H Insurance Broker.", "CanonicalUrl": "https://www.triplehbroker.com/en/solutions/marine-insurance"}', '2026-09-20 16:59:57.192721+00', false, false, 'en', 'ae3fca24-d65f-40f2-b899-3d8914670a71', 'builder', '{"type": "page", "children": [{"id": "481f0bfa-c00b-4893-a90d-a3e6d0ef69e2", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Protect your yacht, boat or commercial vessel against physical damage and marine liability, with cover arranged around the vessel, its use and navigation area.", "items": [{"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}], "eyebrow": "BUSINESS & EMPLOYEE INSURANCE", "heading": "Marine Insurance", "imageAlt": "", "mobileImageUrl": "", "desktopImageUrl": ""}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "1b35f015-1a18-4464-8379-227acb9e0be4", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Marine insurance can protect yachts, boats and commercial vessels against physical damage to the hull and machinery, together with marine liabilities arising from their ownership or operation. Triple H compares suitable insurers and arranges cover around the vessel, its value, use and navigation area.", "eyebrow": "MARINE INSURANCE", "heading": "What is marine insurance?", "audience": "Vessel owners and operators, yacht and pleasure-craft owners, fishing vessel owners and businesses with marine liability exposures.", "buttonHref": "/en/contact", "buttonLabel": "Request a Quote", "audienceHeading": "Who it is for"}, "visible": true, "children": [], "settings": {"sectionType": "solution-introduction"}}, {"id": "ca0b706c-9427-4b6f-9a48-d1af547e35e3", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "03f86dcf-fa16-42ee-939b-dd7306b6f41a", "type": "container", "visible": true, "children": [{"id": "748baf37-744b-4b9e-9a82-a0926466f3c5", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "How can marine insurance cover be structured?", "level": 2}, "visible": true}, {"id": "f428b5ef-d46d-480d-b2d6-88310b29191b", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Marine cover can be arranged around the vessel itself, the liabilities you need to protect against, where and how the vessel operates, and any additional extensions required."}, "visible": true}, {"id": "d07a5480-11eb-494e-8430-58e8c8b89217", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "7170cb7b-f2b9-40b3-b508-0383e0f79f64", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "97eb59d9-4679-4fe7-a3a8-d449e91bda84", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Hull & Machinery Cover", "level": 3}, "visible": true}, {"id": "271547fd-eccd-4cec-8a4f-a635bb726ce4", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Cover can protect the vessel’s hull, machinery and insured equipment against accidental physical loss or damage, subject to the policy terms and selected level of protection."}, "visible": true}]}, {"id": "5dbbe37d-39be-4dcf-812d-05e923b0de1f", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "da255d9c-fcd1-4667-ad90-e786ccc7df20", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Marine Liability Cover", "level": 3}, "visible": true}, {"id": "3c244811-1d1d-4cf8-bc0a-da85da870f7b", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Liability protection can be arranged for claims involving third parties, passengers or other vessels, with limits and scope selected according to the vessel and its use."}, "visible": true}]}, {"id": "16281797-803b-45be-a90f-3dcea92dddb2", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "9c2ebdeb-09e9-4c2d-8997-0d0966581de8", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Navigation & Vessel Use", "level": 3}, "visible": true}, {"id": "7c6c3ac0-edab-40cc-9876-3a868d23b875", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "The policy can be structured around the vessel’s declared use and agreed navigation area, whether it is operated privately, commercially, for fishing or for another insured purpose."}, "visible": true}]}, {"id": "e2f92600-f765-4e9d-86e3-f1b8b59b3e2a", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "af01a926-2c1e-430c-bc2d-b691000f05a9", "type": "heading", "content": {"text": "Additional Extensions", "level": 3}, "visible": true}, {"id": "193d6c21-2c07-4cf2-b3d2-ba8a8d1c654a", "type": "text", "content": {"text": "Additional protection may be added for risks such as personal effects, war and strikes or other marine exposures where available and required."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "bc440e2e-51eb-48d6-b257-bdea879dfa55", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"help": "We compare insurers in Lebanon , insured values, liability limits, navigation terms, deductibles and exclusions, arrange suitable cover for your vessel, and handle claims from notification through assessment and settlement.", "intro": "Depending on the vessel and policy selected, marine insurance can cover physical loss or damage to the vessel, total loss, marine liabilities and certain additional costs arising from an insured incident.", "items": [{"text": "Hull & Machinery"}, {"text": "Actual or Constructive Total Loss"}, {"text": "Collision Liability"}, {"text": "Third-Party Liability"}, {"text": "Passenger Liability, Where Included"}, {"text": "Salvage Charges & General Average"}, {"text": "Personal Effects & Onboard Equipment, Where Included"}], "heading": "What can marine insurance cover?", "helpHeading": "How Triple H helps"}, "visible": true, "children": [], "settings": {"sectionType": "coverage-details"}}, {"id": "2aee6f99-ce34-4f40-970c-51d0d0a4e5af", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "The right policy depends on more than premium. Insured values, deductibles, liability limits, navigation terms, vessel use and exclusions can all make a significant difference to the protection provided.", "items": [{"text": "Insurer reputation and marine claims settlement terms"}, {"text": "Hull and machinery cover and basis of insured value"}, {"text": "Deductibles and excesses applying to each loss"}, {"text": "Partial damage and total loss settlement terms"}, {"text": "Third-party and passenger liability limits"}, {"text": "Navigation limits and available territorial extensions"}, {"text": "Permitted vessel use and operating conditions"}, {"text": "Mooring, storage and lay-up conditions"}, {"text": "Salvage charges, general average and related insured costs"}, {"text": "War, strikes, piracy and other special-risk terms"}, {"text": "Policy terms, conditions, and exclusions"}], "heading": "What to compare before choosing marine insurance"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "dd843d93-7838-4ffb-b3ca-dd372de60bf9", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We review your vessel and how it is used, compare suitable insurers in the Lebanese market, and policy terms, then arrange and maintain the selected cover as your needs change.", "items": [{"body": "We review the vessel type, value, equipment, intended use, navigation area and usual mooring or storage arrangements.", "title": "Review Your Vessel & Use"}, {"body": "We compare suitable insurers in Lebanon by cover, insured values, liability limits, deductibles, navigation terms, exclusions and premium.", "title": "Compare Suitable Insurers"}, {"body": "We place the selected policy, confirm the insured vessel and agreed terms, and check that the policy documents and schedules reflect the cover arranged.", "title": "Arrange the Selected Cover"}, {"body": "We handle claims, relevant policy changes and renewals when the vessel, its value, use, navigation area or other insured details change.", "title": "Keep Your Cover Current"}], "layout": "grid", "heading": "How we arrange marine insurance"}, "visible": true, "children": [], "settings": {"sectionType": "steps"}}, {"id": "25ec73f0-df98-484d-a084-d3c4ebc390c5", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Contact Triple H as soon as possible after taking any necessary steps to protect people and prevent further damage. We handle the claim from notification through assessment and settlement and deal with the insurer on your behalf.", "items": [{"text": "We notify the insurer, confirm the documents required and help you provide the incident details, photographs, reports, repair estimates and other supporting information."}, {"text": "We coordinate with the insurer, surveyor and other relevant parties, follow the assessment of the damage or liability, and keep the claim moving while the loss is evaluated."}, {"text": "We review the insurer’s proposed settlement against the policy terms and follow the claim through the settlement process, raising any points that need clarification or further review."}], "heading": "What to do when your vessel is damaged or involved in an incident"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "699dbb5e-fb1e-4a24-bd7c-e14564292ca6", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Practical answers about vessel cover, navigation limits, insured values, marine liabilities, policy extensions, claims and the information needed to arrange marine insurance.", "items": [{"answer": "Marine insurance covers the vessel itself and related marine liabilities. Cargo insurance covers goods being transported by sea, air or land and is arranged separately.", "question": "Q1 – What is the difference between marine insurance and cargo insurance?"}, {"answer": "Yes. Marine cover can be arranged for yachts and pleasure craft, including the vessel, machinery and equipment, with liability and other protections depending on the policy selected.", "question": "Q2 – Can yachts and pleasure boats be insured?"}, {"answer": "Navigation limits define the geographical area in which the vessel is insured to operate. If you intend to sail outside the agreed area, contact Triple H beforehand so we can confirm or arrange the required extension.", "question": "Q3 – What are navigation limits?"}, {"answer": "The insured value is agreed when the policy is arranged using the vessel details and supporting valuation information required by the insurer. It is important that the declared value properly reflects the vessel being insured.", "question": "Q4 – How is the value of the vessel insured?"}, {"answer": "It can. Depending on the policy, liability cover may include claims involving third parties, passengers or other vessels, subject to the agreed limits and conditions.", "question": "Q5 – Does marine insurance include third-party liability?"}, {"answer": "Not necessarily. These risks can be subject to separate terms, exclusions or extensions, so they should be specifically checked when the policy is arranged.", "question": "Q6 – Is war, strikes or piracy cover automatically included?"}, {"answer": "Contact Triple H before any material change in the vessel’s use, navigation area, ownership or other insured details so we can confirm whether the insurer needs to amend the policy.", "question": "Q7 – What if we change how or where the vessel is used?"}, {"answer": "A survey may be required depending on the vessel’s age, type, value and condition, as well as the insurer’s underwriting requirements. We confirm what is needed before placement.", "question": "Q8 – Will the insurer require a survey of the vessel?"}, {"answer": "Premium can depend on factors such as the vessel’s type, age and value, its use, navigation area, liability limits, deductibles, selected extensions and the insurer’s assessment of the risk.", "question": "Q9 – What affects the cost of marine insurance?"}, {"answer": "Take any necessary steps to protect people and prevent further loss, document the incident where possible and contact Triple H promptly. We notify the insurer and manage the claim through assessment and settlement.", "question": "Q10 – What should we do if the vessel is damaged or involved in an incident?"}, {"answer": "Depending on the incident, the insurer may request photographs, incident or authority reports, vessel documents, repair estimates, invoices, survey reports and other supporting evidence. We confirm and coordinate the required documents.", "question": "Q11 – What documents may be required for a marine claim?"}, {"answer": "We usually need the vessel type, age, value and specifications, its intended use, navigation area, mooring or storage arrangements, claims history, required liability limits and any additional cover you want to consider.", "question": "Q12 – What information do we need for a marine insurance quote?"}], "heading": "Marine Insurance FAQs", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "d4aaa93c-e2de-4240-a795-aa895bcbaf1e", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Explore other cover that can protect your property, employees and wider business operations alongside marine insurance.", "heading": "Other Business Insurance", "buttonHref": "/en/solutions/business", "buttonLabel": "Explore Business Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "callout"}}, {"id": "0e93c91b-a4c3-42f6-87ac-308b790c9505", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "bc6a668f-3de5-4c93-b497-d411ee92fc11", "type": "container", "visible": true, "children": [{"id": "5b639564-d93b-47d5-8b36-3b4ef4e6f29e", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Get a marine insurance quote", "level": 2}, "visible": true}, {"id": "ac8fc151-23a3-46be-bc73-8200ec20eb4e", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Send us your vessel details, insured value, intended use and navigation area. Triple H will compare suitable insurers in Lebanon and come back with clear, written options for your vessel."}, "visible": true}, {"id": "257c32c9-f095-4e9e-a7ed-59388a9cb6ac", "type": "button", "content": {"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, "visible": true}, {"id": "d9caa724-23bb-4252-bb19-90058b29175f", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('cf2f9a98-0560-4195-90cf-fbe5b0467a1e', 'International Support | Triple H Insurance Broker', 'en/international-insurance-support', '2026-09-27 16:38:55.120344+00', '{"Title": "International Insurance Support | Triple H Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "International Insurance Support | Triple H Broker", "ImageUrl": null, "Description": "International and worldwide insurance support across Lebanon, the Gulf and wider international markets."}, "Description": "Arrange international and worldwide insurance cover with Triple H across Lebanon, the Gulf and wider international markets for personal and business needs.", "CanonicalUrl": "https://triplehbroker.com/en/international-insurance-support"}', '2026-09-03 10:44:58.91168+00', false, false, 'en', '47b124b2-7fc8-4f42-95fc-51fbe27fd09d', 'builder', '{"type": "page", "children": [{"id": "54194d65-8434-4841-be86-831819861a8a", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Triple H Insurance Broker Company gives individuals, families and businesses one point of contact for insurance needs across Lebanon, the Gulf and international markets, helping coordinate suitable cover wherever their needs extend.", "items": [{"href": "/en/contact", "label": "Contact Us", "variant": "inverse"}], "eyebrow": "INTERNATIONAL SUPPORT", "heading": "Insurance support beyond Lebanon", "imageAlt": "", "mobileImageUrl": "/uploads/20260927161718-3824cbcdceb1418ea88bf03e87d7054f.webp", "desktopImageUrl": "/uploads/20260927161429-ddf2bca2f03c4da499884358b5dbd934.webp"}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "060ba80e-b7cf-47e6-853f-4c93b3ccfef3", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Triple H Insurance Broker S.A.R.L. is licensed in Lebanon. Our international support is designed for individuals, families and businesses whose insurance needs extend beyond one country or market.", "items": [{"text": "This includes clients in Lebanon seeking international or worldwide cover, clients with assets, employees or operations abroad, and clients seeking insurance for risks located entirely outside Lebanon."}, {"text": "Our support extends across the Gulf Cooperation Council (GCC) — including the UAE, Qatar, Saudi Arabia, Kuwait, Bahrain and Oman — as well as the wider Middle East, Europe, Africa and other international markets. The appropriate arrangement depends on the country, type of risk, territorial scope required and available insurer terms."}], "heading": "How does Triple H support international insurance needs?"}, "visible": true, "children": [], "settings": {"sectionType": "editorial-story"}}, {"id": "7ad3e50d-2d42-45c1-8cf2-7967201f7c73", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "9f383231-e005-4644-a6a6-dd8b1f7e6bc7", "type": "container", "visible": true, "children": [{"id": "816d8d4d-c6b7-479a-bf59-e574bd9edc68", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "What matters when insurance crosses borders?", "level": 2}, "visible": true}, {"id": "fceda436-784b-45f6-a8b1-0d75ea8c1e54", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "International insurance and worldwide cover involve more than choosing a country or area of cover. The policy needs to reflect where the risk is located, where protection is required and how the insurer will respond across the relevant territories."}, "visible": true}, {"id": "533e8e0c-5aa3-4cf2-a738-64220686c60d", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "19bcf98a-4282-43ae-bc75-5e861db2585f", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "4393c78b-6e28-4221-8048-4b82ded53e06", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Territorial scope", "level": 3}, "visible": true}, {"id": "6edace89-51cb-4e1a-8d35-fc86a7b31980", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "We arrange cover with a territorial scope that includes the countries and regions relevant to you, your family or your business — including its employees, assets and activities — so the policy reflects where protection is actually needed."}, "visible": true}]}, {"id": "b7c9a64d-c536-492e-92fa-6383f5166fb9", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "b506615d-415a-4fad-9fb4-a3a4fb1847d1", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Country-specific requirements", "level": 3}, "visible": true}, {"id": "cbc015f5-cb10-44c4-bdca-1495476593d6", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "We arrange the insurance to meet the requirements of the country where cover is needed, taking into consideration the type of insurance, the location of the risk and any local rules that apply."}, "visible": true}]}, {"id": "2b4b115d-6520-4c9a-92ee-e89e145f967a", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "6e9682ed-6c01-44f6-866c-a5e77bcb5d31", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Policy terms across territories", "level": 3}, "visible": true}, {"id": "626855ab-a862-4325-818e-433355554bb6", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "We negotiate and arrange the policy’s limits, conditions and exclusions to match the protection required across the relevant countries and territories. At renewal, we reassess your needs and adjust the cover where necessary."}, "visible": true}]}, {"id": "ee7c77f1-8b65-4d4e-8a88-68744ba5721b", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "b80a5624-bd95-4117-8213-e84db55ebe31", "type": "heading", "content": {"text": "Claims and service abroad", "level": 3}, "visible": true}, {"id": "62580324-a8f5-42fc-ad5e-8876f2e5d73d", "type": "text", "content": {"text": "When a claim occurs abroad, we handle it with the insurer on your behalf, manage the required communication and follow-up, and stay involved until the claim is resolved."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "1bf8e83c-8d81-4ee4-bc92-609d53f48210", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Explore insurance solutions that can support personal, family and business needs across borders.", "items": [{"href": "/en/solutions/health", "title": "Health", "summary": "", "imageAlt": "", "imageUrl": "/uploads/20260925160942-71dafadce2b94c07b8c90a8ef32a794f.webp", "linkLabel": ""}, {"href": "/en/solutions/travel", "title": "Travel", "summary": "", "imageAlt": "", "imageUrl": "/uploads/20260925164107-c4c19666ac8e47158fd19af72390c823.webp", "linkLabel": ""}, {"href": "/en/solutions/business", "title": "Business & liability", "summary": "", "imageAlt": "", "imageUrl": "/uploads/20260816205841-8a0aae16892a4b3db63cec353a511883.webp", "linkLabel": ""}, {"href": "/en/solutions/life", "title": "Life & family protection", "summary": "", "imageAlt": "", "imageUrl": "/uploads/20260925162142-b76192ddfba5445ca80b6540d294e37d.webp", "linkLabel": ""}], "heading": "Insurance solutions for international needs"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "a9db4a4e-35c5-4b74-b402-b90b8ee7af0b", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Practical answers to common questions about arranging insurance across countries and international markets.", "items": [{"answer": "Not always. Depending on the type of insurance, the countries involved and local requirements, one policy may cover several territories, while some situations may require separate arrangements. Triple H determines the most suitable structure for the countries and risks involved.", "question": "Q1 – Do I need a separate insurance policy for each country?"}, {"answer": "Sometimes. We review the policy’s current territorial scope and terms to see whether it can be extended. If it cannot, we arrange additional or separate cover to meet the international protection required.", "question": "Q2 – Can my existing insurance policy be extended internationally?"}, {"answer": "We need to understand the countries involved, who or what needs protection, the type and location of the risk, the activities involved and the territorial scope required. This allows us to approach the appropriate insurers and arrange suitable terms.", "question": "Q3 – What information do you need to arrange international cover?"}, {"answer": "No. International cover can apply to selected countries, a defined region or worldwide, depending on the insurance need and insurer terms. We arrange the territorial scope to match where protection is required.", "question": "Q4 – Does international insurance always mean worldwide cover?"}, {"answer": "Notify Triple H as soon as something changes. We assess the new situation, coordinate any required policy amendments with the insurer and make sure the cover continues to reflect the updated risk.", "question": "Q5 – What happens if my countries, activities or insurance needs change during the policy?"}, {"answer": "Yes. We can review your existing policy, its territorial scope, limits, conditions and exclusions, and advise whether it still matches your current international insurance needs. Where changes are needed, we arrange the appropriate adjustments or additional cover.", "question": "Q6 – Can Triple H review international cover I already have?"}], "heading": "International insurance: common questions", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "b4f25974-12a0-4fa6-ae3d-c0e6369ab0f6", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "4d24c8be-c8fb-4325-8e56-7216f5041070", "type": "container", "visible": true, "children": [{"id": "a41cacb0-16a9-46ec-a8f8-44ed54c2a87a", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Discuss your international insurance needs.", "level": 2}, "visible": true}, {"id": "e936aa8a-5eb4-4e9b-be48-26a2261f7be3", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us what you need to protect and where, and we’ll arrange suitable international cover to match your needs."}, "visible": true}, {"id": "16f5f0ad-8813-4f55-a357-b9fadd0490eb", "type": "button", "content": {"href": "/en/contact", "label": "Contact us", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('82a6f3c3-27bd-4b5e-b5f2-e26430fc3b82', 'Life Insurance | Triple H Insurance Broker', 'en/solutions/life', '2026-09-27 15:48:01.812777+00', '{"Title": "Individual & Family Life Insurance in Lebanon | Triple H", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Individual & Family Life Insurance | Triple H Insurance Broker", "ImageUrl": "https://triplehbroker.com/uploads/20260816201838-4fbe63135df049ca920ae57f625d6d04.webp", "Description": "Explore life insurance, personal accident, critical illness, education, retirement and investment plans arranged around your needs and goals."}, "Description": "Compare individual and family life insurance in Lebanon. Triple H arranges protection, accident, critical illness, education, retirement and investment plans.", "CanonicalUrl": "https://triplehbroker.com/en/solutions/life"}', '2026-08-19 12:29:08.127183+00', false, false, 'en', 'ad6c6fe7-c78f-4a82-b835-38ba02079c21', 'solution-detail', '{"type": "page", "children": [{"id": "8681260f-7a78-4c37-8104-ca9b23d69789", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Life insurance can provide financial protection following death or disability, while other plans can support critical illness, accidents, education, retirement, savings and long-term investment goals. We compare suitable options, explain the benefits and terms clearly, and arrange the plan around your needs.", "eyebrow": "PERSONAL & FAMILY INSURANCE", "heading": "Individual & Family Life Insurance", "audience": "Individuals and families looking to protect financial responsibilities, future income needs, savings and long-term investment goals.", "buttonHref": "/en/contact", "buttonLabel": "Request a quote", "audienceHeading": "Who it is for"}, "visible": true, "settings": {"sectionType": "solution-introduction"}}, {"id": "4e8c6cd9-7b9c-4fc2-aaf4-31ac68606781", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "db4acf2c-347f-49e9-b51d-0534cbad7446", "type": "container", "visible": true, "children": [{"id": "89ab5f70-9119-44c3-925f-3bd03fe91c79", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Life insurance and financial protection plans", "level": 2}, "visible": true}, {"id": "eb0744cf-1da3-46b6-a7c6-d45239949ed2", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Choose from protection, savings and long-term planning solutions designed for different financial needs and life stages."}, "visible": true}, {"id": "fa8d86fa-ca07-4f16-b037-5cfdb65f33d7", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "e2259d68-f96d-48d4-a9c6-72daa48bfa7b", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "61c6c0ed-9c70-422e-96c8-6dffb36694c7", "type": "image", "styles": {"desktop": {"aspectRatio": "4 / 3"}}, "content": {"alt": "", "url": "/uploads/20260927151949-bf72d0d6bb7448658b214b91615d1657.webp", "caption": ""}, "visible": true}, {"id": "34289a3a-6e51-4ea6-8720-16f6ec621c55", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Personal Accident Insurance", "level": 3}, "visible": true}, {"id": "8b74502b-3ac1-4d7a-9598-df0fc9e75f4d", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Provides financial compensation following an accident, including benefits for accidental death, permanent total or partial disability, and weekly income support during temporary total disability, with other benefits available depending on the plan."}, "visible": true}]}, {"id": "6c7fea55-9700-4e1b-869c-450cdc4f03f4", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "485686d6-b429-4f9f-b0a3-812d28eb2f2f", "type": "image", "styles": {"desktop": {"aspectRatio": "4 / 3"}}, "content": {"alt": "", "url": "/uploads/20260927152326-322cf02db9e049758fa97fb859af5ddc.webp", "caption": ""}, "visible": true}, {"id": "c28db950-17f1-4f76-9d86-3742f4145490", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Critical Illness Insurance", "level": 3}, "visible": true}, {"id": "b714a011-a720-4b38-be73-b16b936159e1", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Provides financial compensation following diagnosis of a covered critical illness, helping cover lost income and other unexpected expenses during treatment and recovery, with benefits and conditions depending on the selected plan."}, "visible": true}]}, {"id": "fc31bb98-1388-46bd-9e53-0d09b19284a1", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "5aafe035-6adb-42c2-b7fb-b98abf4e9918", "type": "image", "styles": {"desktop": {"aspectRatio": "4 / 3"}}, "content": {"alt": "", "url": "/uploads/20260927153543-a2cf31f6511e48b6b414c45fb2e51e65.webp", "caption": ""}, "visible": true}, {"id": "1a08ff64-6935-45e3-84ac-fbe8be30702c", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Refundable Life Insurance", "level": 3}, "visible": true}, {"id": "69f4c226-6464-4b70-b77f-7e0a0991e3c1", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Provides life protection during the policy term, with financial benefits in case of death or permanent total disability, while allowing the premiums paid to be returned at maturity if the insured outlives the term, subject to the selected plan."}, "visible": true}]}, {"id": "a95d1f64-3925-4ba8-aacc-4be26cd38154", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "16efb520-2140-490e-bda0-a52ad7f92032", "type": "image", "styles": {"desktop": {"aspectRatio": "4 / 3"}}, "content": {"alt": "", "url": "/uploads/20260927153548-3908556372584934847752ce5db4eee4.webp", "caption": ""}, "visible": true}, {"id": "62c2fa18-c709-41f7-9515-f7dc813067a6", "type": "heading", "content": {"text": "Education Plan", "level": 3}, "visible": true}, {"id": "3b8230ec-eac7-49c1-b933-365e01d8221f", "type": "text", "content": {"text": "Builds funds for your child’s future education through long-term savings and investment, while protection features can help keep the plan on track if death, permanent total disability or covered critical illness affects the person funding it, usually a parent."}, "visible": true}]}, {"id": "f622c25b-041f-4866-a765-9d9fa0627fad", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "bc91c686-9d9a-4294-8492-f42d5e0fb87a", "type": "image", "styles": {"desktop": {"aspectRatio": "4 / 3"}}, "content": {"alt": "", "url": "/uploads/20260927153552-7cbccbfc4cc649ceacbf0fb5ef0bc9e4.webp", "caption": ""}, "visible": true}, {"id": "98ab94de-9614-4291-8226-d46dd2b61825", "type": "heading", "content": {"text": "Retirement Plan", "level": 3}, "visible": true}, {"id": "abf6de85-3437-47ce-8c06-1bdb7df2d5e0", "type": "text", "content": {"text": "Builds funds specifically for retirement through long-term contributions, with the option to receive the accumulated value as retirement capital or income, while protection benefits can help keep the plan on track if death or permanent total disability occurs."}, "visible": true}]}, {"id": "8575966a-e385-440c-bb0f-06b2036337c6", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "9c33730d-416a-47c0-9f03-be33b3663d6e", "type": "image", "styles": {"desktop": {"aspectRatio": "4 / 3"}}, "content": {"alt": "", "url": "/uploads/20260927154752-c77a5588c4924d8fab1ce887d8b9b0b1.webp", "caption": ""}, "visible": true}, {"id": "2abf56cd-de0c-44a0-bbbc-852957981899", "type": "heading", "content": {"text": "Investment Plans", "level": 3}, "visible": true}, {"id": "a9943696-3706-4fd8-82ab-e53e3a595ce2", "type": "text", "content": {"text": "Provides long-term access to selected global investment funds through an insurance-based plan, allowing you to build and diversify savings according to your goals and risk profile. Investment values can increase or decrease depending on fund performance."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "0db4c342-364d-4b98-b865-960fc8541d9c", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"help": "We compare suitable plans, benefits, policy terms, premiums, durations, savings features and investment options, explain the differences clearly and arrange the plan that fits your needs.", "intro": "Life insurance can combine financial protection with savings and long-term planning, depending on the selected plan and insurer.", "items": [{"text": "Financial benefits for beneficiaries in case of death"}, {"text": "Financial benefits for permanent total or partial disability"}, {"text": "Temporary income support following an accident"}, {"text": "Financial benefits following a covered critical illness"}, {"text": "Education funding and protection benefits"}, {"text": "Retirement savings and maturity benefits"}, {"text": "Long-term investment opportunities in global markets"}, {"text": "Policy continuation with waived premiums after covered events"}, {"text": "War risk benefits for war-related death or disability"}], "heading": "What it includes", "helpHeading": "How Triple H helps"}, "visible": true, "settings": {"sectionType": "coverage-details"}}, {"id": "c6eab404-50d8-4124-b396-91885526fbd2", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "The right plan depends on the level of protection you need, how long you want the plan to run and how its financial features work over time.", "items": [{"text": "Amount of financial protection"}, {"text": "Policy term and premium payment period"}, {"text": "Benefits for death, disability and critical illness"}, {"text": "Medical underwriting and eligibility"}, {"text": "Maturity, refund and surrender terms"}, {"text": "Savings and investment options"}, {"text": "Charges and access to accumulated funds"}, {"text": "Guaranteed and market-linked values"}], "heading": "What to compare"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "63712fe4-41cf-4b77-97f4-4729813a0e84", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We manage the process from understanding your needs and goals to comparing suitable plans, arranging the cover and supporting you throughout the policy period.", "items": [{"body": "We understand what you want the plan to achieve and the protection, timeframe and budget that suit you.", "title": "Understand your needs"}, {"body": "We approach suitable insurers in the Lebanese market and compare the available plans against your needs and goals.", "title": "Compare suitable plans"}, {"body": "We explain the differences clearly, help you choose the option that best suits your needs and arrange the plan for you.", "title": "Explain and arrange"}, {"body": "We handle insurer communication and remain involved through policy changes, renewals, claims and plan maturity.", "title": "Stay involved"}], "layout": "grid", "heading": "How we arrange your life insurance"}, "visible": true, "children": [], "settings": {"sectionType": "steps"}}, {"id": "988a4a20-6af1-4628-98e0-3caf9352142b", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Answers to common questions about life insurance, financial protection, savings and long-term planning.", "items": [{"answer": "The premium can vary according to factors such as age, health, the amount of protection, policy duration, selected benefits and underwriting. The type of plan also affects the cost, so we compare the terms as well as the premium.", "question": "Q1 – What affects the cost of life insurance?"}, {"answer": "The appropriate amount depends on your income, financial responsibilities, dependents, outstanding debts and future goals. We assess what would need to be protected financially and help you compare suitable levels of cover.", "question": "Q2 – How much life insurance cover should I choose?"}, {"answer": "In general, only basic health and personal information is needed. Additional medical information may be requested in specific cases, including pre-existing medical conditions or larger amounts of cover.", "question": "Q3 – Will I need medical underwriting for life insurance?"}, {"answer": "Both provide life protection during the policy term, but a refundable plan can also return the premiums paid at maturity if its conditions are met. This usually comes with a higher premium than comparable non-refundable protection.", "question": "Q4 – How is refundable life insurance different from standard life insurance?"}, {"answer": "Health insurance is designed to cover eligible medical expenses, while critical illness insurance provides a financial benefit following diagnosis of a covered serious illness. The benefit can help with income needs, personal expenses or other financial obligations.", "question": "Q5 – How is critical illness insurance different from health insurance?"}, {"answer": "It can be especially useful when your income depends on your ability to work. If an accident causes death, permanent disability or temporarily prevents you from working, the policy can provide financial compensation, including weekly income support, depending on the selected cover. This can help protect income that medical insurance or social security may not replace.", "question": "Q6 – Why consider personal accident insurance alongside life insurance?"}, {"answer": "Depending on the plan, protection benefits can help keep the financial objective in place by covering future premiums, providing financial benefits or continuing education or retirement funding after a covered death or disability.", "question": "Q7 – What happens to an education or retirement plan if death or disability occurs?"}, {"answer": "The investment value depends on the selected strategy and market performance, so it can increase or decrease over time. The plan can also include defined insurance benefits, such as life or disability protection, that are separate from the investment value. We explain clearly which parts are fixed and which depend on market performance before you choose.", "question": "Q8 – Are investment plans guaranteed?"}, {"answer": "It depends on the plan. Early withdrawal or surrender may be available, but the amount received can differ from the accumulated value and may be affected by the timing and policy terms.", "question": "Q9 – Can I access my savings before the plan reaches maturity?"}, {"answer": "Yes, war risk protection can be included under certain plans for covered death or disability resulting from war-related events. The scope, limits and conditions depend on the selected plan and insurer.", "question": "Q10 – Can life insurance include war risk cover?"}], "heading": "Life Insurance FAQs", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "f3e1b6ac-059f-4174-bd18-7ab459e59b12", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Explore other insurance solutions we arrange for individuals, families and businesses.", "heading": "Other insurance solutions"}, "visible": true, "settings": {"sectionType": "related-links"}}, {"id": "1e140255-4ec7-404b-98e6-936be32a20f0", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "9754717e-2c04-4481-baf6-c15dca6042b1", "type": "container", "visible": true, "children": [{"id": "b1c1c681-c92e-46bc-98c8-b812d6a29748", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Find the life insurance plan that fits your needs and goals.", "level": 2}, "visible": true}, {"id": "56479306-e093-4c0b-a3cc-40fd104a4082", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Get a quote based on the protection, timeframe and financial goals that matter to you."}, "visible": true}, {"id": "11cdfbad-065a-4a6a-881a-7529deaca470", "type": "button", "content": {"href": "/en/contact", "label": "Request a Quote", "variant": "inverse"}, "visible": true}, {"id": "04e4b94a-ace5-416f-9671-10603b1baea6", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "solid", "footerVisible": true, "catalogPosition": 1}, "template": "solution-detail", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('10000000-0000-0000-0000-000000000002', 'About Us | Triple H Insurance Broker', 'en/about', '2026-09-25 15:46:26.884477+00', '{"Title": "About Triple H | Licensed Insurance Broker in Lebanon", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "About Triple H | Licensed Insurance Broker in Lebanon", "ImageUrl": "", "Description": "Discover Triple H’s independent approach to insurance, clear comparisons and long-term client support in Lebanon."}, "Description": "Learn about Triple H Insurance Broker S.A.R.L., our independent approach, licensed status in Lebanon and how we advise and support our clients.", "CanonicalUrl": "https://triplehbroker.com/en/about"}', '2026-08-17 12:22:38.166919+00', false, true, 'en', '5c4f303a-5ac5-43b5-c61d-2e862610054f', 'about', '{"type": "page", "children": [{"id": "11000000-0002-0001-0000-000000000001", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "cinematic-tall", "bordered": false}, "content": {"intro": "Triple H Insurance Broker S.A.R.L. is a licensed insurance broker in Lebanon, advising individuals, families and businesses on suitable cover. We compare insurers, explain the differences clearly, arrange the policy and stay involved through renewals, changes and claims.", "items": [], "eyebrow": "ABOUT TRIPLE H", "heading": "Independent advice. Long-term support.", "imageAlt": "Triple H Insurance Broker office in Beirut", "mobileImageUrl": "/uploads/20260925154550-dc1c9bffce9145f1bdf9663db1d0f549.webp", "desktopImageUrl": "/uploads/20260925153836-85fe144796ce48c6aeb2926068d65add.webp"}, "visible": true, "position": 0, "settings": {"sectionType": "hero-banner"}}, {"id": "5b89094f-e078-4646-ac89-e16e06e2dc52", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "00e4f9e9-ce24-489f-a4f6-7cc933b8936a", "type": "container", "visible": true, "children": [{"id": "69075387-d85d-419c-8e2a-11420f6bfece", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Our role goes beyond arranging a policy.", "level": 2}, "visible": true}, {"id": "6e846e03-8395-479d-942c-d07ecb349abf", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Insurance matters most when you need to rely on it. That is why our work does not end when a policy is issued. We first understand what you need to protect, then approach suitable insurers in the Lebanese market and compare the terms that genuinely matter — cover, limits, exclusions, price and how the policy responds when something goes wrong. We explain the differences clearly, negotiate and communicate with insurers on your behalf, and stay involved through policy changes, renewals and claims."}, "visible": true}]}], "settings": {"sectionType": "text"}}, {"id": "cf788e6b-baf0-4cea-86a1-0a9ad124f18f", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Clear advice, transparent comparisons and a broker company that stays involved after your cover is arranged.", "items": [{"text": "We explain the important parts of the policy in clear language, including what is covered, what is limited and what is excluded, so you know exactly what you are choosing."}, {"text": "We compare suitable insurers and the options they offer, looking at more than price so you can see the differences that may matter when you need to use the policy."}, {"text": "Your needs can change over time. We review your cover at renewal and when needed, so it continues to reflect your personal, family or business situation."}, {"text": "We remain available for changes, renewals, questions and claims, and we communicate with insurers on your behalf when needed."}], "heading": "What you can expect from Triple H"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "11000000-0002-0003-0000-000000000003", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "numbered-grid", "bordered": true}, "content": {"intro": "Triple H Insurance Broker S.A.R.L. is a licensed insurance broker in Lebanon, operating under the supervision of the Ministry of Economy & Trade.", "items": [{"label": "Legal name", "value": "Triple H Insurance Broker S.A.R.L."}, {"label": "Insurance Broker License", "value": "No. 581"}, {"label": "Commercial Registration", "value": "No. 2077214"}, {"label": "Triple H cover support", "value": "Lebanon, the Gulf & worldwide"}], "layout": "minimal", "heading": "Licensed, registered and accountable"}, "visible": true, "position": 2, "settings": {"sectionType": "statistics"}}, {"id": "02f3a1d5-a332-4679-8d0a-6a591ea2a17d", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "22f8c34b-d795-4689-95b6-8d7be6463f52", "type": "container", "visible": true, "children": [{"id": "49acb0b1-7c8c-427e-8acf-e1dae37e7613", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "What drives us", "level": 2}, "visible": true}, {"id": "5f375962-92c0-4ba0-95ab-d84b510f4d07", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "The principles that guide how we advise, represent and support our clients."}, "visible": true}, {"id": "49409965-6802-4fb8-83e0-cb1dd83dff5a", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "6ac32400-9f8f-4290-9bd3-5bd29454e929", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "e2e23ba5-41b2-461b-9c3d-f33002e8ad42", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Our mission", "level": 3}, "visible": true}, {"id": "3248d226-a646-4ce1-bf0b-56ca4c1b96c5", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "To make insurance in Lebanon clear, well chosen and genuinely useful — so our clients understand what they are buying and can rely on the support behind it."}, "visible": true}]}, {"id": "91e71e4d-ac52-47d8-b99b-c15b373f02f8", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "fbd0f4de-ca6c-4055-827f-e6cddcd4b41f", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Our vision", "level": 3}, "visible": true}, {"id": "593343c9-43a6-4fb6-a77f-88cee7c76475", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "To be the broker company Lebanese families and businesses trust and recommend to each other, known for clear explanations and for showing up at claim time."}, "visible": true}]}, {"id": "a82a965f-4e86-4f7d-9883-333ecc2fb387", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "c57028a8-9e18-43e6-92b0-f4f91df23c9e", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Our values", "level": 3}, "visible": true}, {"id": "fcc5fe54-84cc-4edc-9143-373025e56dad", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Independence, transparency, plain language and professional advocacy — from choosing your cover to renewals and claims."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "6bc4aa32-f5fa-499b-b53c-406f444a2da9", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "86ed7e5d-0a4c-4540-b509-9dd5c8e6e359", "type": "container", "visible": true, "children": [{"id": "ab30e02a-d40c-43e5-b23b-c9b6c455e9cb", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Let’s discuss your insurance needs.", "level": 2}, "visible": true}, {"id": "e6a315cc-50a6-4735-8504-db7b0f7020a2", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us what you need to protect, and we’ll help you understand the options."}, "visible": true}, {"id": "1a346f2c-4e4c-4472-b8ca-582767a64b31", "type": "button", "content": {"href": "/en/contact", "label": "Contact Us", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "about", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('10000000-0000-0000-0000-000000000001', 'Triple H Insurance Broker S.A.R.L.', 'en', '2026-09-23 17:07:05.196346+00', '{"Title": "Insurance Broker in Lebanon | Triple H Insurance Broker S.A.R.L.", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Triple H Insurance Broker S.A.R.L. | Insurance Solutions in Lebanon", "ImageUrl": "/uploads/20260816154116-cd5b8e9d00d84ddd97e1d44f87b9575f.webp", "Description": "Comprehensive insurance solutions for individuals, families and businesses in Lebanon, backed by independent advice, instant quotes, independent advice and dedicated 24/7 support."}, "Description": "Triple H is a licensed insurance broker in Lebanon offering health, motor, life, property, travel, business and other comprehensive personal and commercial insurance solutions, with instant quotes and expert 24/7 support.", "CanonicalUrl": "https://triplehbroker.com/en"}', '2026-08-16 18:21:44.980976+00', true, true, 'en', '8f839205-470a-bf04-8c4a-48d74ee3351d', 'home', '{"type": "page", "children": [{"id": "11000000-0001-0001-0000-000000000001", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "cinematic-full", "bordered": false}, "content": {"intro": "Transparent health, motor, personal and business coverage from an independent broker company that compares the market and stays with you at claim time.", "items": [{"href": "/en/quote", "label": "Get an Instant Quote", "variant": "inverse"}, {"href": "/en/solutions", "label": "Explore Insurance Solutions", "variant": "inverseOutline"}], "eyebrow": "Licensed Independent Insurance Broker Company · Lebanon", "heading": "Premium protection, tailored for you.", "imageAlt": "The CEO of Triple H Insurance Broker Company reviewing coverage options with a client.", "mobileImageUrl": "https://triplehbroker.com/up