INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('454d5947-4747-4d44-bfbb-9170b433434d', 'Business Insurance | Triple H Insurance Broker', 'en/solutions/business', '2026-09-27 16:08:41.424701+00', '{"Title": "Business Insurance in Lebanon | Triple H Insurance Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Business Insurance in Lebanon | Triple H Insurance Broker", "ImageUrl": "https://triplehbroker.com/uploads/20260816205841-8a0aae16892a4b3db63cec353a511883.webp", "Description": "Explore business insurance in Lebanon for property, employees, vehicles, cargo, liability and specialist risks, arranged around your company’s needs."}, "Description": "Business insurance in Lebanon for property, employees, fleets, cargo, liability and specialist risks. Triple H compares insurers and arranges suitable cover.", "CanonicalUrl": "https://triplehbroker.com/en/solutions/business"}', '2026-08-19 12:29:08.133502+00', false, false, 'en', 'e0f1f38c-ff0b-45be-99ff-5b7dbbc18fdc', 'solution-detail', '{"type": "page", "children": [{"id": "5e098cab-e1f7-49c4-84cd-2083261ff7de", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Business insurance protects the people, property, vehicles, goods and liabilities your company depends on. We identify what your business needs to protect, approach suitable insurers in the Lebanese market and arrange the combination of cover that fits your operations.", "items": [{"href": "/en/contact", "label": "Request a Business Quote", "variant": "inverse"}, {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}], "eyebrow": "BUSINESS & EMPLOYEE INSURANCE", "heading": "Business Insurance in Lebanon", "imageAlt": "", "mobileImageUrl": "/uploads/20260927160829-fd332af6be7c4f8a88aee386326f73d3.webp", "desktopImageUrl": "/uploads/20260927155530-c2cf44ab2226489fa171c11456915f93.webp"}, "visible": true, "children": [], "settings": {"sectionType": "hero-banner"}}, {"id": "8e79186e-6a32-4293-9d2e-48ac0b864c62", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "29aac2ea-f824-4e1e-a502-0997356958cc", "type": "container", "visible": true, "children": [{"id": "ae2a103e-c32a-40f5-be87-ac58bdbcd20b", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "What does your business need to protect?", "level": 2}, "visible": true}, {"id": "7e1f6e24-23d5-478e-a04c-fb09a5a901b8", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Business insurance can protect different parts of your company, from its people and property to vehicles, goods, liabilities and the risks that could interrupt operations."}, "visible": true}, {"id": "35f5849f-163d-4b69-ac83-d3c7129d89e7", "type": "grid", "styles": {"mobile": {"gridTemplateColumns": "1fr"}, "desktop": {"gap": "24px", "gridTemplateColumns": "repeat(3, 1fr)"}}, "visible": true, "children": [{"id": "1af3eaa0-b418-4e0b-a0cf-eb0085b7dfed", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "1e5acf4c-0df2-4d40-9232-b4a539fe7559", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Property & Assets", "level": 3}, "visible": true}, {"id": "266923f1-c42a-44d2-b59b-ca174f8665f5", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Buildings, offices, shops, warehouses, stock, machinery, equipment and other physical assets your business depends on."}, "visible": true}]}, {"id": "ba3b2bea-e6fa-4381-82dc-8e7008d412df", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "795d2fbc-909e-4acb-a87e-2fb679ed7c22", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "People & Employees", "level": 3}, "visible": true}, {"id": "53cbc14f-9130-4e1e-8fc6-7b748de55c5f", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Protection for employees through medical, life and workplace accident insurance, arranged around the needs of your workforce."}, "visible": true}]}, {"id": "9a6c89dc-b073-47ed-a07e-ada05420ac2c", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "2f7ff2aa-c81d-4452-ad53-5b5cb585d856", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Vehicles, Goods & Transport", "level": 3}, "visible": true}, {"id": "d09b4e30-ae34-47af-9e99-6438ff62de6a", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Company vehicles, fleets and goods moving by land, sea or air, with protection arranged around how your business operates."}, "visible": true}]}, {"id": "b5d1929c-1143-4f0e-a80c-999c89e17875", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "779aca9b-5c74-461f-9626-348933f22a70", "type": "heading", "content": {"text": "Liability to Others", "level": 3}, "visible": true}, {"id": "87593192-6d70-4817-a239-f2cdbb5de904", "type": "text", "content": {"text": "Protection when your business may become legally responsible for injury, property damage or other covered claims involving third parties."}, "visible": true}]}, {"id": "dd03aac8-646c-41bd-b7c0-a04250a6154b", "type": "stack", "styles": {"desktop": {"gap": "12px", "border": "1px solid var(--border)", "padding": "28px"}}, "visible": true, "children": [{"id": "66705213-3400-4b3a-b2c2-9e7e12942d06", "type": "heading", "content": {"text": "Operations & Specialist Risks", "level": 3}, "visible": true}, {"id": "80b71567-240d-4c8a-a326-a432dfc94be1", "type": "text", "content": {"text": "Protection for risks that can affect business continuity, finances, professional responsibilities, management or other specialized areas of your operations."}, "visible": true}]}]}]}], "settings": {"sectionType": "cards"}}, {"id": "19d17a02-3f9b-4760-985f-91e95e7cd3f7", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We arrange insurance across the main risks businesses need to protect, with each policy structured around the company’s operations, people and responsibilities.", "items": [{"href": "/en/solutions/commercial-property", "title": "Commercial Property Insurance", "summary": "Protection for business premises, stock, machinery, equipment and other physical assets against covered damage or loss, with additional protection available for business interruption.", "imageAlt": "", "imageUrl": "/uploads/20260925165803-0f82427f23034b749b9863e756fe641f.webp", "linkLabel": "Explore Commercial Property Insurance"}, {"href": "/en/solutions/group-health", "title": "Group Health Insurance", "summary": "Medical insurance for employees, with plans arranged around the workforce, hospital network, medical benefits and level of cover the company wants to provide.", "imageAlt": "", "imageUrl": "/uploads/20260925170216-9bff3b762e9740faab6bd11deda187cb.webp", "linkLabel": "Explore Group Health Insurance"}, {"href": "/en/solutions/group-life", "title": "Group Life Insurance", "summary": "Life and disability protection for employees, with benefits structured around the company’s workforce and the level of financial protection it wants to provide.", "imageAlt": "", "imageUrl": "/uploads/20260925192620-b216d9f2341c47d9907ae20b43529fa8.webp", "linkLabel": "Explore Group Life Insurance"}, {"href": "/en/solutions/commercial-motor-fleet", "title": "Commercial Motor & Fleet Insurance", "summary": "Motor insurance for company vehicles and fleets, from compulsory and third-party liability to broader protection for vehicle damage, drivers and other covered risks.", "imageAlt": "", "imageUrl": "/uploads/20260925193430-6299faa660334686aca8480a8ce28a36.webp", "linkLabel": "Explore Commercial Motor & Fleet Insurance"}, {"href": "/en/solutions/marine-insurance", "title": "Marine Insurance", "summary": "Insurance for marine assets and operations, arranged according to the nature of the risk and the protection the business requires.", "imageAlt": "", "imageUrl": "/uploads/20260925201227-97b80d95c4be45bd9692b31eaea793fb.webp", "linkLabel": "Explore Marine Insurance"}, {"href": "/en/solutions/cargo-insurance", "title": "Cargo Insurance", "summary": "Protection for goods while being transported by sea, air or land, whether for individual shipments or ongoing business activity.", "imageAlt": "", "imageUrl": "/uploads/20260925202036-22647f5fee8843cfa1cfb572dbdca107.webp", "linkLabel": "Explore Cargo Insurance"}, {"href": "/en/solutions/commercial-liability-insurance", "title": "Commercial Liability Insurance", "summary": "Protection when the business becomes legally responsible for covered injury, property damage or other liabilities arising from its operations.", "imageAlt": "", "imageUrl": "/uploads/20260925194949-b0a71896953c4c93b05bfc686fc0d146.webp", "linkLabel": "Explore Commercial Liability Insurance"}, {"href": "/en/solutions/workmen-compensation", "title": "Workmen Compensation Insurance", "summary": "Protection for employees following covered work-related accidents or injuries, helping the business meet its responsibilities to its workforce.", "imageAlt": "", "imageUrl": "/uploads/20260925200127-02b747cba35e4c1d8231cb1720a79655.webp", "linkLabel": "Explore Workmen Compensation Insurance"}, {"href": "/en/solutions/fidelity-guarantee-insurance", "title": "Fidelity Guarantee Insurance", "summary": "Protection against covered financial losses caused by dishonest or fraudulent acts committed by employees.", "imageAlt": "", "imageUrl": "/uploads/20260925202626-1b0e5a6646e149ca839398a50a4d4a0a.webp", "linkLabel": "Explore Fidelity Guarantee Insurance"}, {"href": "/en/contact", "title": "Other Business Insurance", "summary": "Additional business insurance can be arranged for specific risks, activities or requirements that fall outside the main products listed.", "imageAlt": "", "imageUrl": "/uploads/20260926202205-c4037a4f72cc4d309c7fe000f54985a1.webp", "linkLabel": "Enquire"}], "heading": "Business insurance solutions"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "3750f724-70bf-4350-af3c-f7a7857a40e9", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Explore additional cover for professional, management, cyber and other specialist risks that may affect your business.", "items": [{"href": "/en/contact", "title": "Medical Malpractice Insurance", "summary": "Professional liability insurance for doctors and other healthcare professionals, protecting against covered claims related to errors or omissions in their professional work.", "imageAlt": "", "imageUrl": "/uploads/20260925205300-1ddec19da0464362a31c579526512594.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Professional Indemnity Insurance", "summary": "Professional liability insurance for consultants, lawyers, engineers, accountants, IT professionals and other specialists, protecting against covered claims related to errors or omissions in their professional services.", "imageAlt": "", "imageUrl": "/uploads/20260926185850-be92ca735278412ca827f46c64da7d75.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Cyber Insurance", "summary": "Cyber insurance for businesses facing digital and data-related risks, with protection that can include cyber incidents, data breaches, liability and other covered technology-related losses.", "imageAlt": "", "imageUrl": "/uploads/20260926193428-1b60cfe9ca11495c895cc47822383797.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Directors & Officers Insurance", "summary": "Liability insurance for company directors and officers, protecting against covered claims related to decisions, actions or responsibilities carried out in their management roles.", "imageAlt": "", "imageUrl": "/uploads/20260926193458-644892ab1bb042fc96aac73cde8403bd.webp", "linkLabel": "Enquire"}, {"href": "/en/contact", "title": "Expat / Foreign Workers Insurance", "summary": "Insurance for expatriates and foreign workers, with protection that can include hospital and medical expenses following a covered work-related accident, as well as death or disability benefits where applicable.", "imageAlt": "", "imageUrl": "/uploads/20260926194305-c1ba6eed35f84c578bd9520938dc06f6.webp", "linkLabel": "Enquire"}], "heading": "Professional & Specialist Insurance"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "17ff781d-c12d-46a2-bd4a-a149c2fc0a1e", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We identify the risks that need protection, determine the cover required and compare suitable insurers in Lebanon market before arranging the policies for your business.", "items": [{"body": "We review your operations, employees, property, vehicles, goods and liabilities to identify the risks that need to be insured.", "title": "Assess your insurance needs"}, {"body": "We determine the right combination of policies, limits and cover so each part of your business is protected and the policies work together properly.", "title": "Structure the cover"}, {"body": "We approach suitable insurers in the Lebanese market and compare their offers based on cover, limits, exclusions, price, service and claims approach.", "title": "Compare suitable insurers"}, {"body": "We explain the differences, negotiate with insurers where needed and arrange the selected policies so your business has the right protection in place.", "title": "Arrange your insurance"}], "layout": "grid", "heading": "How we structure your business insurance"}, "visible": true, "children": [], "settings": {"sectionType": "steps"}}, {"id": "f95b1f89-0b5e-49b5-b783-02225edf185e", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Your insurance needs can change as your business changes. We stay involved after the policies are issued, handling updates, renewals, insurer communication and claims on your behalf.", "items": [{"text": "Add or remove employees from group insurance policies"}, {"text": "Add or remove vehicles and update fleet details"}, {"text": "Update insured locations, property, stock and equipment"}, {"text": "Adjust cover and insured values when business needs change"}, {"text": "Arrange policy amendments and insurance certificates"}, {"text": "Coordinate renewals across your business policies"}, {"text": "Handle insurer communication on your behalf"}, {"text": "Manage claims from notification through to settlement"}], "heading": "Ongoing support for your business"}, "visible": true, "children": [], "settings": {"sectionType": "feature-list"}}, {"id": "5f062a7a-b463-4f34-a3f3-f662cbb5cb1d", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Different industries face different risks. Explore how we arrange insurance around the way your business operates.", "heading": "Insurance by industry", "buttonHref": "/en/industries", "buttonLabel": "Explore Industries"}, "visible": true, "children": [], "settings": {"sectionType": "callout"}}, {"id": "9a67a14c-6fba-460a-8283-4bf63ba05ba5", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Answers to common questions about arranging, reviewing and managing insurance for your business.", "items": [{"answer": "The right combination depends on how your business operates, what it owns, who it employs and the liabilities it faces. We review the business as a whole and determine which policies, limits and cover are needed.", "question": "Q1 – What insurance does my business need?"}, {"answer": "Yes. We can review your current policies, insured values, limits, exclusions and renewal terms, identify areas that may need improvement and compare suitable alternatives in the market.", "question": "Q2 – Can Triple H review my existing business insurance?"}, {"answer": "Yes. Businesses often need more than one policy. We structure the different covers around the same business so they work together properly and are easier to manage.", "question": "Q3 – Can several business insurance policies be arranged together?"}, {"answer": "Yes. Cover can be updated when you add employees, vehicles, locations, equipment, stock or new activities. We arrange the necessary policy changes and adjust the protection as your business develops.", "question": "Q4 – Can my insurance change as my business grows?"}, {"answer": "Yes. Multiple offices, shops, warehouses or other locations can be included, depending on the type of risk and insurer requirements. We structure the cover around the locations your business operates from.", "question": "Q5 – Can different branches or business locations be insured?"}, {"answer": "The cost can depend on the nature and size of the business, insured values, number of employees or vehicles, turnover, locations, selected limits, claims history and the type of cover required. We compare the terms as well as the premium.", "question": "Q6 – What affects the cost of business insurance?"}, {"answer": "We usually need details about the business activities, locations, employees, assets, vehicles and the cover required. Depending on the product, additional information such as insured values, turnover, claims history or current policies may also be needed.", "question": "Q7 – What information do you need to arrange business insurance?"}, {"answer": "Before renewal, we review any changes in the business, update the information and cover where needed, approach suitable insurers and compare the available terms before arranging the selected renewal.", "question": "Q8 – How do you manage business insurance renewals?"}, {"answer": "Yes. Our support extends beyond Lebanon for businesses with employees, assets, operations or other insurance needs abroad. We coordinate suitable arrangements across the Gulf and wider international markets according to the nature and location of the risk.", "question": "Q9 – Can you support businesses with insurance needs outside Lebanon?"}], "heading": "Business Insurance FAQs", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "cff3aff9-ba70-43c4-910a-a405233776cd", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "e69b0f37-5db5-45cf-8415-57f382924c98", "type": "container", "visible": true, "children": [{"id": "463ab54b-de0d-49d0-8900-9211499bfa3d", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Build the right insurance around your business.", "level": 2}, "visible": true}, {"id": "1e811ca3-8fa9-45ed-80fb-1ea7bc4d7f75", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us what your business needs to protect. We’ll structure the right cover, compare suitable insurers in Lebanon and arrange the selected policies."}, "visible": true}, {"id": "b8e68044-ac76-4dfe-9e06-f280b22b02a4", "type": "button", "content": {"href": "/en/contact", "label": "Request a Business Quote", "variant": "inverse"}, "visible": true}, {"id": "c1ff8e8a-121f-48e6-a5ea-7fd0489bffdc", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true, "catalogPosition": 4}, "template": "solution-detail", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('10000000-0000-0000-0000-000000000004', 'Claims Support | Triple H Insurance Broker', 'en/claims', '2026-09-25 14:05:43.993929+00', '{"Title": "Insurance Claims Support in Lebanon | Triple H Insurance Broker", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Insurance Claims Support | Triple H Insurance Broker", "ImageUrl": "", "Description": "Report a claim and rely on Triple H for dedicated support, insurer coordination and professional claims guidance throughout the process."}, "Description": "Get insurance claims support in Lebanon from Triple H, with dedicated broker guidance from notification and assessment through to settlement.", "CanonicalUrl": "https://triplehbroker.com/en/claims"}', '2026-08-08 09:46:14.671419+00', false, true, 'en', '4e17f6a5-898d-84d9-d595-fa8971804359', 'claims', '{"type": "page", "children": [{"id": "11000000-0004-0001-0000-000000000001", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "cinematic-tall", "bordered": false}, "content": {"intro": "Report your claim as soon as it is safe to do so. We open the file, explain what is required, deal with the insurer and loss adjuster, and follow the claim through to settlement.", "items": [{"href": "https://wa.me/96181891959", "label": "Report a Claim", "variant": "inverse"}], "eyebrow": "Claims Support", "heading": "Insurance claims support when it matters most.", "imageAlt": "Hands reviewing a printed insurance policy on a desk", "mobileImageUrl": "/uploads/20260925140531-9709ad74f15e45f1b61ab56c5570f06f.webp", "desktopImageUrl": "/uploads/20260925140232-f9c21236ec7440acb75b13bb31bce32d.webp"}, "visible": true, "position": 0, "settings": {"sectionType": "hero-banner"}}, {"id": "11000000-0004-0004-0000-000000000004", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "editorial-split", "bordered": true}, "content": {"intro": "We are reachable 24/7 – If anyone is injured, contact the emergency services, seek medical attention and make the scene safe. Insurance paperwork can wait until everyone is safe.", "heading": "Safety comes first.", "buttonHref": "", "buttonLabel": ""}, "visible": true, "position": 3, "settings": {"sectionType": "callout"}}, {"id": "11000000-0004-0002-0000-000000000002", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "numbered-grid", "bordered": true}, "content": {"intro": "Once you notify us, we open the claim, confirm the documents required, coordinate with the insurer and any appointed loss adjuster, and follow the file through assessment and settlement.", "items": [{"body": "Contact us as soon as reasonably possible and provide a clear account of what happened.", "title": "Notify us"}, {"body": "We confirm what is required, organize the supporting documents and submit the claim to the insurer.", "title": "We prepare the claim file"}, {"body": "We coordinate with the insurer and any appointed loss adjuster, respond to queries and keep the claim progressing.", "title": "We manage the follow-up"}, {"body": "We review the assessment against your policy terms and advocate on your behalf where clarification or challenge is needed, then follow the claim through to settlement.", "title": "We review, advocate and follow through"}], "layout": "grid", "eyebrow": "Claim Process", "heading": "How does an insurance claim work?"}, "visible": true, "position": 1, "settings": {"sectionType": "steps"}}, {"id": "11000000-0004-0003-0000-000000000003", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "editorial-split", "bordered": true}, "content": {"intro": "Requirements vary by claim and insurer. Send us what you have, and we’ll confirm exactly what is needed for your claim.", "items": [{"text": "Details of what happened, including the date and location"}, {"text": "Photographs or videos of the damage, where relevant"}, {"text": "Police, medical or other official reports, where applicable"}, {"text": "Invoices, receipts, repair estimates or supporting costs"}, {"text": "Medical reports, prescriptions or test results for medical claims"}, {"text": "Details of any other parties involved"}], "heading": "What should you prepare for a claim?"}, "visible": true, "position": 2, "settings": {"sectionType": "feature-list"}}, {"id": "b1302323-5f2f-42f2-b19b-86d59ef7881a", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "Clear answers to important questions about claim decisions, settlement, policy excesses and renewal.", "items": [{"answer": "Triple H remains your point of contact throughout the claim, so you do not need to manage communications with the insurer yourself.", "question": "Q1 – Who handles my insurance claim?"}, {"answer": "Report an incident as soon as reasonably possible. Notification requirements vary by policy, and you do not need to wait until every supporting document is available.", "question": "Q2 – How quickly should I report a claim?"}, {"answer": "Before cover begins, we explain the key terms, limits and exclusions so you understand what the policy provides. If a claim is declined, we review the reason against those terms and pursue the matter with the insurer where cover applies.", "question": "Q3 – What happens if a claim is declined?"}, {"answer": "Many claims are settled directly between the insurer and an approved provider. Where reimbursement applies, you provide the supporting documents and we handle the claim with the insurer on your behalf.", "question": "Q4 – How is an insurance claim settled?"}, {"answer": "Where applicable, an excess or deductible is the fixed amount or percentage of an eligible claim that remains payable by you. Any such amount is explained before you accept the policy.", "question": "Q5 – What is an excess or deductible?"}, {"answer": "A claim does not usually change your premium automatically. In some cases, claim history may affect renewal pricing or terms, and any impact will be explained clearly at renewal.", "question": "Q6 – Can making a claim affect my premium?"}], "heading": "Claims: common questions", "showArrows": true, "smoothMotion": true}, "visible": true, "children": [], "settings": {"sectionType": "faq"}}, {"id": "f937d003-6eef-4da1-989a-e365a27ec4fe", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "b06cf0ff-359a-40b6-be08-d33d6fa3f0ce", "type": "container", "visible": true, "children": [{"id": "f036143f-7237-4b27-a5c2-d52d19476ce3", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Need help with a claim?", "level": 2}, "visible": true}, {"id": "26677e10-e602-4cf4-9d85-36bb385fb95d", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Our claims team is available 24/7 for new and ongoing claims."}, "visible": true}, {"id": "9cb11742-21d3-40e4-8008-f194caad85eb", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Report a Claim", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "claims", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('509a8873-3d08-4dc7-b341-86f9dd5cf4a6', 'Insurance Industries | Triple H Insurance Broker', 'en/industries', '2026-09-27 15:08:22.486255+00', '{"Title": "Business Insurance by Industry in Lebanon | Triple H", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Insurance Built Around Your Industry | Triple H Insurance Broker", "ImageUrl": null, "Description": "Tailored business insurance for a wide range of industries in Lebanon, arranged around the risks and needs of each sector."}, "Description": "Explore business insurance by industry in Lebanon. Triple H arranges tailored cover for NGOs, healthcare, construction, retail, logistics, technology and more.", "CanonicalUrl": "https://triplehbroker.com/en/industries"}', '2026-08-19 12:02:46.786083+00', false, false, 'en', 'a79230c0-d2f3-4d2d-b1a2-0b5df30679af', 'industries', '{"type": "page", "children": [{"id": "9d121240-5590-4cab-bdd4-c2d9c0acaada", "type": "section", "styles": {"preset": "cinematic-tall"}, "content": {"intro": "Different industries face different risks. We assess how your business operates in Lebanon and arrange the cover it needs across property, liability, people, vehicles and specialist risks.", "items": [], "eyebrow": "INDUSTRIES", "heading": "Business insurance built around your industry.", "imageAlt": "", "mobileImageUrl": "/uploads/20260925132957-8df9e7880c84438aae1c6af9081c9500.webp", "desktopImageUrl": "/uploads/20260925132711-186f218ca80e44f682cf8853f61fc4ad.webp"}, "visible": true, "children": [], "settings": {"layoutGroup": "", "sectionType": "hero-banner", "layoutColumn": 1}}, {"id": "c2e41400-503a-422d-93bf-cc93ed42110e", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "visible": true, "children": [{"id": "a234f4d3-7475-4017-9f82-b2d8447e73f2", "type": "container", "visible": true, "children": [{"id": "6b80626b-fafc-482f-8e61-5c85d8d18239", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Why does business insurance differ by industry?", "level": 2}, "visible": true}, {"id": "3c65b6bf-0f24-4647-b8f9-2271b4381a57", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Every industry carries a different combination of risks, which is why business insurance should reflect how the business actually operates. A healthcare provider may need medical malpractice and cyber protection, while a contractor may require project, equipment and employer liability cover. We assess the nature of your operations and arrange the combination of insurance needed to protect your business properly."}, "visible": true}]}], "settings": {"sectionType": "text"}}, {"id": "310bc57c-71fe-4a6e-bc77-a756bfa97bdf", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px"}}, "content": {"intro": "We arrange business insurance across a wide range of sectors, tailoring the cover to the risks, responsibilities and operating needs of each industry.", "items": [{"href": "", "title": "Healthcare", "summary": "Hospitals, clinics, pharmacies and laboratories, with cover arranged across medical malpractice, property and equipment, cyber risks, employee benefits and public liability.", "imageAlt": "", "imageUrl": "/uploads/20260926233047-a5bb5e23ca53416486bbc30190b963ac.webp", "linkLabel": ""}, {"href": "", "title": "Construction", "summary": "Contractors, developers and engineering businesses, with cover for projects, plant and machinery, employee risks, professional liability and third-party exposures.", "imageAlt": "", "imageUrl": "/uploads/20260926233050-f20dd4568aa04baaabaf8cc7ebea0874.webp", "linkLabel": ""}, {"href": "", "title": "Manufacturing", "summary": "Factories, workshops and industrial businesses, with cover for property, machinery, business interruption, product liability and employee risks.", "imageAlt": "", "imageUrl": "/uploads/20260926233053-ffb44b4937594e0083b1320a023f9c5f.webp", "linkLabel": ""}, {"href": "", "title": "Retail & Wholesale", "summary": "Shops, showrooms, wholesalers, distributors and warehouses, with cover for property, stock, business interruption, liability, money and goods in transit.", "imageAlt": "", "imageUrl": "/uploads/20260926233102-84bf1410765f4deb82f2850ca7912933.webp", "linkLabel": ""}, {"href": "", "title": "Hospitality", "summary": "Hotels, resorts, guest houses and hospitality businesses, with cover for property, liability, business interruption, guest-related risks and employee benefits.", "imageAlt": "", "imageUrl": "/uploads/20260926233105-56ca782f195b4817990ab7d5edd02be4.webp", "linkLabel": ""}, {"href": "", "title": "Restaurants & Cafés", "summary": "Restaurants, cafés, bakeries and catering businesses, with cover for property, food and product liability, stock, business interruption and employee risks.", "imageAlt": "", "imageUrl": "/uploads/20260927122133-03edb2f45d5f4b80bf8c80f80b970bd8.webp", "linkLabel": ""}, {"href": "", "title": "Real Estate", "summary": "Property developers, owners, landlords and property managers, with cover for buildings, liability, rental income, construction risks and professional exposures.", "imageAlt": "", "imageUrl": "/uploads/20260927122138-e78b5cfa00ee47b2981309259a85d15e.webp", "linkLabel": ""}, {"href": "", "title": "Professional Firms", "summary": "Law firms, accountants, consultants, engineers and other professional practices, with cover for professional liability, cyber risks, offices, employees and management exposures.", "imageAlt": "", "imageUrl": "/uploads/20260927122150-b6dbeb94074b4f8badba00c1e5a26bde.webp", "linkLabel": ""}, {"href": "", "title": "Financial Services", "summary": "Financial institutions, fintech businesses, investment and advisory firms, with cover for professional liability, cyber risks, management liability and operational exposures.", "imageAlt": "", "imageUrl": "/uploads/20260927122156-0a128177886e47a4af642a356ba438d2.webp", "linkLabel": ""}, {"href": "", "title": "Technology", "summary": "Software companies, IT providers, digital businesses and technology firms, with cover for professional liability, cyber risks, electronic equipment, employees and third-party liability.", "imageAlt": "", "imageUrl": "/uploads/20260927122202-1fdbda8bb64f48f58770a3348855ff7a.webp", "linkLabel": ""}, {"href": "", "title": "Transport, Shipping & Logistics", "summary": "Fleet operators, haulers, shipping businesses, delivery operators and logistics companies, with cover for vehicles, vessels, marine liability, goods in transit, property and employee risks.", "imageAlt": "", "imageUrl": "/uploads/20260927122506-c448e5b2eb91424bbbe3439dd65debc7.webp", "linkLabel": ""}, {"href": "", "title": "Import & Export", "summary": "Importers, exporters, traders and distributors, with cover for cargo, goods in transit, stock, product liability and business interruption.", "imageAlt": "", "imageUrl": "/uploads/20260927122513-e172e10949b0494b9c2c9a18a3654cf6.webp", "linkLabel": ""}, {"href": "", "title": "Automotive & Motor Trade", "summary": "Vehicle dealerships, garages, repair centers and motor-trade businesses, with cover for premises, vehicles, liability, equipment, stock and employee risks.", "imageAlt": "", "imageUrl": "/uploads/20260927125008-97d354ad2cf046ae8009166054d56081.webp", "linkLabel": ""}, {"href": "", "title": "Schools & Education", "summary": "Schools, universities, nurseries and training centers, with cover for property, liability, students, employees, cyber risks and personal accident.", "imageAlt": "", "imageUrl": "/uploads/20260927125530-31676920c5a44aada885916e9b338ff6.webp", "linkLabel": ""}, {"href": "", "title": "NGOs & Associations", "summary": "Non-profit organizations, foundations and associations, with cover for management liability, employees, volunteers, property, travel and public liability.", "imageAlt": "", "imageUrl": "/uploads/20260927125755-01d232e5ad9e4481aee19f04aaedbacc.webp", "linkLabel": ""}, {"href": "", "title": "Energy & Utilities", "summary": "Energy producers, utilities and service providers, with cover for property, plant and machinery, project risks, business interruption and third-party liability.", "imageAlt": "", "imageUrl": "/uploads/20260927144104-896f671587e24845a75272a4b50b4c74.webp", "linkLabel": ""}, {"href": "", "title": "Agriculture & Food", "summary": "Farms, food producers, processors and distributors, with cover for property, stock, equipment, product liability, employee risks and goods in transit.", "imageAlt": "", "imageUrl": "/uploads/20260927144456-40072ba3e2cb4cefb774662c7cfcf875.webp", "linkLabel": ""}, {"href": "", "title": "Media & Communications", "summary": "Media companies, publishers, agencies and communications businesses, with cover for professional and media liability, cyber risks, equipment, property and employees.", "imageAlt": "", "imageUrl": "/uploads/20260927145319-c6ad4118eab1458f8a494fcd99848257.webp", "linkLabel": ""}, {"href": "", "title": "Events & Entertainment", "summary": "Event organizers, venues, production companies and entertainment businesses, with cover for public liability, equipment, property, cancellation-related risks and employees.", "imageAlt": "", "imageUrl": "/uploads/20260927150149-1f4c3e94704c4da3b5790d2fded5e647.webp", "linkLabel": ""}, {"href": "", "title": "Other Industries & Specialist Risks", "summary": "We support businesses across a wide range of industries, arranging cover around their activities, people, property, liabilities and specialist exposures.", "imageAlt": "", "imageUrl": "/uploads/20260927150813-589ef39ea3884b3b8eeaf0f16d89471c.webp", "linkLabel": ""}], "heading": "Industries we support"}, "visible": true, "children": [], "settings": {"sectionType": "solutions-catalog"}}, {"id": "8f04dd8d-678d-4244-bae1-d79baa06e85f", "type": "section", "styles": {"mobile": {"paddingTop": "48px", "paddingBottom": "48px"}, "desktop": {"paddingTop": "80px", "paddingBottom": "80px", "backgroundColor": "var(--inverse)"}}, "visible": true, "children": [{"id": "85282906-b306-4612-9f56-60a796248a46", "type": "container", "visible": true, "children": [{"id": "a0e0e2cb-7087-4882-843b-2ec5e5e5aa2d", "type": "heading", "styles": {"mobile": {"fontSize": "32px"}, "desktop": {"fontSize": "44px"}}, "content": {"text": "Let’s discuss your business insurance needs.", "level": 2}, "visible": true}, {"id": "bf628ade-b25c-44a6-ad4e-d7113beea043", "type": "text", "styles": {"desktop": {"fontSize": "17px", "maxWidth": "62ch", "lineHeight": "1.7"}}, "content": {"text": "Tell us about your business, and our team will arrange the right combination of cover for its risks, people and operations."}, "visible": true}, {"id": "7ff4e1cc-93bf-4a45-a5da-8883ba998f73", "type": "button", "content": {"href": "/en/contact", "label": "Request a Business Quote", "variant": "inverse"}, "visible": true}, {"id": "6ac93e32-341a-4abb-8456-284158572e34", "type": "button", "content": {"href": "https://wa.me/96181891959", "label": "Enquire on WhatsApp", "variant": "inverse"}, "visible": true}]}], "settings": {"imageAlt": "", "sectionType": "call-to-action", "mobileImageUrl": "", "desktopImageUrl": ""}}], "settings": {"headerMode": "media-overlay", "footerVisible": true}, "template": "builder", "schemaVersion": 1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", seo_data, "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('10000000-0000-0000-0000-000000000006', 'Contact Us | Triple H Insurance Broker', 'en/contact', '2026-08-26 19:41:33.423391+00', '{"Title": "Contact Triple H | Insurance Broker in Lebanon", "Robots": {"Index": true, "Follow": true}, "OpenGraph": {"Title": "Contact Triple H | Insurance Broker in Lebanon", "ImageUrl": "", "Description": "Get in touch with Triple H for insurance quotes, policy support, renewals, claims and general enquiries in Lebanon."}, "Description": "Contact Triple H Insurance Broker in Lebanon for quotes, policy support, renewals, claims and general insurance enquiries.", "CanonicalUrl": "https://triplehbroker.com/en/contact"}', '2026-08-08 07:24:01.158154+00', false, true, 'en', 'd8776c6f-3a64-e6e6-7901-01cdefbacb15', 'contact', '{"type": "page", "children": [{"id": "11000000-0006-0001-0000-000000000001", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "cinematic-tall", "bordered": false}, "content": {"intro": "Whether you are looking for a quote, insurance advice or support with an existing policy, our team is here to help.", "items": [], "eyebrow": "Contact Us", "heading": "Let’s talk about your insurance needs.", "imageAlt": "Insurance broker welcoming a client", "mobileImageUrl": "https://triplehbroker.com/uploads/20260808072344-e3e8a92a181349fcb5acdd0bccd750bc.webp", "desktopImageUrl": "https://triplehbroker.com/uploads/20260808072344-e3e8a92a181349fcb5acdd0bccd750bc.webp"}, "visible": true, "position": 0, "settings": {"sectionType": "hero-banner"}}, {"id": "11000000-0006-0004-0000-000000000004", "type": "section", "styles": {"size": "base", "tone": "default", "preset": "default", "bordered": true}, "content": {"intro": "Choose the most convenient way to reach us for quotations, policy support, renewals or general insurance enquiries.", "i