INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('02f04d37-2d85-5c62-9296-5eaf5b44ea06', 'تأمين البضائع | تريبل إتش وسيط التأمين', 'ar/solutions/cargo-insurance', '2026-10-12 11:00:07+00', '{"Title":"تأمين البضائع في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين البضائع في لبنان | تريبل إتش وسيط التأمين","ImageUrl":null,"Description":"احمِ البضائع أثناء نقلها بحراً أو جواً أو براً بتأمين بضائع ترتّبه تريبل إتش وسيط التأمين في لبنان."},"Description":"تأمين بضائع في لبنان للسلع المنقولة بحراً أو جواً أو براً. قارن شركات التأمين ورتّب التغطية المناسبة مع تريبل إتش وسيط التأمين.","CanonicalUrl":"https://www.triplehbroker.com/ar/solutions/cargo-insurance"}', '2026-10-12 11:00:07+00', false, false, 'ar', 'd7d49dba-adc5-4b7a-9807-41045ced2962', 'builder', '{"type":"page","children":[{"id":"09719fd0-ccf3-5697-b557-29b31034c6e0","type":"section","styles":{"preset":"cinematic-tall"},"content":{"intro":"احمِ بضائعك من الفقد أو الضرر المادي أثناء نقلها بحراً أو جواً أو براً، بتغطية تُرتَّب وفق البضائع ومسار كل شحنة وقيمتها.","items":[{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"}],"eyebrow":"تأمين الأعمال والموظفين","heading":"تأمين البضائع","imageAlt":"","mobileImageUrl":"","desktopImageUrl":""},"visible":true,"children":[],"settings":{"sectionType":"hero-banner"}},{"id":"d3daac70-3c3e-5f27-a99e-b902f0d77d2d","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يحمي تأمين البضائع السلع من الفقد أو الضرر المادي أثناء نقلها بحراً أو جواً أو براً. تقارن تريبل إتش شركات التأمين المناسبة في السوق اللبنانية وترتّب التغطية وفق البضائع وقيمة الشحنة ومسارها وطريقة نقلها ومستوى الحماية المطلوب.","eyebrow":"تأمين البضائع","heading":"ما هو تأمين البضائع؟","audience":"المستوردون والمصدرون والمصنّعون والتجار والموزعون الذين يحتاجون إلى حماية البضائع أو المواد الخام أو المنتجات النهائية أثناء النقل.","buttonHref":"/ar/contact","buttonLabel":"اطلب عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"children":[],"settings":{"sectionType":"solution-introduction"}},{"id":"ceeaf942-6159-5fd6-a58f-996ff5ba9495","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"0ec97fe6-b8cb-54b5-88bb-d4ebfbae2f20","type":"container","visible":true,"children":[{"id":"6efa3993-7924-5137-bb30-5f63fc091c45","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"كيف يمكن تنظيم تغطية البضائع؟","level":2},"visible":true},{"id":"c9b69f78-6c5d-5f4d-91fe-45b0bde59c3d","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن تنظيم التغطية وفق وتيرة الشحن ومستوى الحماية المطلوب ووسائل النقل المستخدمة وأي مخاطر إضافية يجب تأمينها."},"visible":true},{"id":"9102be8e-70c2-5f30-b0eb-f5ced44eddc7","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"a5bdf605-79d2-544e-b5f2-b48ed25982e4","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"322ee170-93a5-56ca-901b-5978c9c7c6ca","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"تغطية شحنة واحدة","level":3},"visible":true},{"id":"9b4e10eb-5e0b-5810-b3ed-c7e67e94cf68","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن ترتيب تغطية لشحنة منفردة عند نقل البضائع بصورة متقطعة، بناءً على البضائع والقيمة المؤمّنة والمسار ووسيلة النقل."},"visible":true}]},{"id":"e7006266-415f-5755-bd47-f707fe3e098f","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"92fe63ef-48ba-5bdb-8050-6a78dead62f5","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"تغطية مفتوحة للبضائع","level":3},"visible":true},{"id":"fcc9b922-cf9b-593a-b50e-b631727c8e6b","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن للشركات التي تشحن بانتظام ترتيب تغطية مفتوحة للشحنات المؤهلة خلال فترة متفق عليها، مع التصريح بالشحنات وفق الترتيب بدلاً من تأمين كل شحنة بشكل منفصل."},"visible":true}]},{"id":"060c94b1-af37-5b3f-a9f5-038b9eea396f","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"860cfecf-fff7-5d0b-845a-89e4470aec47","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"شروط معهد تأمين البضائع","level":3},"visible":true},{"id":"a7930514-690b-549e-9a19-99ff595dafa7","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن ترتيب التغطية وفق شروط معهد تأمين البضائع A أو B أو C، ويتيح كل شرط مستوى مختلفاً من الحماية ضد الفقد أو الضرر أثناء النقل."},"visible":true}]},{"id":"34b75ca6-f5ba-54e6-acbd-d6e88e3ec11e","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"ac21e81c-17a3-51d8-9dab-c9d474a88fca","type":"heading","content":{"text":"مخاطر نقل إضافية","level":3},"visible":true},{"id":"1a013519-bf61-5d58-8e04-fefda22f88fb","type":"text","content":{"text":"يمكن ترتيب حماية إضافية لمخاطر مثل الحرب والإضرابات عند الحاجة وتوافرها، بحسب المسار ووسيلة النقل وشروط الوثيقة."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"12b28ac4-5bc1-53e6-b037-4dd143c8650d","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن شركات التأمين وشروط معهد تأمين البضائع والقيم المؤمّنة والمسارات ووسائل النقل ومبالغ التحمل والتوسعات والاستثناءات، ونرتّب تغطية مناسبة لشحناتك، ونتولى المطالبات مع شركة التأمين من الإبلاغ مروراً بالتقييم وصولاً إلى التسوية.","intro":"بحسب الوثيقة ومستوى الحماية المختار، يمكن أن يغطي تأمين البضائع الفقد أو الضرر المادي أثناء النقل ومخاطر مناولة ونفقات نقل معينة ومخاطر إضافية حيث تُدرج صراحةً.","items":[{"text":"الفقد أو الضرر المادي أثناء النقل"},{"text":"السرقة والسرقة الجزئية وعدم التسليم، حيث تشملها التغطية"},{"text":"الكسر والتسرب والتلوث، حيث تشملها التغطية"},{"text":"مخاطر التحميل والتفريغ والمناولة، حيث تشملها التغطية"},{"text":"المساهمات في الخسارة البحرية المشتركة والإنقاذ"},{"text":"التخزين أثناء النقل وإعادة الشحن، وفق شروط الوثيقة"},{"text":"نفقات المعاينة والحد من الخسائر، حيث تشملها التغطية"},{"text":"مخاطر الحرب والإضرابات، عند إضافتها"},{"text":"النقل البحري والجوي والبري"}],"heading":"ماذا يمكن أن يغطي تأمين البضائع؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"91101fa1-1206-5be4-a756-9ae0ce72ccca","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تعتمد وثيقة البضائع المناسبة على أكثر من القسط. فمستوى التغطية والقيمة المؤمّنة وشروط النقل ووتيرة الشحن والاستثناءات وشروط المطالبات يمكن أن تحدث فرقاً كبيراً في الحماية المقدمة.","items":[{"text":"سمعة شركة التأمين وخبرتها في البضائع وقوتها المالية وسجلها في معالجة المطالبات"},{"text":"شروط معهد تأمين البضائع ومستوى الحماية المختار"},{"text":"أساس القيمة المؤمّنة وأقصى قيمة لكل شحنة"},{"text":"تغطية شحنة منفردة أو تغطية سنوية مفتوحة ومتطلبات التصريح"},{"text":"المناشئ والوجهات والمسارات ووسائل النقل المشمولة"},{"text":"نقطتا بدء النقل ونهايته وشروط التخزين وإعادة الشحن"},{"text":"نوع البضائع ومتطلبات التغليف والقيود الخاصة بكل سلعة"},{"text":"مبالغ التحمل والحدود الفرعية وسائر شروط الوثيقة"},{"text":"شروط أو توسعات الحرب والإضرابات والقرصنة وغيرها من المخاطر الخاصة"},{"text":"أساس تسوية المطالبات ومتطلبات المعاينة وإجراءات تقييم شركة التأمين"}],"heading":"ما الذي ينبغي مقارنته قبل اختيار تأمين البضائع؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"5c87defb-067b-572d-aae4-944f3e2b855b","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"نراجع ما تشحنه وكيفية نقله ونقارن شركات التأمين المناسبة في السوق اللبنانية وشروط البضائع، ثم نرتّب التغطية المختارة ونحافظ على توافقها مع شحناتك.","items":[{"body":"نراجع نوع البضائع وقيم الشحنات والتغليف والمناشئ والوجهات ووسائل النقل ووتيرة الشحن.","title":"مراجعة بضائعك ونقلها"},{"body":"نقارن شركات التأمين في لبنان من حيث شروط معهد تأمين البضائع والقيم المؤمّنة ومبالغ التحمل وشروط النقل والتوسعات والاستثناءات والقسط.","title":"مقارنة شركات التأمين المناسبة"},{"body":"نرتّب التغطية المختارة ونؤكد البضائع المؤمّنة وشروط النقل ونرتّب مستندات الوثيقة أو الشحنة المطلوبة.","title":"ترتيب التغطية المختارة"},{"body":"للشاحنين المنتظمين، نتولى التصريحات ذات الصلة وتعديلات الوثيقة وتجديداتها مع تغير قيم الشحنات أو المسارات أو البضائع أو ترتيبات النقل.","title":"إدارة الشحنات المستمرة"}],"layout":"grid","heading":"كيف نرتّب تأمين البضائع؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"25f1d1db-719b-5210-9502-b328c5fcf664","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تواصل مع تريبل إتش فور علمك بفقد أو ضرر. ندير المطالبة مع شركة التأمين من الإبلاغ مروراً بالتقييم وصولاً إلى التسوية وننسّق الإجراءات نيابةً عنك.","items":[{"text":"نُبلغ شركة التأمين ونؤكد المستندات المطلوبة ونساعدك على تقديم الصور ومستندات النقل والفواتير وغيرها من الأدلة الداعمة."},{"text":"ننسّق مع شركة التأمين وخبير المعاينة والناقل عند الحاجة، ونتابع التقييم أثناء تحديد سبب الخسارة وحجمها."},{"text":"نراجع التسوية المقترحة وفق شروط الوثيقة ونواصل متابعة المطالبة حتى تنهي شركة التأمين الإجراءات وتُسوّى أي مبالغ مغطاة."}],"heading":"ما الذي تفعله عند فقد بضائعك أو تضررها أثناء النقل؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"35fbc066-5558-5005-9e37-c6425f2e2a9d","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عملية عن تغطية البضائع وشروط معهد تأمين البضائع والتغطية المفتوحة وشروط النقل وقيم الشحنات والمطالبات والمعلومات المطلوبة لترتيب التأمين.","items":[{"answer":"يغطي تأمين البضائع السلع المنقولة. ويمكن أن يغطي التأمين البحري السفينة والآلات والمسؤوليات البحرية ذات الصلة. يحمي كل منهما مخاطر مختلفة.","question":"س1 – ما الفرق بين تأمين البضائع والتأمين البحري؟"},{"answer":"نعم. يمكن ترتيب تغطية للنقل البحري والجوي والبري، بما فيه النقل الداخلي عند الحاجة، وفق المسار المتفق عليه وشروط الوثيقة.","question":"س2 – هل يغطي تأمين البضائع النقل بحراً وجواً وبراً؟"},{"answer":"توفر مستويات مختلفة من حماية البضائع. يتيح الشرط A أوسع تغطية، بينما يغطي الشرطان B وC مخاطر محددة، ويوفر الشرط C الحماية الأضيق.","question":"س3 – ما هي شروط معهد تأمين البضائع A وB وC؟"},{"answer":"صُممت التغطية المفتوحة للشركات التي تشحن بانتظام. بدلاً من ترتيب وثيقة منفصلة لكل شحنة، يُصرَّح بالشحنات المؤهلة ضمن ترتيب وثيقة متفق عليه.","question":"س4 – ما هي التغطية المفتوحة للبضائع؟"},{"answer":"قد تمتد التغطية من مغادرة البضائع مكان المنشأ المتفق عليه حتى تسليمها في الوجهة المتفق عليها، وفق شرط النقل والحدود الزمنية وشروط الوثيقة.","question":"س5 – متى تبدأ تغطية البضائع ومتى تنتهي؟"},{"answer":"لا. مسؤولية الناقل منفصلة وقد تخضع لحدود ودفوع تعاقدية أو قانونية. يحمي تأمين البضائع السلع المؤمّنة وفق التغطية المرتبة.","question":"س6 – هل تحل مسؤولية الناقل محل تأمين البضائع؟"},{"answer":"يعتمد ذلك على عقد البيع ووقت انتقال المسؤولية عن البضائع بين الأطراف. نراجع شروط الشحنة ونؤكد صاحب المصلحة التأمينية قبل ترتيب التغطية.","question":"س7 – من يجب أن يؤمّن البضائع: المشتري أم البائع؟"},{"answer":"ليس بالضرورة. عادةً تخضع الحرب والإضرابات لشروط أو بنود أو توسعات منفصلة، لذا يجب التحقق منها تحديداً عند ترتيب التغطية.","question":"س8 – هل الحرب والإضرابات مغطاة تلقائياً؟"},{"answer":"نعم. يجب تغليف البضائع بما يناسب طبيعتها ورحلتها. نساعدك على فهم متطلبات شركة التأمين ذات الصلة قبل ترتيب التغطية لتُؤمَّن الشحنة على الأساس الصحيح.","question":"س9 – هل تؤثر طريقة تغليف البضائع؟"},{"answer":"احتفظ بالبضائع والتغليف إن أمكن ووثّق الضرر وتواصل مع تريبل إتش سريعاً. نُبلغ شركة التأمين وننسّق المعاينة المطلوبة ونتولى إجراءات المطالبة نيابةً عنك.","question":"س10 – ماذا نفعل إذا وصلت البضائع متضررة أو فُقد جزء من الشحنة؟"},{"answer":"قد تطلب شركة التأمين الوثيقة أو الشهادة ومستند النقل والفاتورة التجارية وقائمة التعبئة وسجلات التسليم والصور والمراسلات مع الناقل وأي تقرير معاينة. ننسّق المستندات المطلوبة.","question":"س11 – ما المستندات التي قد تُطلب لمطالبة بضائع؟"},{"answer":"نحتاج عادةً إلى نوع البضائع وقيمة الشحنة وطريقة التغليف والمنشأ والوجهة ووسيلة النقل ووتيرة الشحن وأي تغطية إضافية أو مخاطر خاصة تريد دراستها.","question":"س12 – ما المعلومات المطلوبة للحصول على عرض تأمين بضائع؟"}],"heading":"الأسئلة الشائعة حول تأمين البضائع","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"769dabbd-e1ed-52a4-b9f7-4ca310e93699","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف تغطيات أخرى لحماية سفنك وممتلكاتك وأنشطة أعمالك إلى جانب تأمين البضائع.","heading":"تأمينات أخرى للأعمال","buttonHref":"/ar/solutions/business","buttonLabel":"استكشف تأمين الأعمال"},"visible":true,"children":[],"settings":{"sectionType":"callout"}},{"id":"847aac71-5322-5377-8591-db6ebbd191a3","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"9b7980d5-ca7a-53c7-b379-a6ffd6b25bb1","type":"container","visible":true,"children":[{"id":"3a0f98be-4b86-583d-a8c2-9143661bfc38","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"احصل على عرض تأمين بضائع","level":2},"visible":true},{"id":"3afa16fb-2aa4-58da-8e2e-519216e492e5","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أخبرنا عن بضائعك وقيمة الشحنة ومنشئها ووجهتها ووسيلة النقل. سنقارن شركات التأمين المناسبة ونقدم خيارات مكتوبة وواضحة."},"visible":true},{"id":"7a806a02-7fb1-5682-bb42-b2f7e09c9af6","type":"button","content":{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},"visible":true},{"id":"df06ce5e-0886-5f06-b00f-d058cc2366f3","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"builder","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('20000000-0000-0000-0000-000000000005', 'اطلب عرض سعر', 'ar/quote', '2026-10-12 11:00:07+00', '{"Title":"احصل على عرض تأمين في لبنان | تريبل إتش للتأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"احصل على عرض تأمين في لبنان | تريبل إتش للتأمين","ImageUrl":null,"Description":"اطلب عرض تأمين من تريبل إتش واحصل على مقارنة مخصصة وفق احتياجاتك التأمينية الشخصية أو التجارية."},"Description":"اطلب عرض تأمين في لبنان من تريبل إتش. أخبرنا بما تحتاج إلى حمايته وسيقدم مستشارونا مقارنة تأمينية مخصصة.","CanonicalUrl":"https://triplehbroker.com/ar/quote"}', '2026-08-08 09:48:19.745619+00', false, true, 'ar', '3705bf5c-a664-bcfa-6086-7fa43204dd71', 'quote', '{"type":"page","children":[{"id":"2c077df0-bf01-5ded-8f5c-0a4b3003b8ae","type":"section","styles":{"size":"base","tone":"default","preset":"cinematic-tall","bordered":false},"content":{"intro":"ثلاث خطوات قصيرة. يراجع مستشار كل طلب شخصياً ويرد خلال يوم عمل واحد.","items":[],"eyebrow":"طلب عرض سعر","heading":"اطلب عرض سعر","mobileImageUrl":"/uploads/20260925155651-b040f57765234beab6e87ed803d19d5c.webp","desktopImageUrl":"/uploads/20260925155344-fa2b7c96a32047e39f07eb9eaf3a41f6.webp"},"visible":true,"position":0,"settings":{"sectionType":"hero-banner"}},{"id":"6fb4e025-d055-532c-a9f1-566cd726626f","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"","items":[{"name":"covers","step":"التغطية","type":"checkbox-group","label":"ما الذي ترغب في تأمينه؟","source":"solution-pages","options":[],"required":true,"placeholder":""},{"name":"coverFor","step":"التفاصيل","type":"select","label":"الجهة المؤمّنة","source":"","options":["أنا أو عائلتي","شركتي"],"required":false,"placeholder":""},{"name":"existing","step":"التفاصيل","type":"select","label":"هل لديك تغطية حالياً؟","source":"","options":["نعم، أرغب في التجديد","لا، هذه المرة الأولى","غير متأكد"],"required":false,"placeholder":""},{"name":"budget","step":"التفاصيل","type":"text","label":"الميزانية السنوية التقريبية","source":"","options":[],"required":false,"placeholder":""},{"name":"notes","step":"التفاصيل","type":"textarea","label":"أي معلومات ينبغي أن نعرفها","source":"","options":[],"required":false,"placeholder":"شركة التأمين الحالية، مبالغ التأمين، مخاوف محددة…"},{"name":"name","step":"التواصل","type":"text","label":"الاسم الكامل","source":"","options":[],"required":true,"placeholder":""},{"name":"email","step":"التواصل","type":"email","label":"عنوان البريد الإلكتروني","source":"","options":[],"required":true,"placeholder":""},{"name":"phone","step":"التواصل","type":"tel","label":"الهاتف","source":"","options":[],"required":true,"placeholder":""},{"name":"preferred","step":"التواصل","type":"select","label":"وسيلة التواصل المفضلة","source":"","options":["البريد الإلكتروني","الهاتف","واتساب"],"required":false,"placeholder":""}],"heading":"المزيد من التفاصيل","backLabel":"رجوع","nextLabel":"متابعة","recipient":"","submitLabel":"إرسال الطلب","successMessage":"شكراً لك. سيراجع مستشار طلبك ويرد خلال يوم عمل واحد."},"visible":true,"settings":{"sectionType":"multi-step-form"}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"quote","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('610016f7-b5ba-4c47-ad9b-b52c610a3ce8', 'التأمين الصحي | تريبل إتش وسيط التأمين', 'ar/solutions/health', '2026-10-12 11:00:07+00', '{"Title":"التأمين الصحي للأفراد والعائلات في لبنان | تريبل إتش","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"التأمين الصحي للأفراد والعائلات | تريبل إتش وسيط التأمين","ImageUrl":"https://triplehbroker.com/uploads/20260816184252-b4559109afd8488f964382ca0980acda.webp","Description":"استكشف التأمين الصحي للأفراد والعائلات في لبنان مع مقارنات واضحة للشبكات والمنافع والحدود والشروط."},"Description":"قارن التأمين الصحي للأفراد والعائلات في لبنان. تقارن تريبل إتش شركات التأمين المناسبة والشبكات والمنافع والحدود والشروط وترتّب تغطيتك.","CanonicalUrl":"https://triplehbroker.com/ar/solutions/health"}', '2026-08-19 12:29:08.134473+00', false, false, 'ar', 'ad93bac6-696d-443e-96cc-f7c66962edf5', 'solution-detail', '{"type":"page","children":[{"id":"2be8d134-0446-5dd8-b2ab-8a668f6782ed","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تأمين صحي للأفراد والعائلات يُرتَّب وفق الرعاية الطبية وشبكة مقدمي الخدمات والنطاق الجغرافي المطلوب. نقارن شركات التأمين المناسبة ونوضح الفروق المهمة ونرتّب الوثيقة وفق احتياجاتك.","eyebrow":"التأمين الشخصي والعائلي","heading":"التأمين الصحي للأفراد والعائلات","audience":"الأفراد والعائلات الباحثون عن تأمين طبي خاص في لبنان أو تغطية صحية دولية مناسبة.","buttonHref":"/ar/quote","buttonLabel":"احصل على عرض سعر فوري","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"settings":{"sectionType":"solution-introduction"}},{"id":"ecb6b21d-303d-529f-916a-66340ff8f9b7","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نتواصل مع شركات التأمين المناسبة ونقارن الشبكات الطبية والمنافع والحدود والاستثناءات والأقساط ونوضح الفروق بوضوح ونرتّب التغطية المناسبة لاحتياجاتك.","intro":"يمكن أن يشمل التأمين الصحي مجموعة من المنافع الطبية، مع تغطية وحدود وشروط تعتمد على الخطة المختارة وشركة التأمين.","items":[{"text":"داخل المستشفى: الاستشفاء والجراحة"},{"text":"داخل المستشفى: العلاج الطبي الطارئ"},{"text":"خارج المستشفى: الفحوص التشخيصية والتصوير والعلاج الفيزيائي"},{"text":"علاج السرطان وغيره من العلاجات الطبية الكبرى"},{"text":"الأمومة ورعاية المولود الجديد"},{"text":"العلاج الطبي الطارئ الدولي"}],"heading":"ما الذي يغطيه؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"settings":{"sectionType":"coverage-details"}},{"id":"0b810836-1397-5bed-b625-4fb63cdbf94e","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يعتمد التأمين الصحي المناسب على أكثر من القسط. هذه بعض النقاط الرئيسية التي ينبغي مقارنتها قبل اختيار الخطة.","items":[{"text":"شبكة المستشفيات ومقدمي الرعاية الطبية"},{"text":"التغطية السنوية الإجمالية وحدود المنافع الفردية"},{"text":"منافع العلاج داخل المستشفى وخارجه"},{"text":"مبالغ التحمل والمشاركة في الدفع"},{"text":"شروط الحالات السابقة للتأمين"},{"text":"فترات الانتظار"},{"text":"النطاق الجغرافي للتغطية"},{"text":"الاستثناءات وشروط الوثيقة"}],"heading":"ما الذي تقارنه؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"62417e5a-3b67-53e0-a9b9-8ee5acdb5a1e","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"من فهم احتياجاتك إلى ترتيب الوثيقة، ندير كل خطوة ونواصل المتابعة بعدها.","items":[{"body":"نفهم احتياجاتك ونحدد الخطط الأكثر ملاءمة للتغطية والمنافع والميزانية التي تبحث عنها.","title":"فهم احتياجاتك"},{"body":"نتواصل مع شركات التأمين المناسبة ونقارن الشبكات والمنافع والحدود والاستثناءات والأقساط.","title":"مقارنة الخيارات المناسبة"},{"body":"نوضح الفروق بوضوح ونساعدك على اختيار الأنسب لاحتياجاتك ونرتّب الوثيقة لك.","title":"الشرح والترتيب"},{"body":"نتولى التواصل مع شركة التأمين ونواصل المتابعة بشأن التعديلات والتجديدات والمطالبات طوال مدة وثيقتك.","title":"المتابعة المستمرة"}],"layout":"grid","eyebrow":"","heading":"كيف نرتّب تأمينك الصحي؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"0aed142e-9ff2-58f6-ad80-bcf90ee1e7f8","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تواصل مع خطنا الساخن المتاح على مدار الساعة طوال الأسبوع عندما تحتاج إلى دعم لاستخدام تأمينك الصحي، وننسّق الترتيبات والموافقات اللازمة نيابةً عنك.","items":[{"text":"إذا احتجت إلى دخول المستشفى وظهرت مشكلة، يمكنك أو أحد أفراد عائلتك التواصل معنا مباشرةً. ننسّق مع فريق الدخول في المستشفى وشركة إدارة المطالبات وشركة التأمين للحصول على الموافقة المطلوبة ليستمر علاجك دون تأخير غير ضروري."},{"text":"للفحوص والتصوير والعلاج الفيزيائي وغيرها من خدمات العلاج خارج المستشفى التي تتطلب موافقة، أخبرنا باليوم والوقت المناسبين. يمكنك اختيار مقدم الرعاية الطبية أو يمكننا اقتراح مقدم مناسب. نرتّب الموعد ونحصل على الموافقة المسبقة المطلوبة، لتكتفي عند وصولك بإبراز بطاقتك الطبية وهويتك أو جواز سفرك والمباشرة بالعلاج الموافق عليه."}],"heading":"ما الذي تفعله عندما تحتاج إلى رعاية طبية؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"938f444c-e754-581a-acc9-a060a5f5b0b0","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عن أسئلة شائعة حول التأمين الصحي للأفراد والعائلات، بما فيها الأقساط والحالات الطبية وشبكات المستشفيات والتغطية العائلية وشروط الوثيقة.","items":[{"answer":"قد يختلف القسط بحسب العمر وشبكة المستشفيات ومنافع العلاج داخلها وخارجها والنطاق الجغرافي وحدود الوثيقة ومبالغ التحمل أو المشاركة في الدفع والاكتتاب الطبي وتسعير شركة التأمين. لا يوفر القسط الأقل بالضرورة الحماية نفسها، لذا نقارن شروط الوثيقة إلى جانب السعر.","question":"س1 – ما الذي يؤثر في تكلفة التأمين الصحي للأفراد والعائلات؟"},{"answer":"يعتمد ذلك على الحالة وشركة التأمين والاكتتاب الطبي. قد تُعرض التغطية بشروط محددة أو فترات انتظار أو قيود أو استثناءات، لذا نقارن الخيارات المتاحة ونشرح الفروق قبل اختيارك.","question":"س2 – هل يمكنني الحصول على تأمين صحي مع حالة سابقة للتأمين أو مرض مزمن؟"},{"answer":"تحدد شبكة المستشفيات المستشفيات ومقدمي الرعاية المتاحين بموجب الوثيقة، وقد تؤثر أيضاً في القسط. نقارن الشبكات المتاحة وفق مستوى الوصول والمستشفيات التي تهمك.","question":"س3 – كيف تؤثر شبكة المستشفيات في تأميني الصحي؟"},{"answer":"يمكن ترتيب تأمين صحي للأفراد والعائلات. وقد تعتمد أهلية الزوج أو الزوجة والأطفال والوالدين على العمر وشروط الإعالة والاكتتاب الطبي وهيكل خطة شركة التأمين.","question":"س4 – هل يمكن إدراج الزوج أو الزوجة أو الأطفال أو الوالدين في تأميني الصحي؟"},{"answer":"قد تكون الأمومة ورعاية المولود الجديد جزءاً من التأمين الصحي، مع حدود وفترات انتظار وشروط أخرى تختلف بحسب الشركة والخطة. نقارن هذه الشروط بعناية لتفهم كيفية تطبيق التغطية قبل اختيار الوثيقة.","question":"س5 – هل يغطي التأمين الصحي الأمومة ورعاية المولود الجديد؟"},{"answer":"قد تخضع بعض المنافع أو الحالات الطبية لفترات انتظار، بينما تسري أخرى من تاريخ بدء الوثيقة. تعتمد فترات الانتظار المطبّقة على شركة التأمين والخطة والاكتتاب الطبي.","question":"س6 – هل تنطبق فترات انتظار على التأمين الصحي؟"},{"answer":"يمكن أن يشمل التأمين الصحي علاجاً طبياً طارئاً دولياً ضمن مناطق محددة، مع خطط توفر تغطية طوارئ عالمية. يعتمد النطاق الجغرافي والحدود المالية والشروط المطبّقة على الخطة المختارة وشركة التأمين.","question":"س7 – هل يشمل التأمين الصحي علاجاً طبياً طارئاً دولياً؟"},{"answer":"تشمل المعلومات عادةً عدد الأشخاص المطلوب تأمينهم وأعمارهم ونوع التغطية المطلوبة. وقد تُطلب معلومات طبية إضافية عند الحاجة للاكتتاب.","question":"س8 – ما المعلومات المطلوبة للحصول على عرض تأمين صحي؟"},{"answer":"نعم. يمكن دراسة خيارات مختلفة عند التجديد، لكن تغيير الخطة أو شركة التأمين قد يؤثر في الاكتتاب الطبي وفترات الانتظار واستمرارية التغطية أو التعامل مع الحالات القائمة. نقارن البدائل ونوضح الفروق قبل التغيير.","question":"س9 – هل يمكن تغيير خطة التأمين الصحي أو الشركة عند التجديد؟"}],"heading":"الأسئلة الشائعة حول التأمين الصحي","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"3a1c3d73-b12a-55cd-9bb4-b759583fa624","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف حلول تأمين أخرى نرتّبها للأفراد والعائلات والشركات.","heading":"حلول تأمين أخرى"},"visible":true,"settings":{"sectionType":"related-links"}},{"id":"805a541c-f9e3-5d33-a5f1-0f7586c40b18","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"a4b92315-0b3b-5b63-b300-24f2a10a00b7","type":"container","visible":true,"children":[{"id":"d76f3029-6790-5d75-b772-f815d583ee28","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"اعثر على خطة التأمين الصحي المناسبة لاحتياجاتك.","level":2},"visible":true},{"id":"08145940-e32e-5727-90d4-4c89e9bb67fb","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"احصل على عرض سعر وفق التغطية وشبكة المستشفيات والميزانية التي تبحث عنها."},"visible":true},{"id":"95c73048-3b63-5313-b5a7-0bd51ce16e4b","type":"button","content":{"href":"/ar/quote","label":"احصل على عرض سعر فوري","variant":"inverse"},"visible":true},{"id":"65917671-b2b9-52a3-96d1-b723a7644638","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"solid","footerVisible":true,"catalogPosition":0},"template":"solution-detail","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('9766690b-674b-45c0-8d0b-365e1ab8a151', 'تأمين السيارات | تريبل إتش وسيط التأمين', 'ar/solutions/motor', '2026-10-12 11:00:07+00', '{"Title":"تأمين السيارات في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين السيارات الخاصة | تريبل إتش وسيط التأمين","ImageUrl":"https://triplehbroker.com/uploads/20260816191450-59bd0a59f5a94794bfe58cd9137d769c.webp","Description":"استكشف تأمين السيارات الإلزامي والغير والخسارة الكلية وجميع الأخطار، وقارن الخيارات المتاحة واحصل على عرض فوري."},"Description":"قارن تأمين السيارات في لبنان، بما فيه الإلزامي والغير والخسارة الكلية وجميع الأخطار. احصل على عرض فوري مع تريبل إتش.","CanonicalUrl":"https://triplehbroker.com/ar/solutions/motor"}', '2026-08-19 12:29:08.134232+00', false, false, 'ar', '07cb890c-1b1b-49a5-91d9-941d9d3cb90c', 'solution-detail', '{"type":"page","children":[{"id":"4e1f4e68-96bd-53d7-8f1d-19054f7480f0","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يمكن لتأمين السيارات حماية نفسك ومركبتك ومسؤوليتك على الطريق. نقارن شركات التأمين المناسبة في السوق اللبنانية ونوضح الفروق بين الخطط المتاحة ونرتّب التغطية المناسبة لمركبتك واحتياجاتك.","eyebrow":"التأمين الشخصي والعائلي","heading":"تأمين السيارات الفردي","audience":"مالكو المركبات الخاصة الباحثون عن حماية إلزامية أو ضد الغير أو للخسارة الكلية أو لجميع الأخطار أو عبر الحدود.","buttonHref":"/ar/quote","buttonLabel":"احصل على عرض سعر فوري","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"settings":{"sectionType":"solution-introduction"}},{"id":"87e3b843-cce6-557f-9c11-22524ee7ab05","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"قارن مستويات الحماية المتاحة واحصل مباشرةً على عرض فوري للخيار المناسب لك.","items":[{"href":"/ar/quote","title":"التأمين الإلزامي للأضرار الجسدية","summary":"تأمين سيارات إلزامي في لبنان يغطي المسؤولية القانونية عن الإصابة الجسدية أو الوفاة التي تلحق بالغير في حادث سير، بتغطية تصل إلى 500,000 دولار أمريكي.","imageAlt":"","imageUrl":"/uploads/20260926203255-d27dabab93b946efbe1f5de20f8e8e2d.webp","linkLabel":"احصل على عرض سعر فوري"},{"href":"/ar/quote","title":"تأمين الأضرار المادية للغير","summary":"أصبح مطلوباً في لبنان، ويغطي الضرر الذي تسببه لمركبة أو ممتلكات شخص آخر، بحدود من 500,000 دولار أمريكي إلى 1.5 مليون دولار أمريكي، مع القطر بعد الحوادث. وتشمل خطط مختارة أيضاً القطر للأعطال الميكانيكية أو الكهربائية.","imageAlt":"","imageUrl":"/uploads/20260926204931-6263e81bdf014f5cb3645641c90f603b.webp","linkLabel":"احصل على عرض سعر فوري"},{"href":"/ar/quote","title":"تأمين الخسارة الكلية للمركبة","summary":"يحمي مركبتك إذا اعتُبرت خسارة كلية بعد حادث أو سُرقت أو تضررت بالحريق، مع مسؤولية تجاه الغير ومنافع للركاب وخدمة قطر متاحة بحسب الخطة المختارة.","imageAlt":"","imageUrl":"/uploads/20260926205745-60f0e9ef52af4fb7a61f2edfb9265469.webp","linkLabel":"احصل على عرض سعر فوري"},{"href":"/ar/quote","title":"تأمين جميع أخطار السيارات","summary":"يوفر حماية واسعة لمركبتك من أضرار الحوادث والحريق والسرقة، مع المسؤولية تجاه الغير وحماية الركاب والأحداث الطبيعية وأضرار الطقس والمساعدة على الطريق ومنافع السيارة البديلة بحسب الخطة المختارة.","imageAlt":"","imageUrl":"/uploads/20260926211159-80c63b244e714c8f92eaa74cb8bc89e8.webp","linkLabel":"احصل على عرض سعر فوري"},{"href":"/ar/contact","title":"تأمين البطاقة البرتقالية","summary":"يوفر حماية المسؤولية الإلزامية تجاه الغير عند القيادة بين الدول العربية المشاركة، ويغطي الإصابات الجسدية أو الأضرار المادية للآخرين وفق متطلبات التأمين في البلد المزور.","imageAlt":"","imageUrl":"/uploads/20260926212256-214febf471f1410586645e9b24a5916b.webp","linkLabel":"احصل على عرض سعر"}],"heading":"خيارات تأمين السيارات"},"visible":true,"children":[],"settings":{"sectionType":"solutions-catalog"}},{"id":"0dae6a59-9475-5470-9237-d9fb88d7aec4","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن تفاصيل كل عرض، ومنها التغطية والحدود وشروط الإصلاح ومنافع المساعدة، ونساعدك على اختيار الأنسب لمركبتك واحتياجاتك.","intro":"يمكن لتأمين السيارات تغطية المسؤولية تجاه الآخرين وضرر مركبتك أو فقدها وحماية الركاب وخدمات المساعدة، بحسب المنتج والخطة المختارين.","items":[{"text":"الأضرار الجسدية للغير"},{"text":"الأضرار المادية للغير"},{"text":"أضرار الحوادث لمركبتك"},{"text":"الحريق والسرقة"},{"text":"الخسارة الكلية لمركبتك"},{"text":"منافع الوفاة أو العجز للسائق والركاب"},{"text":"النفقات الطبية بعد حادث مغطى"},{"text":"أضرار الطقس والأحداث الطبيعية"},{"text":"الإضرابات والشغب والاضطرابات المدنية والإرهاب"},{"text":"المساعدة على الطريق والقطر"},{"text":"سيارة بديلة أو مستأجرة بعد حادث مغطى"},{"text":"سرقة أجزاء المركبة حيث تشملها التغطية"}],"heading":"ما الذي يغطيه؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"d076e258-23be-5d04-a12a-abc83f0fbeef","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"السعر واسم الخطة جزء فقط من المقارنة. فقد تؤثر شركة التأمين وشروط الوثيقة والحدود وشروط الإصلاح والتسوية ومقدم المساعدة على الطريق وخدمة المطالبات عندما تحتاج إلى استخدام التغطية.","items":[{"text":"شركة التأمين وخدمة المطالبات"},{"text":"شروط الوثيقة وأحكامها واستثناءاتها"},{"text":"حدود المسؤولية تجاه الغير"},{"text":"القيمة المؤمّنة للمركبة وتسوية الخسارة الكلية"},{"text":"متى تُعتبر المركبة خسارة كلية"},{"text":"مبلغ التحمل — المبلغ الذي تدفعه عند حدوث مطالبة"},{"text":"الوكيل الرسمي والمرآب المعتمد وجودة الإصلاح"},{"text":"استهلاك قطع الغيار — حصتك من تكاليف القطع البديلة"},{"text":"تسوية السرقة وسرقة الأجزاء"},{"text":"تغطية الخدوش والانبعاجات البسيطة"},{"text":"حدود الطقس والأحداث الطبيعية"},{"text":"حدود الإضرابات والشغب والاضطرابات المدنية والإرهاب"},{"text":"حدود المنافع الطبية للسائق والركاب بعد حادث"},{"text":"حدود منافع الوفاة والعجز الدائم للسائق والركاب"},{"text":"مقدم المساعدة على الطريق وشروط القطر"},{"text":"منافع السيارة البديلة أو المستأجرة"}],"heading":"ما الذي تقارنه؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"de0035fc-a743-5599-888b-05595747e3fc","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"ندير الإجراءات من فهم التغطية المطلوبة إلى التواصل مع شركات التأمين المناسبة في السوق اللبنانية ومقارنة عروضها وترتيب الوثيقة ودعمك طوال مدتها.","items":[{"body":"نفهم الحماية المطلوبة وفق مركبتك واستخدامها ونوع تأمين السيارات الذي تبحث عنه.","title":"فهم احتياجاتك"},{"body":"نتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن عروضها وفق التغطية والشروط والخدمة التي تهمك.","title":"مقارنة الخيارات المناسبة"},{"body":"نوضح الفروق بوضوح ونساعدك على اختيار الأنسب لمركبتك واحتياجاتك ونرتّب الوثيقة لك.","title":"الشرح والترتيب"},{"body":"نتولى التواصل مع شركة التأمين ونواصل المتابعة خلال تعديلات الوثيقة وتجديداتها طوال مدتها.","title":"المتابعة المستمرة"}],"layout":"grid","heading":"كيف نرتّب تأمين سيارتك؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"e1f88507-78e2-5c94-8daa-9e136e0b9421","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"اتصل بخطنا الساخن المتاح على مدار الساعة طوال الأسبوع وسنتولى الباقي.","items":[{"text":"عند الحاجة، نرتّب حضور خبير مطالبات سيارات إلى موقع الحادث لإرشادك بشأن الخطوات التالية وتنسيق المستندات اللازمة. ثم نتواصل مع شركة التأمين نيابةً عنك ونتابع المطالبة وننسّق المسؤوليات تجاه الغير وفق الوثيقة."},{"text":"لمطالبات جميع الأخطار، ننسّق إصلاح المركبة مع المرآب المناسب أو الوكيل الرسمي ونتابع العمل حتى اكتماله، بما يساعد على تنفيذ الإصلاحات المتفق عليها بصورة سليمة."}],"heading":"ما الذي تفعله بعد حادث؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"bb5b38d2-9d2d-5c73-9bdd-44ce7b12dfc3","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عن أسئلة شائعة حول تأمين السيارات في لبنان، من التغطية الإلزامية وأنواع الوثائق إلى الخسارة الكلية والإصلاح والمساعدة على الطريق.","items":[{"answer":"يُلزم سائقو المركبات في لبنان بحمل تأمين إلزامي للأضرار الجسدية والمادية للغير. تحمي تغطية الأضرار الجسدية من المسؤولية القانونية عن إصابة الآخرين أو وفاتهم، بينما تحمي تغطية الأضرار المادية من الضرر الذي يصيب مركبة شخص آخر أو ممتلكاته.","question":"س1 – ما تأمين السيارات المطلوب في لبنان؟"},{"answer":"يحمي تأمين الغير أساساً من الضرر الذي يلحق بالآخرين. وتضيف تغطية الخسارة الكلية حماية للخسائر الكبرى مثل اعتبار المركبة خسارة كلية أو سرقتها أو تضررها بالحريق. وتوفر جميع الأخطار حماية أوسع، منها الضرر العرضي لمركبتك، وفق شروط الوثيقة المختارة.","question":"س2 – ما الفرق بين تأمين الغير والخسارة الكلية وجميع الأخطار؟"},{"answer":"قد يختلف القسط بحسب ماركة المركبة وطرازها وقيمتها السوقية ونوع التغطية وحدود الوثيقة وخيارات الإصلاح ومعايير التسعير لدى شركة التأمين. لذلك قد يختلف عرضان متشابهان في السعر والشروط.","question":"س3 – ما الذي يؤثر في تكلفة تأمين السيارات؟"},{"answer":"في الخطط الحالية التي نقارنها، تُعتبر المركبة عادةً خسارة كلية عندما تبلغ تكاليف الإصلاح 60 إلى 65% من قيمتها السوقية وقت الحادث أو تتجاوزها، وفق شروط الوثيقة المختارة وأساس التسوية.","question":"س4 – متى تُعتبر المركبة خسارة كلية؟"},{"answer":"لا. توفر جميع الأخطار حماية واسعة، لكن تبقى الحدود والاستثناءات والشروط مطبّقة. قد تختلف الأضرار البسيطة وسرقة الأجزاء والأحداث الطبيعية وإصلاحات الوكيل وغيرها من المنافع بين الخطط.","question":"س5 – هل يغطي تأمين جميع الأخطار كل أنواع الضرر؟"},{"answer":"يعتمد ذلك على الخطة المختارة وعمر المركبة. تشمل بعض الوثائق إصلاحات لدى الوكيل الرسمي للمركبات المؤهلة، بينما تستخدم أخرى مرائب معتمدة. ينبغي مقارنة ترتيبات الإصلاح وجودته قبل الاختيار.","question":"س6 – هل يمكن إصلاح مركبتي لدى الوكيل الرسمي؟"},{"answer":"قد يكمن الفرق في شركة التأمين ونص الوثيقة والحدود وشبكة الإصلاح وخدمة المطالبات ومقدم المساعدة على الطريق وشروط التسوية والاستثناءات. نقارن هذه التفاصيل لتفهم كيفية عمل كل خيار فعلياً.","question":"س7 – لماذا قد يختلف عرضان متشابهان لتأمين جميع الأخطار؟"},{"answer":"يوفر تأمين البطاقة البرتقالية حماية المسؤولية الإلزامية تجاه الغير عند القيادة في الدول العربية المشاركة، وفق متطلبات البلد المزور. ويمكن أن يغطي الأضرار الجسدية والمادية التي تلحق بالآخرين أثناء القيادة خارج لبنان.","question":"س8 – ما هو تأمين البطاقة البرتقالية؟"},{"answer":"يعتمد ذلك على الخطة. يُدرج القطر بعد الحوادث عادةً، بينما قد يختلف القطر بعد عطل ميكانيكي أو كهربائي بحسب الوثيقة، بما فيه عدد الخدمات والمسافة ومقدم المساعدة.","question":"س9 – هل يشمل تأمين السيارات القطر بعد عطل؟"},{"answer":"نعم. يمكنك الحصول على عرض فوري لخيارات تأمين السيارات المتاحة بإدخال تفاصيل المركبة والتغطية المطلوبة، ثم مقارنة الخيارات المتاحة لك.","question":"س10 – هل يمكن الحصول على عرض فوري لتأمين السيارات؟"}],"heading":"الأسئلة الشائعة حول تأمين السيارات","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"aefdddee-cda0-5d5e-92c1-daadaf9c653a","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف حلول تأمين أخرى نرتّبها للأفراد والعائلات والشركات.","heading":"حلول تأمين أخرى"},"visible":true,"settings":{"sectionType":"related-links"}},{"id":"a9f10a49-2710-53c0-a88e-84a8bc8b77ce","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"98840dbc-3617-5559-9e53-568f7a1211b6","type":"container","visible":true,"children":[{"id":"09a2b1f1-02a7-57a1-bba4-1c6c2ce6af5c","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"اعثر على خطة تأمين السيارات المناسبة لمركبتك واحتياجاتك.","level":2},"visible":true},{"id":"3a9511a6-6fb7-5adf-816c-5db142b3dcc5","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"احصل على عرض فوري وقارن خيارات تأمين السيارات المتاحة لمركبتك."},"visible":true},{"id":"bae5b0ae-c7d2-57b4-8f37-e5fefda5f492","type":"button","content":{"href":"/ar/quote","label":"احصل على عرض سعر فوري","variant":"inverse"},"visible":true},{"id":"40561a83-783c-59cf-bc02-6c905fb6add3","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"solid","footerVisible":true,"catalogPosition":2},"template":"solution-detail","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('d4624157-9442-4da7-80e5-70c7206e878a', 'تأمين المنزل | تريبل إتش وسيط التأمين', 'ar/solutions/home', '2026-10-12 11:00:07+00', '{"Title":"تأمين المنزل في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين المنزل | تريبل إتش وسيط التأمين","ImageUrl":"https://triplehbroker.com/uploads/20260816200834-1cb8ffe33d9c4b3986804a0ccbc706a6.webp","Description":"احمِ منزلك ومقتنياتك ومسؤولياتك بتأمين منزل ترتّبه شركة تريبل إتش وسيط التأمين وفق احتياجاتك."},"Description":"قارن تأمين المنزل في لبنان للعقار والمقتنيات والسرقة وأضرار المياه والأحداث الطبيعية والمسؤولية. ترتّب تريبل إتش التغطية المناسبة.","CanonicalUrl":"https://triplehbroker.com/ar/solutions/home"}', '2026-08-19 12:29:08.135265+00', false, false, 'ar', '1c4feafa-4fe0-4737-9d93-6b9e71fd07cb', 'solution-detail', '{"type":"page","children":[{"id":"fbfa04cb-f10d-5c13-b710-c898fceef938","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يساعد تأمين المنزل على حماية منزلك ومقتنياتك من مخاطر مثل الحريق وأضرار المياه والسرقة وغيرها من الأحداث المغطاة. نتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن التغطية والشروط المتاحة ونرتّب الوثيقة وفق عقارك واحتياجاتك.","eyebrow":"التأمين الشخصي والعائلي","heading":"تأمين المنزل","audience":"أصحاب المنازل والمؤجرون والمستأجرون الذين يريدون حماية المبنى أو مقتنياتهم أو كليهما، بتغطية قد تشمل أيضاً المسؤولية تجاه الآخرين والسكن المؤقت وفقدان دخل الإيجار.","buttonHref":"/ar/contact","buttonLabel":"اطلب عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"settings":{"sectionType":"solution-introduction"}},{"id":"435cd1b9-69c1-5fee-9b8f-dc4f2c039468","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"4fa3ee99-7778-5fa7-b709-55e73f9b5c33","type":"container","visible":true,"children":[{"id":"25db858f-0f7a-592e-b003-eba890fa65d5","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"ما الذي يمكن أن يحميه تأمين المنزل؟","level":2},"visible":true},{"id":"e23a3521-5cba-529d-a8be-4834d8a9476b","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن أن يحمي تأمين المنزل المبنى ومقتنياتك وتكاليف أو مسؤوليات معينة ناتجة عن ضرر أو خسارة."},"visible":true},{"id":"76c18aba-f76d-53ff-965c-c75bb2b7f7ab","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"5dbb1317-1b60-5df4-ab2c-3812863b8672","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"1139cafa-fde4-5c45-a118-faa9fffb1015","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"المبنى والتجهيزات الثابتة","level":3},"visible":true},{"id":"927a96e6-b246-524e-bd08-2ddcf5a65370","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"حماية للهيكل المادي للمنزل وأجزائه الدائمة، مثل الأبواب والأقفال والنوافذ والتجهيزات المدمجة وغيرها من العناصر الثابتة للعقار."},"visible":true}]},{"id":"cc39c367-ca80-52eb-942d-49c58f3272c9","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"5367849c-4a8e-5566-a217-2dd25eb4253d","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"المحتويات والمقتنيات","level":3},"visible":true},{"id":"cca9f7e7-ca60-5eb7-be88-3b89d098453e","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"حماية لمقتنياتك مثل الأثاث والأجهزة والإلكترونيات وغيرها من الممتلكات الشخصية، بحسب الوثيقة المختارة."},"visible":true}]},{"id":"b218c0c0-a5bc-54c3-92af-5a04fcba77c8","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"b6b40f5e-a00d-507a-bfdd-953c3c209031","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"المسؤولية تجاه الآخرين والتكاليف الإضافية","level":3},"visible":true},{"id":"88989634-aff4-583a-8bc9-908546876af8","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"حماية قد تشمل الأضرار التي تلحق بالجيران أو الآخرين والمسؤولية القانونية والسكن المؤقت وفقدان الإيجار بعد حدث مغطى."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"88671805-f0ac-5afb-ba76-c21872530e28","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن خيارات تأمين المنزل المناسبة ونوضح الفروق المهمة ونرتّب التغطية وفق عقارك ومقتنياتك واحتياجاتك.","intro":"يمكن لتأمين المنزل حماية الأضرار والخسائر والمسؤولية الناتجة عن مجموعة أحداث، بمنافع وحدود وشروط تعتمد على الوثيقة المختارة وشركة التأمين.","items":[{"text":"الحريق والانفجار والصواعق"},{"text":"أضرار المياه من انفجار الأنابيب أو تسرب الخزانات"},{"text":"أضرار الأمطار وارتداد مياه الصرف أو المجاري"},{"text":"السرقة إثر دخول بالقوة"},{"text":"أضرار الأبواب والأقفال إثر اقتحام"},{"text":"العواصف والفيضانات والبَرَد وغيرها من الأحداث الطبيعية"},{"text":"الزلازل والتسونامي"},{"text":"أضرار الدخان"},{"text":"تقلب التيار والأضرار الكهربائية المرتبطة به"},{"text":"كسر الزجاج"},{"text":"الإضرابات والشغب والاضطرابات المدنية والأضرار المتعمدة"},{"text":"الأضرار الناجمة عن اصطدام المركبات أو الطائرات"},{"text":"المسؤولية عن الأضرار التي تلحق بالجيران أو الآخرين"},{"text":"السكن المؤقت أو فقدان الإيجار بعد حدث مغطى"},{"text":"إزالة الأنقاض وتكاليف مهنية معينة بعد ضرر كبير"}],"heading":"ما الذي يغطيه؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"e1eda0b0-406a-54d6-936e-e9cade6ddbfe","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"قد تبدو وثيقتا تأمين منزل متشابهتين لكن تختلفان كثيراً في ما تحميانه والمبلغ المدفوع والشروط المطبّقة. هذه النقاط الرئيسية للمقارنة قبل اختيار الوثيقة.","items":[{"text":"شركة التأمين وجودة الوثيقة وخدمة المطالبات"},{"text":"القيمة المؤمّنة للمبنى — المبلغ المستخدم لتأمين الهيكل"},{"text":"القيمة المؤمّنة للمحتويات وحدودها"},{"text":"الحدود المطبّقة على أنواع الضرر أو الخسارة المختلفة"},{"text":"مبالغ التحمل — ما تدفعه عند حدوث مطالبة"},{"text":"شروط أضرار المياه وتسرب الأنابيب"},{"text":"شروط السرقة والدخول بالقوة"},{"text":"تغطية الزلازل والفيضانات وغيرها من الأحداث الطبيعية"},{"text":"المسؤولية عن الأضرار التي تلحق بالجيران أو الآخرين"},{"text":"منافع السكن المؤقت وفقدان الإيجار"},{"text":"تغطية تقلب التيار والأضرار الكهربائية"},{"text":"حدود النقد والمقتنيات الثمينة وغيرها من الممتلكات الخاصة"},{"text":"الاستثناءات وشروط الوثيقة"}],"heading":"ما الذي تقارنه؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"40883480-b325-5855-bd04-9d233469c21b","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"ندير الإجراءات من فهم ما تحتاج إلى حمايته إلى مقارنة شركات التأمين المناسبة في السوق اللبنانية وترتيب الوثيقة ودعمك بعدها.","items":[{"body":"نحدد ما تريد تأمينه ونوع الحماية المطلوبة ومستوى التغطية المناسب لك.","title":"فهم احتياجاتك"},{"body":"نتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن عروضها وفق التغطية والحدود والشروط وشركة التأمين وخدمة المطالبات.","title":"مقارنة الخيارات المناسبة"},{"body":"نوضح الفروق بوضوح ونساعدك على اختيار الأنسب لمنزلك واحتياجاتك ونرتّب الوثيقة لك.","title":"الشرح والترتيب"},{"body":"نتولى التواصل مع شركة التأمين ونواصل المتابعة خلال تعديلات الوثيقة وتجديداتها طوال مدتها.","title":"المتابعة المستمرة"}],"layout":"grid","heading":"كيف نرتّب تأمين منزلك؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"df504640-4ad7-5eee-8eda-13236691dc67","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"اتصل بخطنا الساخن المتاح على مدار الساعة طوال الأسبوع وسندير مطالبتك في كل مرحلة حتى التسوية.","items":[{"text":"عند الحاجة، نرسل خبير مطالبات إلى العقار بأسرع وقت لمعاينة الضرر وتسجيل ما حدث. ندير المطالبة منذ البداية وننسّق عمل الخبير ونتحقق من توثيق الأضرار والمعلومات الداعمة بصورة سليمة لتسير المطالبة بشكل صحيح."},{"text":"ثم نتعامل مع شركة التأمين نيابةً عنك ونتابع المطالبة عن كثب ونعمل على تحصيل التسوية والمنافع المغطاة المستحقة لك بموجب الوثيقة. وإذا تسبب الحادث أيضاً بأضرار للجيران أو أطراف ثالثة، ننسّق المسؤولية المغطاة كذلك. نتولى التواصل والمستندات والمتابعة حتى انتهاء المطالبة مع إطلاعك على المستجدات طوال الوقت."}],"heading":"ما الذي تفعله عند تضرر منزلك؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"126027fd-4cd5-57f4-b912-db9cb3825e5a","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عن أسئلة شائعة حول تأمين المنزل، بما فيها القيم المؤمّنة وتغطية المبنى والمحتويات والسرقة والمقتنيات الثمينة والمؤجرون والمستأجرون.","items":[{"answer":"قد يختلف القسط بحسب العقار وقيمة المبنى والمحتويات المؤمّنة والتغطية المختارة وحدود الوثيقة ومبالغ التحمل وتسعير شركة التأمين. نقارن الحماية والشروط إلى جانب القسط.","question":"س1 – كيف تُحسب تكلفة تأمين المنزل؟"},{"answer":"يجب تأمين المبنى والمحتويات بقيم مناسبة لتعكس الوثيقة ما تحتاج فعلياً إلى حمايته. نساعدك على تحديد مبالغ مناسبة للعقار والمقتنيات قبل مقارنة الخيارات المتاحة.","question":"س2 – بأي مبلغ ينبغي تأمين منزلي؟"},{"answer":"يمكن ترتيب تأمين للمبنى أو المحتويات أو كليهما بحسب حاجتك. غالباً يحمي أصحاب المنازل الاثنين، بينما يؤمّن المستأجرون مقتنياتهم ويركّز المؤجرون على العقار ومخاطر الإيجار. نرتّب التغطية وفق وضعك.","question":"س3 – هل أحتاج إلى تأمين المبنى والمحتويات معاً؟"},{"answer":"نعم. قد لا تحمي وثيقة المبنى كل احتياجاتك الفردية، مثل مقتنياتك أو مسؤوليتك الشخصية أو مخاطر مرتبطة بمنزلك تحديداً. نتحقق مما هو مؤمّن بالفعل ونرتّب الحماية الإضافية اللازمة دون ازدواجية غير ضرورية.","question":"س4 – هل يمكن ترتيب تأمين منزل إذا كان المبنى مؤمّناً بالفعل؟"},{"answer":"نعم. يمكن أن يشمل تأمين المنزل حماية المقتنيات المسروقة والأضرار أثناء الاقتحام. نقارن شروط السرقة وحدودها بين شركات التأمين ويمكننا ترتيب حماية إضافية للمقتنيات الثمينة عند الحاجة.","question":"س5 – هل يغطي تأمين المنزل السرقة؟"},{"answer":"يمكن أن يشمل تأمين المنزل حماية للأضرار التي تلحق بجار بعد تسرب مياه مؤمّن أو حدث مغطى آخر. نقارن حدود المسؤولية المتاحة ونرتّب الحماية وفق مستوى التغطية المطلوب.","question":"س6 – ماذا يحدث إذا أضرت مياه من منزلي بممتلكات جار؟"},{"answer":"يمكن أن يشمل تأمين المنزل تكاليف السكن المؤقت أثناء تعذر الإقامة في المنزل بعد حدث مغطى. وللعقار المؤجر، يمكن أيضاً إدراج فقدان الإيجار. نقارن المنافع والحدود والشروط المتاحة عند ترتيب الوثيقة.","question":"س7 – ماذا لو تعذر البقاء في منزلي بعد ضرر جسيم مغطى؟"},{"answer":"نعم. يمكن حماية المقتنيات الثمينة، لكن قد تخضع لحدود محددة أو تحتاج إلى التصريح بها أو تأمينها منفصلةً. نحدد ما تريد حمايته ونسعى لترتيب حدود مناسبة أو تغطية إضافية حيث تتاح لتناسب الحماية احتياجاتك بصورة أفضل.","question":"س8 – هل يمكن تأمين المجوهرات والنقد والمقتنيات الثمينة الأخرى؟"},{"answer":"نحتاج عادةً إلى تفاصيل أساسية عن العقار وما إذا كنت تملكه أو تستأجره وما تريد تأمينه والقيم التقريبية للمبنى والمحتويات. وقد تُطلب معلومات إضافية بحسب العقار والتغطية المطلوبة.","question":"س9 – ما المعلومات المطلوبة لعرض تأمين المنزل؟"}],"heading":"الأسئلة الشائعة حول تأمين المنزل","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"914e7513-c254-5094-8616-0bd8e719387f","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف حلول تأمين أخرى نرتّبها للأفراد والعائلات والشركات.","heading":"حلول تأمين أخرى"},"visible":true,"settings":{"sectionType":"related-links"}},{"id":"25f143f5-9c58-500d-ac6d-8ee30f44974f","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"9094afaa-740b-5d43-b1fb-7ca9d62d479b","type":"container","visible":true,"children":[{"id":"c4977fa1-461b-5ee8-9782-d2fd8f77fd69","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"احمِ منزلك بالتغطية المناسبة.","level":2},"visible":true},{"id":"0b86545c-8ee8-5a90-9227-c6de1dd488d0","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أخبرنا بما تريد حمايته، وسنقارن خيارات تأمين المنزل المناسبة ونرتّب التغطية وفق احتياجاتك."},"visible":true},{"id":"fbb1cfd6-aee1-5ff8-bfcd-4d0c477fe67c","type":"button","content":{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},"visible":true},{"id":"43a65b11-3868-5a00-8dfc-8a28ffe37495","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"solid","footerVisible":true,"catalogPosition":3},"template":"solution-detail","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('96205932-ae0f-400b-9aee-e87d146e2383', 'تأمين السفر | تريبل إتش وسيط التأمين', 'ar/solutions/travel', '2026-10-12 11:00:07+00', '{"Title":"تأمين السفر في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين السفر | تريبل إتش وسيط التأمين","ImageUrl":"https://triplehbroker.com/uploads/20260816204131-9321bc958398416c9ba24a3444c7178a.webp","Description":"استكشف تأمين السفر لرحلة واحدة والسفر المتكرر والإقامات الطويلة، بحماية وفق وجهتك واحتياجاتك، بما فيها متطلبات التأشيرة."},"Description":"قارن تأمين السفر في لبنان للطوارئ الطبية وإلغاء الرحلات والأمتعة والإقامات الطويلة ومتطلبات التأشيرة. ترتّب تريبل إتش التغطية المناسبة.","CanonicalUrl":"https://triplehbroker.com/ar/solutions/travel"}', '2026-08-19 12:29:08.134716+00', false, false, 'ar', '933c3578-eb28-43fd-b777-8958167721e2', 'solution-detail', '{"type":"page","children":[{"id":"e7f815f8-e405-5aff-9e81-0a7ce97801bd","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يساعد تأمين السفر على حمايتك من الطوارئ الطبية والأحداث غير المتوقعة التي قد تؤثر في رحلتك قبل المغادرة أو أثناء السفر. نتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن التغطية والشروط المتاحة ونرتّب الوثيقة وفق وجهتك ورحلتك واحتياجاتك.","eyebrow":"التأمين الشخصي والعائلي","heading":"تأمين السفر","audience":"الأفراد والعائلات الذين يسافرون إلى الخارج للعطلات أو الأعمال أو رحلات شخصية أخرى، بمن فيهم من يحتاجون إلى تأمين لطلب تأشيرة.","buttonHref":"/ar/contact","buttonLabel":"احصل على عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"settings":{"sectionType":"solution-introduction"}},{"id":"33fcf1fc-3280-55e7-89d0-e06e517ea69a","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"8f352499-c208-56a8-b576-c38f1de5523a","type":"container","visible":true,"children":[{"id":"db49e6c4-0590-5c78-8ff2-3689be825b09","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"خيارات تأمين السفر","level":2},"visible":true},{"id":"ee17078a-6ab7-5e45-bee1-71ddf804bb24","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن ترتيب تأمين السفر لرحلة واحدة أو عدة رحلات خلال السنة أو إقامة طويلة، بحسب كيفية سفرك ووجهتك."},"visible":true},{"id":"025bba81-31c7-54d8-8aec-9757c41cdb35","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"6787764c-75d2-50d8-8e5e-94604d9b21f4","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"9a5ca4cf-7a16-5cd2-85bd-36e965fa8739","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"تأمين رحلة واحدة","level":3},"visible":true},{"id":"9ec38557-bc50-5bb4-afe8-66d1a684a223","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تغطية لرحلة واحدة تُرتَّب وفق وجهتك وتواريخ سفرك ومستوى الحماية المطلوب."},"visible":true}]},{"id":"3f54f24d-6c28-5071-87ec-2e4881aa8377","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"55a69075-a3e3-5cdb-ae58-cd2b368d683b","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"تأمين سنوي لرحلات متعددة","level":3},"visible":true},{"id":"8c6c42b0-b78d-5607-b32f-6e24adb8ab6f","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تغطية لعدة رحلات خلال سنة الوثيقة تمنح المسافرين المتكررين حماية مستمرة دون ترتيب وثيقة منفصلة لكل رحلة."},"visible":true}]},{"id":"5ab2dcef-3998-5c60-8276-bbcb441b7caa","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"f75b3fc7-9df5-566f-8598-433c5ebc9c07","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"تأمين السفر للإقامة الطويلة","level":3},"visible":true},{"id":"ea4494c6-a87f-5abf-a1f9-5591a19b6ad7","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تغطية لرحلة واحدة طويلة تُرتَّب وفق الوجهة ومدة الإقامة ومستوى الحماية المطلوب."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"c1ca2267-6150-57b9-b0c1-5099f07598db","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن خطط تأمين السفر المناسبة في السوق اللبنانية ونوضح الفروق المهمة ونرتّب التغطية وفق وجهتك ومدة إقامتك واحتياجات سفرك.","intro":"يمكن لتأمين السفر حمايتك من الطوارئ الطبية واضطراب الرحلة وغيرها من الأحداث غير المتوقعة قبل المغادرة أو أثناء السفر، بمنافع وحدود تعتمد على الوثيقة المختارة.","items":[{"text":"العلاج الطبي الطارئ والاستشفاء"},{"text":"الإجلاء الطبي والعودة إلى الوطن عند الضرورة الطبية"},{"text":"إعادة الجثمان إلى الوطن في حالة الوفاة"},{"text":"علاج الأسنان الطارئ"},{"text":"إلغاء الرحلة أو انقطاعها لأسباب مغطاة"},{"text":"تأخر الرحلات الجوية أو السفر حيث تشمله التغطية"},{"text":"فقدان الأمتعة أو سرقتها أو تأخرها"},{"text":"فقدان جواز السفر أو مستندات السفر الأخرى"},{"text":"الإنقاذ البحري والجبلي حيث تشمله التغطية"},{"text":"المسؤولية الشخصية أثناء السفر"},{"text":"منافع الوفاة العرضية أو العجز الدائم"},{"text":"دعم سفر أفراد العائلة بعد طارئ طبي خطير"}],"heading":"ما الذي يغطيه؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"6ccd59c5-7cc8-584d-b78d-496a3b6cc9e6","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يعتمد تأمين السفر المناسب على أكثر من القسط. فشركة التأمين والحماية الطبية والوجهة ومدة الرحلة وخدمة المساعدة وشروط الوثيقة قد تؤثر في مستوى الحماية والدعم اللذين تتلقاهما.","items":[{"text":"شركة التأمين وخدمة المطالبات"},{"text":"حد التغطية الطبية الطارئة"},{"text":"البلدان والمناطق المشمولة"},{"text":"مدة كل رحلة"},{"text":"تغطية رحلة واحدة أو رحلات سنوية متعددة أو إقامة طويلة"},{"text":"الإجلاء الطبي والإعادة إلى الوطن"},{"text":"مبالغ التحمل — ما تدفعه عند حدوث مطالبة طبية"},{"text":"أهلية العمر وشروطه"},{"text":"منافع إلغاء الرحلة وانقطاعها"},{"text":"حدود فقدان الأمتعة وتأخرها"},{"text":"منافع تأخر الرحلات الجوية والسفر"},{"text":"تغطية الرياضات والأنشطة عند الحاجة"},{"text":"حدود المسؤولية الشخصية"},{"text":"خدمة مساعدة طبية وسفر على مدار الساعة طوال الأسبوع"},{"text":"الاستثناءات وشروط الوثيقة"}],"heading":"ما الذي تقارنه؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"e3a97693-250e-5251-8613-70759518a679","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"ندير الإجراءات من تحديد التغطية المطلوبة إلى مقارنة شركات التأمين المناسبة في لبنان وترتيب الوثيقة ودعمك طوال مدتها.","items":[{"body":"نحدد مستوى الحماية المطلوب لرحلتك، بما فيه النطاق الجغرافي والتغطية الطبية ومدة الرحلة وأي متطلبات للتأشيرة أو الأنشطة.","title":"فهم احتياجاتك"},{"body":"نتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن عروضها وفق الحماية والحدود وخدمة المساعدة والشروط المهمة لرحلتك.","title":"مقارنة الخيارات المناسبة"},{"body":"نوضح الفروق بوضوح ونساعدك على اختيار الأنسب لاحتياجاتك ونرتّب الوثيقة لك.","title":"الشرح والترتيب"},{"body":"نتولى التواصل مع شركة التأمين ونبقى متاحين للتعديلات والتوسعات والدعم طوال مدة الوثيقة.","title":"المتابعة المستمرة"}],"layout":"grid","heading":"كيف نرتّب تأمين سفرك؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"47f44f86-e165-568d-9dbb-f5bbf824a5c7","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"اتصل بخطنا الساخن المتاح على مدار الساعة طوال الأسبوع لننسّق المساعدة المطلوبة وندير مطالبتك في كل مرحلة حتى التسوية.","items":[{"text":"إذا احتجت إلى رعاية طبية عاجلة أو مساعدة أخرى أثناء السفر، ننسّق مباشرةً مع شركة التأمين وفريق المساعدة لترتيب الدعم المتاح بموجب الوثيقة، بما فيه دخول المستشفى والإحالات الطبية والإجلاء وغيرها من الخدمات المغطاة."},{"text":"للمطالبات، نتولى التواصل مع شركة التأمين نيابةً عنك ونُعدّ المستندات المطلوبة ونقدمها ونتابع الحالة عن كثب ونعمل على تحصيل التسوية والمنافع المغطاة المستحقة لك بموجب الوثيقة. ندير الإجراءات حتى انتهاء المطالبة ونُطلعك على المستجدات طوال الوقت."}],"heading":"ما الذي تفعله إذا احتجت إلى مساعدة أو تقديم مطالبة؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"fc4c217a-d178-5237-afa2-4b924f2f8c61","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عن أسئلة شائعة حول تأمين السفر، بما فيها تأشيرات شنغن والتغطية العائلية والسفر المتكرر والإقامات الطويلة والعمر ومتطلبات الوثيقة.","items":[{"answer":"نعم. يُطلب التأمين الطبي للسفر لطلبات تأشيرة شنغن ويجب أن يستوفي متطلبات التأشيرة المطبّقة. نرتّب وثائق مناسبة ونوفر شهادة التأمين المطلوبة لطلبك.","question":"س1 – هل أحتاج إلى تأمين سفر لتأشيرة شنغن؟"},{"answer":"نعم. يمكن ترتيب تأمين سفر للأفراد والأزواج والعائلات المسافرين معاً. نقارن الخيارات العائلية المتاحة ونرتّب التغطية وفق المسافرين والوجهة ومدة الرحلة.","question":"س2 – هل يمكن ترتيب تأمين سفر لعائلتي؟"},{"answer":"نعم. يمكن ترتيب تأمين سفر للمسافرين الأكبر سناً، مع خطط وأقساط وشروط تعتمد على العمر والوجهة ومدة الرحلة. نقارن الخيارات المناسبة ونوضح الفروق قبل ترتيب الوثيقة.","question":"س3 – هل يمكن للمسافرين الأكبر سناً الحصول على تأمين سفر؟"},{"answer":"يمكن للوثيقة السنوية متعددة الرحلات تغطية عدة رحلات خلال سنة الوثيقة، دون الحاجة إلى وثيقة جديدة قبل كل رحلة. نقارنها بتغطية الرحلة الواحدة ونرتّب الأنسب لوتيرة سفرك.","question":"س4 – ماذا لو سافرت عدة مرات خلال السنة؟"},{"answer":"نعم. يمكن ترتيب تأمين سفر لإقامات طويلة في الخارج. نقارن الخيارات المناسبة وفق مدة إقامتك ووجهتك والحماية المطلوبة.","question":"س5 – هل يمكن الحصول على تأمين سفر لإقامة طويلة في الخارج؟"},{"answer":"نعم. يمكن أن يشمل تأمين السفر حماية لرياضات وأنشطة معينة، منها التزلج ضمن خطط مناسبة. أخبرنا بأنشطتك المخطط لها لنرتّب التغطية الملائمة حيث تتاح.","question":"س6 – هل يمكن تغطية رياضات مثل التزلج؟"},{"answer":"يفضّل ترتيب الوثيقة قبل بدء الرحلة وقبل تقديم طلب تأشيرة يتطلب تأميناً. يضمن ترتيبها مبكراً أيضاً إمكانية تطبيق منافع ما قبل المغادرة المتاحة، مثل إلغاء الرحلة، وفق شروط الوثيقة المختارة.","question":"س7 – متى ينبغي ترتيب تأمين السفر؟"},{"answer":"نحتاج عادةً إلى عمر المسافر والوجهة وتواريخ السفر وعدد المسافرين ونوع الرحلة ونسخة من جواز السفر. نسأل أيضاً عن متطلبات خاصة مثل إقامة طويلة أو أنشطة تحتاج إلى حماية إضافية.","question":"س8 – ما المعلومات المطلوبة لعرض تأمين السفر؟"},{"answer":"تواصل معنا فور تغير تواريخ سفرك أو وجهتك أو مدة رحلتك. حيث تسمح الوثيقة، ننسّق التعديل أو التمديد المطلوب مع شركة التأمين لتظل التغطية ملائمة لرحلتك.","question":"س9 – ماذا لو تغيرت خطط سفري بعد إصدار الوثيقة؟"}],"heading":"الأسئلة الشائعة حول تأمين السفر","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"0d55b4fd-e9a0-51f0-885e-a559fe9b4fe5","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف حلول تأمين أخرى نرتّبها للأفراد والعائلات والشركات.","heading":"حلول تأمين أخرى"},"visible":true,"settings":{"sectionType":"related-links"}},{"id":"ee5ef40c-16f5-5c97-ad23-b2dfbc7d3b0f","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"bc6d96a5-8b26-52de-ac58-741b8f42d175","type":"container","visible":true,"children":[{"id":"3042c5eb-c421-5e43-8576-cd9eaaea3c04","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"اعثر على خطة تأمين السفر المناسبة لرحلتك.","level":2},"visible":true},{"id":"8d7cafca-7bd3-5d7e-bca4-80340c01c7f9","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أخبرنا بوجهتك وتواريخ سفرك. سنقارن الخيارات المناسبة ونرتّب التغطية المطلوبة."},"visible":true},{"id":"a4153a1c-b4ee-55f3-bc86-be654c67c262","type":"button","content":{"href":"/ar/quote","label":"احصل على عرض سعر","variant":"inverse"},"visible":true},{"id":"6abccc85-8d70-55eb-8930-cfb21917b0ab","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"solid","footerVisible":true,"catalogPosition":5},"template":"solution-detail","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('a13f524b-ff0d-5542-91e2-7922b360d555', 'تأمين المركبات التجارية والأساطيل', 'ar/solutions/commercial-motor-fleet', '2026-10-12 11:00:07+00', '{"Title":"تأمين المركبات التجارية والأساطيل في لبنان | تريبل إتش","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين المركبات التجارية والأساطيل | تريبل إتش وسيط التأمين","ImageUrl":null,"Description":"احمِ مركبات شركتك بتأمين مركبات تجارية وأساطيل ترتّبه تريبل إتش وسيط التأمين في لبنان."},"Description":"تأمين مركبات تجارية وأساطيل في لبنان لمركبات الشركة. قارن شركات التأمين ورتّب تغطية مناسبة مع تريبل إتش وسيط التأمين.","CanonicalUrl":"https://www.triplehbroker.com/ar/solutions/commercial-motor-fleet"}', '2026-10-12 11:00:07+00', false, false, 'ar', '00b25096-3cfa-4cd0-a037-96ac0b9aa8d4', 'builder', '{"type":"page","children":[{"id":"6183689a-adfe-55e4-907f-b4a73334bdf0","type":"section","styles":{"preset":"cinematic-tall"},"content":{"intro":"تغطية لمركبات شركتك والمسؤوليات تجاه الغير المرتبطة بها، تُرتَّب وفق استخدامها في أعمالك.","items":[{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"}],"eyebrow":"تأمين الأعمال والموظفين","heading":"تأمين المركبات التجارية والأساطيل","imageAlt":"","mobileImageUrl":"","desktopImageUrl":""},"visible":true,"children":[],"settings":{"sectionType":"hero-banner"}},{"id":"3f8c2236-c5fd-5bde-b9d3-29e29497bdb3","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يساعد تأمين المركبات التجارية والأساطيل على حماية مركبات الشركة من الضرر أو الخسارة المغطاة ويوفر حماية مسؤولية للمطالبات التي تشمل أطرافاً ثالثة. تساعدك تريبل إتش على مقارنة شركات التأمين المناسبة وترتيب التغطية وفق مركباتك وسائقيك والاستخدام التجاري.","eyebrow":"تأمين المركبات التجارية والأساطيل","heading":"ما هو تأمين المركبات التجارية والأساطيل؟","audience":"الشركات والمنشآت الصغيرة والمتوسطة وغيرها من الأعمال التي تملك أو تشغّل سيارات أو شاحنات صغيرة أو بيك أب أو شاحنات أو مركبات أخرى للاستخدام التجاري.","buttonHref":"/ar/contact","buttonLabel":"اطلب عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"children":[],"settings":{"sectionType":"solution-introduction"}},{"id":"4f724811-5537-574a-8d59-60def5b27e5e","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"c9252fe6-d8f8-5ead-85b0-f661c3c9de0a","type":"container","visible":true,"children":[{"id":"68680a9c-8c0d-5182-99e2-72c7f688bff8","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"كيف يمكن تنظيم تغطية المركبات التجارية؟","level":2},"visible":true},{"id":"dfbad75b-8ece-5a4f-8863-aa5a5c29a1f0","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن ترتيب التغطية وفق مركباتك واستخدامها ومستوى الحماية الذي تحتاجه منشأتك."},"visible":true},{"id":"d0443231-ccbb-51ab-9113-fecf8bca9709","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"82030b68-de8f-5667-a59b-b47a789a5cc7","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"a41239e2-4a8d-551a-899b-4e3ae8cb8cfb","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"مركبات الشركة","level":3},"visible":true},{"id":"9724b2b3-36e4-5aa2-b538-ac023a2ce921","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تغطية للسيارات والشاحنات الصغيرة وغيرها من المركبات المؤهلة التي تملكها أو تشغّلها منشأتك."},"visible":true}]},{"id":"22318661-1872-5355-810c-cbf8d2f8f334","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"436fbf4c-3dbf-5b0e-97fe-3cfbf9e979ca","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"ترتيبات الأساطيل","level":3},"visible":true},{"id":"f6400d4a-fda1-506a-ba54-8dd0087e6fbb","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن إدارة عدة مركبات تجارية ضمن ترتيب تأميني منسّق."},"visible":true}]},{"id":"b2c7db9a-ddd7-5f17-a4d4-a2c7c7d7b301","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"1bebc690-0958-5e82-9edf-082ae5989bcf","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"استخدامات مختلفة للمركبات","level":3},"visible":true},{"id":"c533267c-64b2-528f-86cc-512ed2475102","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن أن تعكس التغطية استخدام المركبات في المبيعات أو التوصيل أو النقل أو أنشطة أعمال أخرى."},"visible":true}]},{"id":"e26a6a62-4b4e-56c9-a26c-c58b2005908b","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"19887a76-70e9-50a5-bdea-e6dd52fe4eab","type":"heading","content":{"text":"مستويات تغطية مرنة","level":3},"visible":true},{"id":"05f06bda-a683-54d5-82a0-582697efd4a2","type":"text","content":{"text":"يمكن تنظيم الحماية بمنافع مناسبة للمسؤولية وأضرار المركبة ومنافع اختيارية وفق احتياجات أعمالك."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"25ea1dc9-8daa-53d3-8cca-23eb2a7c2aac","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن شركات التأمين في السوق اللبنانية والتغطية والحدود ومبالغ التحمل وشروط الإصلاح والوثيقة، ونرتّب الحماية المناسبة لأعمالك ونتولى المطالبات من الإبلاغ مروراً بالتقييم وصولاً إلى التسوية.","intro":"يجمع تأمين المركبات التجارية بين المسؤولية الإلزامية تجاه الغير وتغطية أوسع لمركباتك ومسؤوليات الغير ومخاطر إضافية مختارة. تعتمد المنافع والحدود والشروط الدقيقة على الوثيقة المرتبة.","items":[{"text":"المسؤولية الإلزامية تجاه الغير — الأضرار الجسدية والمادية"},{"text":"تأمين جميع أخطار السيارات / التغطية الشاملة"},{"text":"الأضرار العرضية للمركبات المؤمّنة"},{"text":"تغطية الخسارة الكلية"},{"text":"الحريق والانفجار"},{"text":"السرقة ومحاولة السرقة"},{"text":"الأخطار الطبيعية وأضرار الطقس"},{"text":"تغطية الإضرابات والشغب والاضطرابات المدنية والإرهاب"},{"text":"أضرار الزجاج الأمامي والزجاج"},{"text":"الحوادث الشخصية للسائق والركاب"},{"text":"النفقات الطبية للسائق والركاب"},{"text":"المساعدة على الطريق والقطر"},{"text":"مركبة بديلة / مستأجرة وفق شروط الوثيقة"},{"text":"البطاقة البرتقالية — المسؤولية تجاه الغير عبر الحدود"}],"heading":"ماذا يمكن أن يغطي تأمين المركبات التجارية والأساطيل؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"05835162-b1e6-5b81-a6bb-c69b373e74b8","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تعتمد التغطية المناسبة على أكثر من القسط. فحدود المسؤولية وقيم المركبات ومبالغ التحمل وشروط الإصلاح والسائقين والمساعدة والتسوية وإدارة الأسطول تؤثر جميعها في أداء الوثيقة عملياً.","items":[{"text":"سمعة شركة التأمين وشبكة الإصلاح وشروط تسوية المطالبات"},{"text":"الأقساط والتكلفة الإجمالية للأسطول"},{"text":"حدود المسؤولية تجاه الغير ونطاق تغطية الخسارة الكلية أو جميع الأخطار"},{"text":"قيم المركبات وأساس تسوية الخسارة الكلية"},{"text":"مبالغ التحمل العامة والإضافية المطبّقة على السائقين"},{"text":"شروط الإصلاح والمرائب المعتمدة وإصلاحات الوكيل واستهلاك قطع الغيار"},{"text":"أهلية السائقين والقيود والاستخدام التجاري المصرّح به"},{"text":"الحدود الجغرافية ومتطلبات عبور الحدود / البطاقة البرتقالية"},{"text":"شروط المساعدة على الطريق والقطر والمركبة البديلة / المستأجرة"},{"text":"إدارة جدول الأسطول وإضافة المركبات أو حذفها وسجل المطالبات عند التجديد"}],"heading":"ما الذي ينبغي مقارنته قبل اختيار تأمين المركبات التجارية والأساطيل؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"06309ee0-7233-51e4-b2e9-1db09379f228","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"نراجع أسطولك واستخدامه ونقارن شركات التأمين المناسبة في لبنان وشروط الوثائق، ثم نرتّب التغطية المختارة ونحافظ عليها مع تغير مركباتك.","items":[{"body":"نراجع مركباتك وقيمها واستخدامها التجاري وسائقيها وسجل المطالبات لفهم المخاطر التي يجب تأمينها.","title":"فهم أسطولك"},{"body":"نقارن شركات التأمين المناسبة من حيث التغطية وحدود المسؤولية ومبالغ التحمل وشروط الإصلاح والتوسعات وشروط تسوية المطالبات والقسط.","title":"مقارنة شركات التأمين المناسبة"},{"body":"نرتّب إصدار الوثيقة المختارة ونؤكد المركبات المؤمّنة والشروط المتفق عليها ونتحقق من إصدار المستندات والجداول المطلوبة بصورة صحيحة.","title":"ترتيب التغطية المختارة"},{"body":"نتولى مطالبات التأمين وإضافة المركبات وحذفها، ونحدّث تفاصيل الوثيقة عند تغير أسطولك ونُعدّ المعلومات المطلوبة للتجديد.","title":"إبقاء أسطولك محدّثاً"}],"layout":"grid","heading":"كيف نرتّب تأمين المركبات التجارية والأساطيل؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"d5454116-d748-583f-aeb6-f4cbe2f831e4","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تواصل مع تريبل إتش بأسرع وقت. نتولى المطالبة من الإبلاغ مروراً بالتقييم والإصلاح أو التسوية ونتابع مع شركة التأمين نيابةً عنك.","items":[{"text":"نسجل المطالبة لدى شركة التأمين ونؤكد المستندات المطلوبة وننسّق التقييم الأولي للمركبة وظروف الحادث."},{"text":"نتابع الإصلاح أو تقييم الخسارة ونتواصل مع شركة التأمين والمرآب والأطراف المعنية ونساعد على حل المشاكل التي قد تؤخر المطالبة."},{"text":"نراجع التسوية المقترحة وفق شروط الوثيقة ونواصل متابعة الملف حتى تسوية المطالبة واكتمال الإجراءات."}],"heading":"ماذا يحدث عندما تتعرض إحدى مركبات شركتك لحادث؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"e7fcd9ca-9835-5d16-b392-d8dadfb8d8ff","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عملية عن التغطية والسائقين وتغيرات الأسطول والمطالبات وكيفية عمل تأمين المركبات التجارية لمنشأتك.","items":[{"answer":"يجب أن تستوفي كل مركبة للشركة متطلبات التأمين الإلزامي في لبنان. وبعد ذلك، يمكن اختيار تغطية الغير أو الخسارة الكلية أو جميع الأخطار بحسب المركبة ومستوى الحماية المطلوب.","question":"س1 – ما تأمين السيارات الذي تحتاجه منشأتنا لمركباتها؟"},{"answer":"لا. قد تختلف مستويات التغطية بين المركبات بحسب قيمتها وعمرها واستخدامها واحتياجات أعمالك. مثلاً، قد تحتاج مركبة إلى حماية جميع الأخطار بينما تناسب أخرى تغطية الخسارة الكلية أو الغير أكثر، وفق شروط شركة التأمين.","question":"س2 – هل تحتاج كل مركبات أسطولنا إلى مستوى التغطية نفسه؟"},{"answer":"تقدم شركتك تفاصيل السائقين الذين سيستخدمون المركبات المؤمّنة. يجب أن يحمل كل سائق رخصة قيادة صالحة ويستوفي متطلبات العمر المطبّقة لدى شركة التأمين ويستخدم المركبة للغرض التجاري المصرّح به.","question":"س3 – من يمكنه قيادة مركبات شركتنا المؤمّنة؟"},{"answer":"قد يعتمد السعر على عدد المركبات وأنواعها وقيمها وأعمارها واستخدامها والسائقين وسجل المطالبات ومستوى التغطية ومبالغ التحمل وشروط الإصلاح ومعايير التسعير لدى شركة التأمين. نقارن القسط والشروط التي تقف وراءه.","question":"س4 – ما الذي يؤثر في تكلفة تأمين المركبات التجارية والأساطيل؟"},{"answer":"نعم. تواصل مع تريبل إتش كلما تغير أسطولك. ننسّق الإضافات والحذف واستبدال المركبات مع شركة التأمين ونحدّث جدول الوثيقة ليظل الأسطول المؤمّن محدّثاً.","question":"س5 – هل يمكن إضافة مركبات أو حذفها أو استبدالها خلال مدة الوثيقة؟"},{"answer":"تواصل مع تريبل إتش عبر خطنا الساخن المتاح على مدار الساعة طوال الأسبوع بمجرد أن يكون ذلك آمناً. نرتّب خبير المطالبات عند الحاجة وننسّق المستندات والتقييم ونتعامل مع شركة التأمين والمرآب والأطراف الثالثة المعنية ونتابع المطالبة خلال الإصلاح أو التسوية.","question":"س6 – ماذا ينبغي أن تفعل شركتنا بعد حادث؟"},{"answer":"تعتمد التسوية على شروط الوثيقة وقيمة المركبة وقت الخسارة وعتبة الخسارة الكلية وأساس التسوية ومبلغ التحمل. نراجع التقييم والتسوية مع شركة التأمين ونتولى المطالبة نيابةً عن شركتك.","question":"س7 – ماذا يحدث إذا اعتُبرت إحدى مركباتنا خسارة كلية؟"},{"answer":"يعتمد ذلك على الوثيقة المختارة والمركبة وشركة التأمين. توفر بعض الخطط إصلاحات لدى الوكيل الرسمي للمركبات المؤهلة، بينما تستخدم أخرى مرائب معتمدة. نقارن ترتيبات الإصلاح وشروط قطع الغيار والأحكام المطبّقة قبل إصدار الوثيقة.","question":"س8 – هل يمكن إصلاح مركبات شركتنا لدى الوكيل الرسمي؟"},{"answer":"تعتمد هذه المنافع على الخطة المختارة. قد تشمل المساعدة على الطريق القطر بعد الحوادث، وفي بعض الوثائق، المساعدة بعد عطل ميكانيكي أو كهربائي. ويمكن أيضاً إدراج منافع مركبة بديلة أو مستأجرة وفق حدود الوثيقة ومدتها وشروطها.","question":"س9 – هل يشمل تأمين المركبات التجارية القطر ومركبة بديلة؟"},{"answer":"نعم، حيث تتاح التغطية الجغرافية المطلوبة. للسفر إلى بلدان تشارك في نظام البطاقة البرتقالية، يمكننا ترتيب مستندات المسؤولية تجاه الغير عبر الحدود قبل سفر المركبة.","question":"س10 – هل يمكن تغطية مركبات شركتنا عند السفر خارج لبنان؟"},{"answer":"نحتاج عادةً إلى مستندات مركباتك وقيمها واستخدامها وتفاصيل السائقين. وقد تُطلب معلومات إضافية بحسب المركبات والتغطية المطلوبة.","question":"س11 – ما المعلومات المطلوبة لعرض تأمين مركبات تجارية أو أسطول؟"}],"heading":"الأسئلة الشائعة حول تأمين المركبات التجارية والأساطيل","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"7353628a-25aa-581c-bb0b-c5c29cc155c4","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف تغطيات أخرى لحماية أعمالك وممتلكاتك وموظفيك إلى جانب تأمين المركبات التجارية.","heading":"تأمينات أخرى للأعمال","buttonHref":"/ar/solutions/business","buttonLabel":"استكشف تأمين الأعمال"},"visible":true,"children":[],"settings":{"sectionType":"callout"}},{"id":"d7832422-30dc-581e-b3af-5ab197048610","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"0bea9740-3c79-5f63-8655-25e07294ce61","type":"container","visible":true,"children":[{"id":"9d3b6c29-a429-5f52-9365-d3b25e02df93","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"احصل على عرض تأمين للمركبات التجارية والأساطيل","level":2},"visible":true},{"id":"274aad25-2e75-5ad8-9948-cf4c450908ec","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أخبرنا عن مركبات شركتك واستخدامها. سنقارن شركات التأمين المناسبة في السوق اللبنانية وخيارات التغطية ونقدم عروضاً مكتوبة وواضحة."},"visible":true},{"id":"01396db4-3e6b-5618-a853-530e8ec89380","type":"button","content":{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},"visible":true},{"id":"e58ed322-fbae-5441-892f-c7cd174a3bd2","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"builder","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('20000000-0000-0000-0000-000000000007', 'الأسئلة الشائعة | تريبل إتش وسيط التأمين', 'ar/faq', '2026-10-12 11:00:07+00', '{"Title":"الأسئلة الشائعة حول التأمين في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"الأسئلة الشائعة حول التأمين | تريبل إتش وسيط التأمين","ImageUrl":"","Description":"إجابات واضحة عن أسئلة شائعة حول تريبل إتش وعروض التأمين واختيار التغطية والوثائق والتجديدات في لبنان."},"Description":"إجابات واضحة من تريبل إتش وسيط التأمين عن التأمين في لبنان، بما فيه الوسطاء والعروض والتغطية وشروط الوثائق والتجديدات.","CanonicalUrl":"https://triplehbroker.com/ar/faq"}', '2026-08-08 09:52:35.69894+00', false, true, 'ar', 'f20c50e1-6b91-6a2b-e56b-1c8ab4936a58', 'faq', '{"type":"page","children":[{"id":"384b1b7a-a696-5266-8051-a154b75235b9","type":"section","styles":{"size":"base","tone":"default","preset":"cinematic-tall","bordered":false},"content":{"intro":"اعثر على إجابات واضحة عن اختيار التغطية والعمل مع وسيط التأمين وعروض الأسعار والوثائق والتجديدات وأسئلة التأمين اليومية في لبنان.","items":[],"eyebrow":"الأسئلة الشائعة حول التأمين","heading":"أسئلة التأمين بإجابات واضحة.","imageAlt":"مستشار تأمين يجيب عن أسئلة عميل","mobileImageUrl":"https://triplehbroker.com/uploads/20260808072307-4ac8a712be4844c99ac105214f21d358.webp","desktopImageUrl":"https://triplehbroker.com/uploads/20260808072307-4ac8a712be4844c99ac105214f21d358.webp"},"visible":true,"position":0,"settings":{"sectionType":"hero-banner"}},{"id":"44253436-91c0-5d35-b956-28930b6b9147","type":"section","styles":{"size":"base","tone":"default","preset":"accordion-groups","bordered":true},"content":{"intro":"تصفّح إجابات واضحة عن العمل مع تريبل إتش واختيار التأمين والحصول على عرض سعر والوثائق والتجديدات.","items":[{"group":"عن تريبل إتش","answer":"لا. تريبل إتش وسيط تأمين مرخّص. تتولى شركات التأمين الاكتتاب بالخطر وإصدار الوثائق، بينما نقيّم احتياجاتك ونقارن شركات التأمين المناسبة ونرتّب تغطيتك وندير العلاقة نيابةً عنك.","question":"س1 – هل أنتم شركة تأمين؟"},{"group":"عن تريبل إتش","answer":"يعمل الوسيط معك بدلاً من تمثيل شركة تأمين واحدة. نساعدك على مقارنة الخيارات المناسبة وفهم الشروط والحدود والاستثناءات وترتيب تغطيتك، ونواصل المتابعة خلال التجديدات والمطالبات.","question":"س2 – لماذا أستخدم وسيط تأمين بدلاً من التواصل مباشرةً مع شركة التأمين؟"},{"group":"عن تريبل إتش","answer":"لا. للوثيقة والشروط نفسيهما، لا يزيد ترتيب تأمينك عبر تريبل إتش السعر الذي تعرضه شركة التأمين. تُرتَّب أتعابنا بشكل منفصل عبر اتفاقيات مع شركات التأمين، بينما تستفيد من المشورة المستقلة والمقارنة والدعم المستمر من الوسيط.","question":"س3 – هل سأدفع أكثر مع تريبل إتش؟"},{"group":"عن تريبل إتش","answer":"تحمل تريبل إتش وسيط التأمين ش.م.م. ترخيص وسيط رقم 581 من وزارة الاقتصاد والتجارة في لبنان، وسجلاً تجارياً رقم 2077214.","question":"س4 – كيف أتحقق من ترخيص تريبل إتش؟"},{"group":"عن تريبل إتش","answer":"نساعد العملاء بالعربية والإنجليزية والفرنسية.","question":"س5 – ما اللغات التي تعملون بها؟"},{"group":"عروض الأسعار واختيار التغطية","answer":"يمكن احتساب عروض التأمين الطبي والسيارات عبر خدمتنا الإلكترونية للعروض الفورية. للمخاطر الشخصية والتجارية والمتخصصة الأخرى، تواصل معنا لنقيّم متطلباتك ونرتّب عروضاً مناسبة.","question":"س1 – كيف أحصل على عرض تأمين؟"},{"group":"عروض الأسعار واختيار التغطية","answer":"تعتمد المعلومات على نوع التأمين. قد نطلب تفاصيل عنك أو مركبتك أو عقارك أو منشأتك أو موظفيك أو مخاطر أخرى مؤمّنة. تساعد المعلومات الكاملة والدقيقة شركات التأمين على تقديم الشروط والسعر الصحيحين.","question":"س2 – ما المعلومات التي تحتاجونها لعرض سعر؟"},{"group":"عروض الأسعار واختيار التغطية","answer":"لا. يخضع العرض للمعلومات المقدمة والاكتتاب وقبول شركة التأمين. لا تُؤكد التغطية إلا بعد قبول شركة التأمين للخطر وإصدار الوثيقة.","question":"س3 – هل العرض الإلكتروني أو المكتوب مضمون؟"},{"group":"عروض الأسعار واختيار التغطية","answer":"نبدأ باحتياجاتك والمخاطر التي تريد حمايتها، ثم نقارن شركات التأمين المناسبة من حيث التغطية والأحكام والشروط والحدود والاستثناءات والسعر. نعرض الخيارات الأنسب بوضوح ونشرح الفروق ونرشدك إلى التغطية الأكثر ملاءمة لاحتياجاتك، لتتخذ قراراً مدروساً بثقة أكبر.","question":"س4 – كيف تساعدني تريبل إتش على اختيار التأمين المناسب؟"},{"group":"الوثائق والتجديدات","answer":"تبدأ التغطية وفق تاريخ السريان المؤكد بعد قبول شركة التأمين للخطر وإصدار الوثيقة. لا يعني عرض السعر وحده أن التغطية قائمة.","question":"س1 – متى تبدأ تغطيتي التأمينية؟"},{"group":"الوثائق والتجديدات","answer":"يجب أن تفهم ما يُغطّى وحدود الوثيقة والاستثناءات والشروط المهمة وأي مبلغ تحمل مطبّق. نشرح الشروط ذات الصلة قبل قبولك الوثيقة لتتمكن من اتخاذ قرار مدروس.","question":"س2 – ما الذي يجب فهمه قبل قبول الوثيقة؟"},{"group":"الوثائق والتجديدات","answer":"أخبر تريبل إتش بأسرع وقت عند حدوث تغير مهم في الخطر المؤمّن. سنتحقق مما إذا كان يجب إبلاغ شركة التأمين ونرتّب أي تعديل لازم لوثيقتك.","question":"س3 – ماذا أفعل إذا تغير شيء خلال مدة وثيقتي؟"},{"group":"الوثائق والتجديدات","answer":"لا تحتاج إلى الانتظار حتى اقتراب انتهاء وثيقتك أو التواصل معنا أولاً. نراجع تغطيتك مسبقاً ونراعي تغيرات احتياجاتك أو ظروفك ونقيّم شروط التجديد وقسطه، ونقارن البدائل المناسبة عند الاقتضاء. ثم نتواصل معك في الوقت المناسب ونشرح الخيارات ونساعدك على اتخاذ قرار تجديد مدروس.","question":"س4 – ماذا يحدث عندما يحين تجديد وثيقة تأميني؟"}],"heading":"الأسئلة الشائعة","showArrows":true,"smoothMotion":true},"visible":true,"position":1,"settings":{"sectionType":"faq-groups"}},{"id":"d497b016-3a93-5945-8904-9e56e633ff11","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"da42334f-ff7d-5d43-bd84-4b8b486f683a","type":"container","visible":true,"children":[{"id":"2c015668-4b91-5ce1-a8f5-e3c17e58cf0f","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"هل لا يزال لديك سؤال؟","level":2},"visible":true},{"id":"451ee626-9553-5c61-ac16-ed755270c508","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تواصل مع فريقنا للحصول على إرشاد واضح ومخصص بشأن احتياجاتك التأمينية أو وثيقتك أو تغطيتك."},"visible":true},{"id":"8cb8a2e3-4cbd-5294-bdb6-144e71e9f5f4","type":"button","content":{"href":"/ar/contact","label":"اتصل بنا","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"faq","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('45d78df8-2812-5f76-a576-2dc12c5c752b', 'الوظائف | تريبل إتش وسيط التأمين', 'ar/careers', '2026-10-12 11:00:07+00', '{"Title":"وظائف في تريبل إتش | وسيط تأمين في لبنان","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"وظائف في تريبل إتش وسيط التأمين","ImageUrl":null,"Description":"استكشف فرص العمل مع تريبل إتش وتعرّف على نهجنا المهني في التأمين وخدمة العملاء في لبنان."},"Description":"استكشف فرص العمل لدى تريبل إتش وسيط التأمين في لبنان وتعرّف على نهجنا المهني في خدمة العملاء والمشورة التأمينية.","CanonicalUrl":"https://triplehbroker.com/ar/careers"}', '2026-10-12 11:00:07+00', false, false, 'ar', 'b602dd3c-009e-4516-b869-58349b01c42a', 'career', '{"type":"page","children":[{"id":"2c4c1b9d-a353-53f7-8aaa-77667c6eacaf","type":"section","styles":{"preset":"cinematic-tall"},"content":{"intro":"انضم إلى شركة وساطة تأمين مهنية تضع المشورة الواضحة وخدمة العملاء والعلاقات طويلة الأمد في صميم عملها.","items":[{"href":"/ar/contact","label":"اعرف المزيد","variant":"inverse"}],"eyebrow":"الوظائف","heading":"ابنِ مسيرتك المهنية مع تريبل إتش.","imageAlt":"","mobileImageUrl":"/uploads/20260927163655-2d0e830a4ad94355b73420cdf06d75d0.webp","desktopImageUrl":"/uploads/20260927162433-3b1a96fa432341f8983541df256244bc.webp"},"visible":true,"children":[],"settings":{"sectionType":"hero-banner"}},{"id":"c9f39fbb-34e4-5d91-8918-3816bf1104f2","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"dd042869-8957-5550-8899-9790a67d3a78","type":"container","visible":true,"children":[{"id":"b2a7a95a-871b-5c3f-a34e-be3e55619808","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"اعمل بهدف ومهنية.","level":2},"visible":true},{"id":"64a06548-cadb-5988-813e-2680d82fee8e","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يقوم عملنا على فهم العملاء وشرح التأمين بوضوح ومواصلة المتابعة عندما يهم الدعم. نبحث عن أشخاص يقدّرون الدقة والمسؤولية والتواصل الواضح والعلاقات طويلة الأمد، ويلتزمون بتقديم خدمة تأمينية عالية المستوى."},"visible":true}]}],"settings":{"sectionType":"text"}},{"id":"2f770181-ba6f-5d7f-8c32-638492d3fb4e","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"eb6d1268-ce3b-512e-872b-33fa56742668","type":"container","visible":true,"children":[{"id":"c75bc2a1-97f0-583a-ad36-94d1aa6e67fd","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"هل ترغب في الانضمام إلى تريبل إتش؟","level":2},"visible":true},{"id":"e2ed2cc3-c8cf-586e-8255-e43512b90daf","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"إذا كنت ترغب في بناء مسيرتك مع تريبل إتش، أرسل سيرتك الذاتية ورسالة تعريفية مختصرة. تُراجع الطلبات وفق الفرص الحالية والمستقبلية داخل الشركة."},"visible":true},{"id":"8fd54f84-f0a1-5b2d-951f-7469d24adde3","type":"button","content":{"href":"mailto:c.haddad@triplehbroker.com","label":"أرسل سيرتك الذاتية بالبريد الإلكتروني","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"builder","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('738aa459-4b3e-5821-868e-72c5aa5e00e7', 'تأمين المسؤولية التجارية | تريبل إتش وسيط التأمين', 'ar/solutions/commercial-liability-insurance', '2026-10-12 11:00:07+00', '{"Title":"تأمين المسؤولية التجارية في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين المسؤولية التجارية في لبنان | تريبل إتش","ImageUrl":null,"Description":"تأمين مسؤولية تجارية لإصابات الغير وأضرار الممتلكات، ترتّبه تريبل إتش وسيط التأمين وفق أنشطة أعمالك."},"Description":"تأمين مسؤولية تجارية في لبنان لإصابات الغير وأضرار الممتلكات. قارن الشركات والحدود والشروط مع تريبل إتش وسيط التأمين.","CanonicalUrl":"https://www.triplehbroker.com/ar/solutions/commercial-liability-insurance"}', '2026-10-12 11:00:07+00', false, false, 'ar', 'ffe00e81-8c41-4737-92b3-d5bbfd1a5658', 'builder', '{"type":"page","children":[{"id":"e1ce0e85-11a2-5a36-b44a-6cf2b815edd9","type":"section","styles":{"preset":"cinematic-tall"},"content":{"intro":"احمِ منشأتك من مطالبات الإصابات الجسدية أو أضرار ممتلكات الغير الناشئة عن مقراتك أو أنشطتك أو منتجاتك، بتغطية تُرتَّب وفق أنشطتك ومخاطر مسؤوليتك.","items":[{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"}],"eyebrow":"تأمين الأعمال والموظفين","heading":"تأمين المسؤولية التجارية","imageAlt":"","mobileImageUrl":"","desktopImageUrl":""},"visible":true,"children":[],"settings":{"sectionType":"hero-banner"}},{"id":"a1e663c2-85da-5e7b-8764-c225c597b2a7","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يمكن لتأمين المسؤولية التجارية حماية منشأتك من المسؤولية القانونية عن الإصابات الجسدية أو أضرار ممتلكات الغير الناشئة عن مقراتك أو أنشطتك أو منتجاتك. تقارن تريبل إتش شركات التأمين المناسبة وترتّب التغطية وفق أنشطتك ومواقعك ومنتجاتك وحدود المسؤولية المطلوبة.","eyebrow":"تأمين المسؤولية التجارية","heading":"ما هو تأمين المسؤولية التجارية؟","audience":"المقاولون وشركات التنظيف والصيانة والمطاعم وتجار التجزئة والمصنّعون والموزعون ومنظمو الفعاليات وشركات الإعلان أو اللافتات التي تعمل في مواقع العملاء أو المواقع العامة.","buttonHref":"/ar/contact","buttonLabel":"اطلب عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"children":[],"settings":{"sectionType":"solution-introduction"}},{"id":"bb75fa09-d8e1-52ac-b54b-918b27145f81","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"bbb830e4-06ed-5180-b42d-d071c0a4cd2f","type":"container","visible":true,"children":[{"id":"c86ec572-1ca8-50d4-9825-0d669c9701ac","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"كيف يمكن تنظيم تغطية المسؤولية التجارية؟","level":2},"visible":true},{"id":"60cd3741-391a-5f7a-b747-7d2cad42300e","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن تنظيم التغطية وفق مواقع عمل منشأتك والأعمال التي تنفذها وما إذا كانت منتجاتك قد تنشئ مسؤولية بعد توريدها."},"visible":true},{"id":"ce6277eb-98af-57cd-ae82-448b13394c26","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"42fb9ab2-95fd-5cfa-844f-cd17bc9fbe8f","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"88ae1749-8182-5cf3-b5ee-65e421519fa3","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"المسؤولية العامة","level":3},"visible":true},{"id":"ef0faedf-6f01-52f9-9bb6-b7ec0794edc2","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تغطية للمسؤولية القانونية الناشئة عن إصابات الغير الجسدية أو أضرار ممتلكاتهم المرتبطة بمقراتك أو أنشطة أعمالك."},"visible":true}]},{"id":"dcf4b350-12b9-5cc3-8d1b-f43d10ba9097","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"b4a952e4-3b21-5110-b38f-78a2459d5892","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"الأعمال خارج المقر والأعمال التعاقدية","level":3},"visible":true},{"id":"8abb45af-5307-5abf-8bb9-ce3132115f71","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن ترتيب تغطية للشركات التي تنفذ أعمالاً في مواقع العملاء أو مواقع أخرى، مثل المقاولين وشركات التنظيف والصيانة والتركيب."},"visible":true}]},{"id":"480eed52-ed6b-56a1-a75e-b81614973920","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"f72f1d52-3556-55f4-a5be-f967cb34b356","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"مسؤولية المنتجات","level":3},"visible":true},{"id":"4a7bbdd2-f0a5-5688-88f9-035d6fe4c1e8","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"للشركات التي تصنّع المنتجات أو توزعها أو توردها، لتغطية المسؤولية القانونية عن إصابات الغير أو أضرار ممتلكاتهم الناجمة عن تلك المنتجات."},"visible":true}]},{"id":"8c14ac51-7f93-55c7-864f-c03a333b0d51","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"a84ccddc-5277-571a-bed3-e9bf8bc52329","type":"heading","content":{"text":"تغطية مسؤولية مشتركة","level":3},"visible":true},{"id":"d50c9c45-a0cb-5d62-86f3-b0e0eab74125","type":"text","content":{"text":"يمكن للشركات المعرضة لمخاطر التشغيل والمنتجات ترتيب المسؤولية العامة ومسؤولية المنتجات معاً، بحدود وشروط تُنظَّم وفق أنشطتها."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"e95be006-6a3f-5dbe-b997-6bb32f46157d","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن شركات التأمين وحدود المسؤولية ومبالغ التحمل والأنشطة والمواقع المؤمّنة والتوسعات والاستثناءات، ونرتّب تغطية مناسبة لأعمالك ونتولى المطالبات مع شركة التأمين من الإبلاغ مروراً بالتقييم وصولاً إلى التسوية.","intro":"بحسب الوثيقة وأنشطتك، يمكن أن يغطي تأمين المسؤولية التجارية المسؤولية القانونية عن الإصابات الجسدية العرضية أو أضرار ممتلكات الغير الناشئة عن مقراتك أو أنشطتك أو منتجاتك، وتكاليف قانونية وتوسعات معينة حيث تُدرج.","items":[{"text":"الإصابات الجسدية للغير"},{"text":"أضرار ممتلكات الغير"},{"text":"المسؤولية الناشئة عن مقرات أعمالك"},{"text":"المسؤولية عن الأعمال والأنشطة خارج المقر، حيث تشملها التغطية"},{"text":"مسؤولية المنتجات، حيث تشملها التغطية"},{"text":"تكاليف ونفقات الدفاع القانوني، حيث تشملها التغطية"},{"text":"مسؤولية التسمم بالطعام والشراب، عند إضافتها"},{"text":"مسؤولية اللافتات، عند إضافتها"},{"text":"تغطية سحب المنتجات، عند ترتيبها تحديداً"}],"heading":"ماذا يمكن أن يغطي تأمين المسؤولية التجارية؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"73d6ae63-c106-52d7-a29a-5a64615d4c9c","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تعتمد وثيقة المسؤولية المناسبة على أكثر من القسط. فقد تحدث الحدود والأنشطة المؤمّنة والتكاليف القانونية والنطاق الجغرافي والاستثناءات فرقاً كبيراً عند حدوث مطالبة.","items":[{"text":"سمعة شركة التأمين وخبرتها في المسؤولية وسجلها في تسوية المطالبات"},{"text":"تغطية المسؤولية العامة والمنتجات والتغطية المشتركة المطلوبة"},{"text":"الحد لكل حادث والإجمالي السنوي، عند انطباقه"},{"text":"تكاليف الدفاع القانوني وما إذا كانت تُنقص حد المسؤولية"},{"text":"أنشطة الأعمال والمقرات والأنشطة خارج المقر المشمولة"},{"text":"الحدود الجغرافية والاختصاصات القضائية المشمولة"},{"text":"مبالغ التحمل والحدود الفرعية للوثيقة"},{"text":"شروط مسؤولية المقاولين والمقاولين من الباطن"},{"text":"الاستثناءات الرئيسية المؤثرة في أنشطتك أو منتجاتك أو أعمالك بمواقع العملاء"},{"text":"متطلبات العملاء أو المؤجرين أو المناقصات لحدود المسؤولية وشروط الوثيقة"}],"heading":"ما الذي ينبغي مقارنته قبل اختيار تأمين المسؤولية التجارية؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"475d1ecb-dbd5-5e73-ba94-c19360a32992","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"نراجع أين قد تواجه منشأتك مطالبات من الغير ونقارن شركات التأمين المناسبة في السوق اللبنانية وشروط المسؤولية، ثم نرتّب التغطية وفق أنشطتك الفعلية.","items":[{"body":"نراجع أنشطتك ومقراتك وأعمالك خارج المقر ومنتجاتك وحجم مبيعاتك وعقودك ومطالباتك السابقة.","title":"مراجعة مخاطر مسؤوليتك"},{"body":"نقارن حدود المسؤولية والتكاليف القانونية ومبالغ التحمل والنطاق الجغرافي والتوسعات والاستثناءات والقسط.","title":"مقارنة شركات التأمين المناسبة"},{"body":"نرتّب إصدار الوثيقة المختارة ونؤكد الأنشطة والحدود المؤمّنة ونرتّب أي شهادات مسؤولية أو ملاحق مطلوبة.","title":"ترتيب التغطية المختارة"},{"body":"نتولى المطالبات والتعديلات والتجديدات مع تغير أنشطتك أو عقودك أو مواقعك أو منتجاتك أو متطلبات المسؤولية.","title":"إبقاء التغطية محدّثة"}],"layout":"grid","heading":"كيف نرتّب تأمين المسؤولية التجارية؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"69e3891a-ea49-5e79-959d-f3e3d6b2ed5b","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تواصل مع تريبل إتش فور وقوع حادث أو تقديم مطالبة. نُبلغ شركة التأمين وننسّق المطالبة نيابةً عنك ونتابعها خلال التقييم والدفاع والتسوية.","items":[{"text":"نؤكد المعلومات المطلوبة ونساعدك على تقديم تقارير الحادث والصور وتفاصيل الشهود والمراسلات وغيرها من المستندات الداعمة."},{"text":"ننسّق مع شركة التأمين وخبير تسوية الخسائر والمحامين عند الحاجة ونتابع التقييم أثناء تحديد المسؤولية وحجم المطالبة."},{"text":"نراجع رد شركة التأمين وأي تسوية مقترحة وفق شروط الوثيقة ونواصل متابعة المطالبة حتى انتهاء الإجراءات."}],"heading":"ما الذي تفعله عندما يقدم طرف ثالث مطالبة ضد منشأتك؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"0134e201-b525-51fe-a41e-766532224443","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عملية عن مطالبات الغير والمسؤولية العامة ومسؤولية المنتجات وأنشطة الأعمال وحدود المسؤولية وما يجب فعله عند وقوع حادث.","items":[{"answer":"تغطي المسؤولية العامة المطالبات الناشئة عن مقراتك أو أنشطة أعمالك، بينما تغطي مسؤولية المنتجات المطالبات الناجمة عن منتجات تصنّعها أو توردها أو تبيعها.","question":"س1 – ما الفرق بين المسؤولية العامة ومسؤولية المنتجات؟"},{"answer":"الطرف الثالث هو عموماً شخص خارج منشأتك، مثل زبون أو زائر أو عميل أو مورد أو فرد من الجمهور، يتعرض لإصابة أو ضرر ممتلكات مرتبط بأنشطتك.","question":"س2 – من يُعتبر طرفاً ثالثاً؟"},{"answer":"تُعالج إصابات الموظفين عادةً ضمن تأمين طوارئ العمل أو مسؤولية أصحاب العمل بدلاً من المسؤولية العامة. نراجع الخطرين لتتكامل الوثائق المناسبة.","question":"س3 – هل تغطي المسؤولية التجارية إصابات موظفينا؟"},{"answer":"نعم، إذا صُرّح بهذا النشاط وأُدرج. هذا مهم خصوصاً للمقاولين وشركات التنظيف والصيانة والتركيب وغيرها من الشركات التي تعمل بانتظام خارج مقراتها. يمكن أن تمتد المسؤولية العامة للحوادث الناشئة في أماكن تنفيذ الأنشطة.","question":"س4 – هل يمكن أن تغطي الوثيقة أعمالاً تُنفذ في مقر عميل؟"},{"answer":"قد تستجيب الوثيقة بحسب كيفية وقوع الضرر ونصها الدقيق. نتحقق قبل ترتيب التغطية من تناول أنشطتك والممتلكات المحيطة بعملك بصورة مناسبة.","question":"س5 – ماذا لو أتلفنا ممتلكات عميل عرضياً أثناء العمل لديه؟"},{"answer":"إذا كانت منشأتك تستخدم مقاولين من الباطن، أخبرنا عند ترتيب الوثيقة. نتحقق من كيفية التعامل معهم ضمن التغطية ومن تنظيم الوثيقة بصورة صحيحة لأنشطتك.","question":"س6 – هل المقاولون من الباطن مشمولون؟"},{"answer":"تُدرج تكاليف الدفاع القانوني عادةً في وثائق المسؤولية التجارية. تختلف الشركات في كيفية التعامل مع هذه التكاليف، خصوصاً ما إذا كانت تُدفع ضمن حد المسؤولية أو إضافةً إليه. نتحقق من ذلك قبل ترتيب الوثيقة.","question":"س7 – هل تكاليف الدفاع القانوني مغطاة؟"},{"answer":"ليس تلقائياً. قد يتطلب سحب المنتجات تغطية محددة، لذا ينبغي للشركات المعرضة لهذا الخطر دراسته منفصلاً عند ترتيب الوثيقة.","question":"س8 – هل تغطي مسؤولية المنتجات أيضاً تكلفة سحب منتج؟"},{"answer":"يعتمد الحد المناسب على أنشطتك ومواقعك ومنتجاتك وحجم المطالبة المحتمل وأي حدود يطلبها العملاء أو المؤجرون أو المناقصات. نقارن حدوداً مناسبة بدلاً من استخدام المبلغ نفسه لكل منشأة.","question":"س9 – ما مقدار تغطية المسؤولية الذي تحتاجه منشأتنا؟"},{"answer":"نعم. قد تحدد العقود التجارية والمناقصات حدود مسؤولية دنيا أو متطلبات معينة للوثيقة، لذا نراجعها قبل ترتيب التغطية.","question":"س10 – هل يمكن لعميل أو مناقصة اشتراط حد مسؤولية محدد؟"},{"answer":"وثّق ما حدث وتواصل مع تريبل إتش سريعاً قبل الرد على أي مطالبة أو الإقرار بالمسؤولية. نُبلغ شركة التأمين ونؤكد المعلومات المطلوبة وندير المطالبة خلال التقييم والتسوية.","question":"س11 – ماذا نفعل عند وقوع حادث أو مطالبة من الغير؟"},{"answer":"نحتاج عادةً إلى نشاط منشأتك وحجم مبيعاتها ومقراتها ومواقعها وأعمالها بمواقع العملاء ومنتجاتها عند الاقتضاء وحدود المسؤولية المطلوبة وأي متطلبات محددة للعقود أو المناقصات.","question":"س12 – ما المعلومات المطلوبة لعرض تأمين مسؤولية تجارية؟"}],"heading":"الأسئلة الشائعة حول تأمين المسؤولية التجارية","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"bad15cdb-def9-5147-bd0a-610dc294e93b","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف تغطيات أخرى لحماية موظفيك وممتلكاتك ومركبات شركتك إلى جانب تأمين المسؤولية التجارية.","heading":"تأمينات أخرى للأعمال","buttonHref":"/ar/solutions/business","buttonLabel":"استكشف تأمين الأعمال"},"visible":true,"children":[],"settings":{"sectionType":"callout"}},{"id":"53a5e17c-c729-5b02-9963-5c0041253846","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"d84f9294-1727-5d0f-8005-d5166c57eddc","type":"container","visible":true,"children":[{"id":"1c731a53-ff16-587b-acbe-b458552e8119","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"احصل على عرض تأمين مسؤولية تجارية","level":2},"visible":true},{"id":"d57bc3d7-0f71-5604-ad86-ec14409344c7","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أخبرنا عن أنشطتك ومواقع عملك وأعمالك خارج المقر أو منتجاتك وحدود المسؤولية المطلوبة. سنقارن شركات التأمين المناسبة في السوق اللبنانية ونقدم خيارات مكتوبة وواضحة."},"visible":true},{"id":"5dfb2edf-8877-5e0b-9fce-e3eda856476f","type":"button","content":{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},"visible":true},{"id":"6ead47e1-1f0a-53b7-8483-5c007e3f731b","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"builder","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('8c4bfe6c-b609-58f0-9a4a-e171388ebe01', 'تأمين الممتلكات التجارية في لبنان | تريبل إتش', 'ar/solutions/commercial-property', '2026-10-12 11:00:07+00', '{"Title":"تأمين الممتلكات التجارية في لبنان | تريبل إتش","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين الممتلكات التجارية في لبنان | تريبل إتش","ImageUrl":null,"Description":"احمِ مقرات الأعمال والمخزون والآلات والمعدات بتأمين ممتلكات تجارية ترتّبه تريبل إتش وفق احتياجات أعمالك."},"Description":"تأمين ممتلكات تجارية في لبنان لمقرات الأعمال والمخزون والمعدات ومخاطر الانقطاع. تقارن تريبل إتش شركات التأمين وترتّب التغطية المناسبة.","CanonicalUrl":"https://triplehbroker.com/ar/solutions/commercial-property"}', '2026-10-12 11:00:07+00', false, false, 'ar', '33ef3a14-7b56-4b11-8b82-b56aeca20ac1', 'builder', '{"type":"page","children":[{"id":"935d5a10-0630-5a5d-b23e-f3930abd7fd9","type":"section","styles":{"preset":"cinematic-tall"},"content":{"intro":"احمِ مقرات أعمالك ومخزونك ومعداتك وغيرها من الأصول المادية من الضرر أو الخسارة المغطاة، بتأمين يُرتَّب وفق احتياجاتك.","items":[{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"}],"eyebrow":"تأمين الأعمال والموظفين","heading":"تأمين الممتلكات التجارية في لبنان","imageAlt":"","mobileImageUrl":"","desktopImageUrl":""},"visible":true,"children":[],"settings":{"sectionType":"hero-banner"}},{"id":"2c6c4e7f-fb93-5231-b9f9-1acc1eb647be","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يحمي تأمين الممتلكات التجارية مقرات أعمالك وأصولها المادية من الخسائر أو الأضرار المغطاة. نقيّم ما يحتاج إلى حماية ونتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن التغطية والشروط المتاحة ونرتّب الوثيقة وفق أعمالك.","eyebrow":"تأمين الممتلكات التجارية","heading":"ما هو تأمين الممتلكات التجارية؟","audience":"الشركات التي تملك أو تشغل مقرات تجارية وتحتاج إلى حماية المباني أو التجهيزات الداخلية أو المخزون أو الآلات أو المعدات أو أصول مادية أخرى.","buttonHref":"/ar/contact","buttonLabel":"اطلب عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"children":[],"settings":{"sectionType":"solution-introduction"}},{"id":"d0cebb8a-6662-5cd8-b342-6912a475f2d2","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"99b190e0-7a58-5b74-95ae-054f7b66265e","type":"container","visible":true,"children":[{"id":"209c4cab-93d3-5403-9377-b59409fb67c7","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"ما الذي يمكن حمايته؟","level":2},"visible":true},{"id":"42dc06cf-5c86-5f76-87cf-18e41ed2a3e7","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن لتأمين الممتلكات التجارية حماية الأصول المادية الرئيسية التي تعتمد عليها أعمالك، سواء كنت تملك المقر أو تشغله."},"visible":true},{"id":"7de1f29e-1b72-554b-9d93-911e9f6cf731","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"425feeba-fe96-54ff-935b-6b55311b82a2","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"339981fb-b77e-54f6-964f-3105dccc573c","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"المباني والمقرات","level":3},"visible":true},{"id":"7441a83b-c490-5ae8-bd2f-dad14adbf554","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"المباني والمقرات التجارية المستخدمة لأنشطتك، بما فيها المكاتب والمتاجر والمستودعات ومواقع الأعمال الأخرى."},"visible":true}]},{"id":"bc2fd8ed-035d-5ef1-821f-e28ebef93b62","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"eb85c050-81ca-5be5-adc4-b13733cf2107","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"التجهيزات الداخلية والأثاث والمحتويات","level":3},"visible":true},{"id":"58a6b6bc-d7f3-5e83-b1a9-812fbf824015","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"التجهيزات الداخلية والثابتة والأثاث ومحتويات المكتب وغيرها من الممتلكات المستخدمة داخل المقرات المؤمّنة."},"visible":true}]},{"id":"e105b337-d0cd-5c81-8a5b-896e1d544bcc","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"79b8b204-1446-51bc-918c-950691e423e2","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"البضائع والمخزون","level":3},"visible":true},{"id":"b5adc7d7-404b-5f73-80e6-034469bb127f","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"المواد الخام والمنتجات النهائية والسلع وغيرها من المخزون الموجود في الموقع المؤمّن، بما يشمل تغير مستويات المخزون عند الاقتضاء."},"visible":true}]},{"id":"028cb54c-d434-5d17-80d2-38e8fa1eea01","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"c3c9e9d4-76b7-5fd9-8fa9-0fc6df38e934","type":"heading","content":{"text":"الآلات والمعدات","level":3},"visible":true},{"id":"f5e69c63-52ac-51cb-8353-7dc3250250b3","type":"text","content":{"text":"الآلات ومعدات الإنتاج والحواسيب وغيرها من معدات الأعمال التي قد يكون إصلاحها أو استبدالها مكلفاً بعد ضرر مغطى."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"19c7aae1-422a-5ded-9594-da200695fcc8","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نحدد المخاطر التي تحتاج منشأتك إلى حمايتها ونتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن التغطية والحدود ومبالغ التحمل والاستثناءات والتوسعات قبل ترتيب الوثيقة المختارة.","intro":"يمكن ترتيب تغطية لمجموعة واسعة من الأحداث التي قد تضر بمقراتك أو أصول أعمالك. تعتمد الحماية الدقيقة والحدود والشروط على شركة التأمين والوثيقة المختارتين.","items":[{"text":"أضرار الحريق والانفجار والصواعق والدخان"},{"text":"العواصف والفيضانات والبَرَد والزلازل وغيرها من الأخطار الطبيعية"},{"text":"أضرار المياه من انفجار الأنابيب أو الخزانات أو الأمطار أو مشاكل التصريف"},{"text":"السطو أو السرقة إثر دخول بالقوة"},{"text":"أضرار الاصطدام بالمركبات أو الأحداث الخارجية الأخرى"},{"text":"كسر الزجاج"},{"text":"الأضرار الكهربائية أو تقلب التيار"},{"text":"الإضرابات والشغب والاضطرابات المدنية والأضرار المتعمدة"},{"text":"إزالة الأنقاض والأتعاب المهنية بعد خسارة مغطاة"},{"text":"فقدان الإيجار أو انقطاع الأعمال بعد ضرر ممتلكات"},{"text":"المسؤولية المرتبطة بالممتلكات أو الرجوع المتعلق بالجيران أو الشركاء في الملكية"}],"heading":"ماذا يمكن أن يغطي تأمين الممتلكات التجارية؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"4a52e3db-a376-5e50-a1ab-88bc9ab093b2","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تعتمد الوثيقة المناسبة على أكثر من السعر. فالقيم المؤمّنة ومبالغ التحمل والاستثناءات والتوسعات ومعالجة المطالبات تؤثر جميعها في مدى حماية أعمالك.","items":[{"text":"سمعة شركة التأمين وقوتها المالية وموثوقيتها"},{"text":"القيم المؤمّنة للمباني والمخزون والآلات والمعدات"},{"text":"الحدود والحدود الفرعية المطبّقة على أنواع محددة من الخسائر"},{"text":"مبالغ التحمل التي تتحملها منشأتك عند حدوث مطالبة"},{"text":"حماية الأخطار الطبيعية، بما فيها الفيضانات والزلازل"},{"text":"شروط السرقة بالكسر والخلع ومتطلبات الأمان"},{"text":"تغطية الأضرار الكهربائية وأضرار الآلات والتأمين الهندسي"},{"text":"حماية انقطاع الأعمال والفترة التي تستجيب خلالها"},{"text":"الاستثناءات والاشتراطات وسائر شروط الوثيقة"}],"heading":"ما الذي ينبغي مقارنته قبل اختيار تأمين الممتلكات التجارية؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"0775ab60-9853-5e9a-be13-b01b6886f38d","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"نقيّم ما يحتاج إلى حماية ونقارن شركات التأمين المناسبة في لبنان ونرتّب التغطية وفق أعمالك.","items":[{"body":"نراجع المقرات ونشاط الأعمال والمخزون والآلات والمعدات وغيرها من الأصول التي تحتاج إلى حماية.","title":"تقييم الخطر"},{"body":"نقيّم القيم المصرّح بها والحدود المطلوبة والحماية اللازمة لممتلكاتك وأنشطتك.","title":"تنظيم التغطية"},{"body":"نتواصل مع شركات التأمين المناسبة في السوق اللبنانية ونقارن تغطيتها وشروطها ومبالغ التحمل والاستثناءات والسمعة والسعر.","title":"مقارنة شركات التأمين المناسبة"},{"body":"نوضح الفروق ونتفاوض مع شركات التأمين عند الاقتضاء ونرتّب التغطية المختارة لأعمالك.","title":"ترتيب الوثيقة"}],"layout":"grid","heading":"كيف نرتّب تأمين ممتلكاتك التجارية؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"864b89ff-d499-5459-8864-d2848fb43e52","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تواصل معنا بأسرع وقت. ننسّق المطالبة والتقييم والتواصل مع شركة التأمين نيابةً عنك.","items":[{"text":"عند الحاجة، نرسل خبير مطالبات لمعاينة الضرر وتوثيق الخسارة. ثم نُبلغ شركة التأمين وننسّق التقارير وعروض الأسعار والمستندات الداعمة المطلوبة."},{"text":"نتابع المطالبة عن كثب ونتولى أسئلة شركة التأمين ونعمل على تحصيل التسوية المغطاة المستحقة بموجب الوثيقة."},{"text":"إذا انطبقت تغطية انقطاع الأعمال، ننسّق هذا الجزء من المطالبة أيضاً ونبقى مشاركين حتى انتهائها."}],"heading":"ما الذي تفعله عند تضرر ممتلكات منشأتك؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"a573425f-9f6b-51d7-bd64-f293e3369721","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عن أسئلة شائعة بشأن تأمين مقرات الأعمال وأصولها.","items":[{"answer":"نعم. تُرتَّب التغطية وفق الممتلكات والأصول التي يتحمل كل طرف مسؤوليتها.","question":"س1 – هل يمكن للمالكين والمستأجرين ترتيب تأمين ممتلكات تجارية؟"},{"answer":"نعم. يمكن إدراج عدة مكاتب أو متاجر أو مستودعات أو مواقع أخرى، بحسب المنشأة ومتطلبات شركة التأمين.","question":"س2 – هل يمكن تأمين عدة مواقع أعمال؟"},{"answer":"نعم. يمكن ترتيب قيمة المخزون المؤمّنة وفق مستويات المخزون العادية والقصوى، بحسب المنشأة وشروط الوثيقة.","question":"س3 – هل يمكن تأمين شركات بقيم مخزون موسمية أو متغيرة؟"},{"answer":"نعم. يمكننا مراجعة التغطية الحالية والقيم والحدود ومبالغ التحمل والاستثناءات ومقارنة البدائل المناسبة في السوق.","question":"س4 – هل يمكنكم مراجعة تأمين ممتلكاتي الحالي؟"},{"answer":"نحتاج عادةً إلى نشاط الأعمال وموقع العقار وتكوينه الإنشائي واستخدامه والأصول المؤمّنة وقيمها وتدابير الأمان والحماية من الحريق وسجل المطالبات والتغطية المطلوبة.","question":"س5 – ما المعلومات المطلوبة لعرض سعر؟"},{"answer":"نعم. يمكننا ترتيب تعديلات عند إضافة مواقع أو مخزون أو معدات أو أصول أخرى خلال مدة الوثيقة.","question":"س6 – هل يمكن تحديث الوثيقة خلال السنة؟"},{"answer":"إذا كانت القيم المصرّح بها منخفضة جداً، فقد ينخفض المبلغ المسترد بعد المطالبة وفق شروط الوثيقة. نساعد على مراجعة القيم المؤمّنة قبل الإصدار والتجديد.","question":"س7 – ماذا يحدث إذا كانت ممتلكات المنشأة مؤمّنة بأقل من قيمتها؟"}],"heading":"الأسئلة الشائعة حول تأمين الممتلكات التجارية","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"6def0b07-262f-56b8-96ce-cfba8256a148","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"احمِ موظفيك ومركباتك وبضائعك ومسؤولياتك وغيرها من مخاطر الأعمال بتأمين يُرتَّب وفق أنشطتك.","heading":"استكشف المزيد من تأمين الأعمال","buttonHref":"/ar/solutions/business","buttonLabel":"استكشف تأمين الأعمال"},"visible":true,"children":[],"settings":{"sectionType":"callout"}},{"id":"5d720122-9499-58b7-b17e-d2f2fc648472","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"6aa1c87c-3825-5188-a281-bcdc14e7ad47","type":"container","visible":true,"children":[{"id":"4fbca1c0-615a-5669-8901-37e61752ee24","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"احمِ ممتلكات أعمالك بالتغطية المناسبة.","level":2},"visible":true},{"id":"280133f5-2ba7-5cb9-b213-cfa54e665f1a","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أخبرنا بما تحتاج إلى تأمينه. سنقارن شركات التأمين المناسبة في السوق اللبنانية ونرتّب الحماية التي تحتاجها منشأتك."},"visible":true},{"id":"e5f03524-4300-5c48-9de1-af233cf58034","type":"button","content":{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},"visible":true},{"id":"4b5ce83b-7040-5b1b-b7a5-b7fe39465983","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"builder","schemaVersion":1}');
INSERT INTO public.pages ("Id", "Title", "Slug", "UpdatedAt", "seo_data", "CreatedAt", "IsHomepage", "IsSystemPage", "Locale", "PageGroupId", "Template", "BuilderDocument") VALUES ('2a235d80-c2ef-5e3c-9ca8-e06fce47d0a5', 'تأمين طوارئ العمل', 'ar/solutions/workmen-compensation', '2026-10-12 11:00:07+00', '{"Title":"تأمين طوارئ العمل في لبنان | تريبل إتش وسيط التأمين","Robots":{"Index":true,"Follow":true},"OpenGraph":{"Title":"تأمين طوارئ العمل | تريبل إتش وسيط التأمين","ImageUrl":null,"Description":"احمِ موظفيك ومنشأتك من حوادث العمل بتأمين طوارئ عمل ترتّبه تريبل إتش وسيط التأمين في لبنان."},"Description":"تأمين طوارئ العمل في لبنان لأصحاب العمل. قارن شركات التأمين ورتّب تغطية مناسبة لحوادث الموظفين مع تريبل إتش وسيط التأمين.","CanonicalUrl":"https://www.triplehbroker.com/ar/solutions/workmen-compensation"}', '2026-10-12 11:00:07+00', false, false, 'ar', '2ca1cb21-1292-4573-ad69-929808220d36', 'builder', '{"type":"page","children":[{"id":"9b52a289-c308-5fe2-9e25-2638383c3122","type":"section","styles":{"preset":"cinematic-tall"},"content":{"intro":"احمِ منشأتك وموظفيك من التبعات المالية لحوادث العمل، بتغطية تُرتَّب وفق العاملين وأنشطتك.","items":[{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"}],"eyebrow":"تأمين الأعمال والموظفين","heading":"تأمين طوارئ العمل","imageAlt":"","mobileImageUrl":"","desktopImageUrl":""},"visible":true,"children":[],"settings":{"sectionType":"hero-banner"}},{"id":"e6275be5-9d7b-5a68-b263-83d3d56aa0c1","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"يساعد تأمين طوارئ العمل على حماية منشأتك من مسؤوليتها عند إصابة موظف في حادث عمل. تقارن تريبل إتش شركات التأمين المناسبة وترتّب التغطية وفق العاملين والمهن وأنشطة أعمالك.","eyebrow":"تأمين طوارئ العمل","heading":"ما هو تأمين طوارئ العمل؟","audience":"أصحاب العمل في مختلف القطاعات الذين يحتاجون إلى حماية منشآتهم وموظفيهم من التبعات المالية لحوادث العمل.","buttonHref":"/ar/contact","buttonLabel":"اطلب عرض سعر","audienceHeading":"لمن تُناسب هذه التغطية؟"},"visible":true,"children":[],"settings":{"sectionType":"solution-introduction"}},{"id":"09a6ee9a-5693-5edb-9c88-295244bc2d20","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"visible":true,"children":[{"id":"e2a98c44-1d65-50b9-b3a0-7c6200367caf","type":"container","visible":true,"children":[{"id":"4efbff88-3334-506c-beaf-c5c26d5e28d7","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"كيف يمكن تنظيم تغطية طوارئ العمل؟","level":2},"visible":true},{"id":"7d20d524-c1bc-5dc8-ad94-3bfbc91dc379","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تُرتَّب التغطية وفق العاملين ومهام الموظفين والأجور المصرّح بها ومواقع العمل وأي أنشطة أخرى تؤثر في مخاطر مكان العمل لدى شركتك."},"visible":true},{"id":"a12fad1f-51f5-5b8b-9d87-901f703dbacb","type":"grid","styles":{"mobile":{"gridTemplateColumns":"1fr"},"desktop":{"gap":"24px","gridTemplateColumns":"repeat(3, 1fr)"}},"visible":true,"children":[{"id":"75f4d486-8663-5f87-be2f-8a61fc291c92","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"2e0b148e-c00f-5b61-8a0e-1ee5f25373d9","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"العاملون وفئات الموظفين","level":3},"visible":true},{"id":"bc510681-90a6-5632-bfcd-c46f7da931cd","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"يمكن تغطية موظفيك ضمن وثيقة واحدة للشركة، مع تقسيم العاملين إلى فئات مناسبة بحسب أدوارهم وهيكل توظيفهم."},"visible":true}]},{"id":"2561537b-2425-5a0e-9fa2-8b21a95e5054","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"c831e1e9-485d-554f-bdd1-d186671b7932","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"الأدوار الوظيفية والتعرض للمخاطر","level":3},"visible":true},{"id":"06bd9b14-b075-5a15-9527-5b98340ebfb6","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تراعي شركة التأمين ما يفعله الموظفون فعلياً، إذ قد تنطوي الأعمال المكتبية والقيادة والبناء والتصنيع وغيرها على مستويات مخاطر مختلفة جداً."},"visible":true}]},{"id":"61bb2fb0-0de5-5974-9fbf-45c8723b6e25","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"a1bc6d97-581a-5d83-901d-edf8addcfe01","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"الرواتب والأجور","level":3},"visible":true},{"id":"3ffcd379-6902-5346-92b8-040c0bb533f9","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"تُراعى الرواتب والأجور والدخول المطبّقة المصرّح بها عند ترتيب التغطية، لأنها قد تؤثر في المنافع المؤمّنة والحدود والقسط المطلوب."},"visible":true}]},{"id":"50cbe40c-98eb-561b-8419-5fc4b9a96fc1","type":"stack","styles":{"desktop":{"gap":"12px","border":"1px solid var(--border)","padding":"28px"}},"visible":true,"children":[{"id":"b233b14e-223c-5411-a227-b8447ab4d21b","type":"heading","content":{"text":"مواقع العمل وأنشطة الأعمال","level":3},"visible":true},{"id":"069ae120-001f-5b41-a6bf-7ab79d8e7a00","type":"text","content":{"text":"تراعي شركة التأمين أيضاً أماكن عمل الموظفين والأنشطة المنفذة في كل موقع وأي مخاطر ذات صلة بالمقاولين من الباطن يجب التصريح بها."},"visible":true}]}]}]}],"settings":{"sectionType":"cards"}},{"id":"e9f7c8c2-9088-5373-bec7-d205ca1f5b83","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"help":"نقارن شركات التأمين والمنافع والحدود والأجور المصرّح بها وفئات الموظفين وشروط الوثيقة، ونرتّب تغطية مناسبة لأعمالك ونتولى المطالبات من الإبلاغ مروراً بالتقييم وصولاً إلى التسوية.","intro":"يمكن أن يغطي تأمين طوارئ العمل التبعات المالية لحادث عمل والمرض المهني حيث يُدرج، من العلاج الطبي وفقدان الدخل إلى منافع العجز أو الوفاة ومسؤوليتك كصاحب عمل.","items":[{"text":"النفقات الطبية لإصابة عمل"},{"text":"العجز المؤقت وتعويض الأجور"},{"text":"منافع العجز الدائم الكلي أو الجزئي"},{"text":"منافع الوفاة"},{"text":"مسؤولية صاحب العمل"},{"text":"تكاليف الدفاع القانوني"},{"text":"المرض المهني، حيث تشمله التغطية"},{"text":"التنقل من العمل وإليه، عند توسيع التغطية"}],"heading":"ماذا يمكن أن يغطي تأمين طوارئ العمل؟","helpHeading":"كيف تساعدك تريبل إتش؟"},"visible":true,"children":[],"settings":{"sectionType":"coverage-details"}},{"id":"cac031b6-51fc-56e4-82a7-d1d1d0b25045","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تعتمد الوثيقة المناسبة على أكثر من القسط. فحدود المنافع والأجور المصرّح بها وفئات الموظفين وأنشطة العمل والاستثناءات وشروط المطالبات تؤثر جميعها في حماية أعمالك.","items":[{"text":"سمعة شركة التأمين وشروط تسوية المطالبات"},{"text":"حدود النفقات الطبية والشروط المطبّقة"},{"text":"منافع العجز المؤقت وتعويض الأجور"},{"text":"شروط تعويض العجز الدائم الجزئي والكلي والوفاة"},{"text":"الرواتب والأجور المصرّح بها وأساس احتساب المنافع"},{"text":"مهن الموظفين وفئات المخاطر وأنشطة الأعمال المصرّح بها"},{"text":"مواقع العمل والنطاق الجغرافي للتغطية"},{"text":"عمال المقاولين من الباطن وما إذا كانت المسؤولية المتعلقة بهم مشمولة"},{"text":"تغطية الأمراض المهنية والاستثناءات وقيود الوثيقة"},{"text":"تغيرات العاملين وتسويات كشوف الأجور وتصريحات التجديد"},{"text":"توسعات التنقل من العمل وإليه وغيرها من التوسعات المتاحة"}],"heading":"ما الذي ينبغي مقارنته قبل اختيار تأمين طوارئ العمل؟"},"visible":true,"children":[],"settings":{"sectionType":"feature-list"}},{"id":"f3b21365-e055-58cb-8253-342ee8ca3887","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"نراجع العاملين لديك ومخاطر مكان العمل ونقارن شركات التأمين المناسبة وشروط الوثائق، ثم نرتّب التغطية المختارة ونحافظ عليها مع تغير أعمالك.","items":[{"body":"نراجع أعداد الموظفين ومهنهم والأجور المصرّح بها ومواقع العمل وأنشطة الأعمال لفهم المخاطر المطلوب تغطيتها.","title":"فهم العاملين لديك"},{"body":"نقارن شركات التأمين المناسبة في لبنان من حيث المنافع والحدود والاستثناءات وشروط الوثيقة وشروط تسوية المطالبات والقسط.","title":"مقارنة شركات التأمين المناسبة"},{"body":"نرتّب إصدار الوثيقة المختارة ونؤكد العاملين المصرّح بهم والشروط المؤمّنة ونتحقق من إصدار المستندات والجداول المطلوبة بصورة صحيحة.","title":"ترتيب التغطية المختارة"},{"body":"نتولى المطالبات وتعديلات الوثيقة ذات الصلة مع تغير العاملين أو الأجور أو الأنشطة، ونُعدّ المعلومات المحدّثة المطلوبة للتجديد.","title":"إبقاء تغطيتك محدّثة"}],"layout":"grid","eyebrow":"","heading":"كيف نرتّب تأمين طوارئ العمل؟"},"visible":true,"children":[],"settings":{"sectionType":"steps"}},{"id":"26f0f491-ffd6-5c23-8d3a-9f6ad10830f5","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"تواصل مع تريبل إتش بأسرع وقت بعد حصول الموظف على الرعاية الطبية اللازمة. نتولى المطالبة من الإبلاغ مروراً بالتقييم وصولاً إلى التسوية ونتعامل مع شركة التأمين نيابةً عن شركتك.","items":[{"text":"نسجل المطالبة لدى شركة التأمين ونؤكد المستندات المطلوبة ونساعد شركتك على تقديم تفاصيل الحادث ومعلومات الموظف والتقارير الطبية وغيرها من السجلات الداعمة."},{"text":"نتابع التقييم الطبي وتقييم المطالبة وننسّق مع شركة التأمين والأطراف ذات الصلة ونواصل إجراءات الملف أثناء تحديد المنافع المطبّقة."},{"text":"نراجع التسوية المقترحة وفق شروط الوثيقة ونواصل متابعة المطالبة حتى تسوية المنافع الطبية أو منافع العجز أو الوفاة أو غيرها من المنافع المؤمّنة المطبّقة."}],"heading":"ما الذي تفعله عندما يُصاب أحد موظفيك في العمل؟"},"visible":true,"children":[],"settings":{"sectionType":"editorial-story"}},{"id":"3eef63e7-ff3b-5919-abfe-d185fd32742d","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"إجابات عملية عن تغطية الموظفين وحوادث العمل والأقساط وتغيرات العاملين والمطالبات والمعلومات المطلوبة لترتيب تأمين طوارئ العمل.","items":[{"answer":"يشكل تأمين طوارئ العمل جزءاً من الإطار اللبناني لحماية الموظفين بعد حوادث العمل. ينبغي لأصحاب العمل ترتيب تغطية مناسبة للموظفين الخاضعين للمتطلبات المطبّقة.","question":"س1 – هل تأمين طوارئ العمل مطلوب لشركتنا في لبنان؟"},{"answer":"يمكن أن تشمل التغطية موظفين من جنسيات متنوعة ومهن وفئات مخاطر مختلفة، من موظفي المكاتب إلى العاملين في الأعمال اليدوية والتقنية والقيادة والبناء وغيرها من الأعمال التشغيلية.","question":"س2 – من هم الموظفون الذين يمكن تغطيتهم؟"},{"answer":"يعتمد القسط عموماً على الأجور المصرّح بها وعدد الموظفين، سواء بأسمائهم أو دون تسميتهم، ومهنهم وأنشطة الأعمال ومستوى المخاطر المرتبط بالعمل الذي يؤدونه.","question":"س3 – كيف يُحسب القسط؟"},{"answer":"ليس دائماً. يمكن ترتيب التغطية على أساس موظفين بأسمائهم أو دون تسميتهم، بحسب الوثيقة. وللموظفين غير المسمّين، يجب تقديم الفئات والأعداد والأجور المصرّح بها المطلوبة بدقة.","question":"س4 – هل يجب إدراج اسم كل موظف في الوثيقة؟"},{"answer":"تواصل مع تريبل إتش عند حدوث تغير جوهري في العاملين أو الأجور أو المهن أو الأنشطة لنتحقق مما إذا كانت شركة التأمين تحتاج إلى تحديث معلومات الوثيقة.","question":"س5 – ماذا يحدث إذا تغير العاملون أو الأجور خلال السنة؟"},{"answer":"لا. تأمين طوارئ العمل يختلف عن الصندوق الوطني للضمان الاجتماعي. تستجيب الوثيقة لحوادث العمل وفق شروطها والإطار اللبناني المطبّق، بينما الضمان الاجتماعي نظام مستقل.","question":"س6 – هل تأمين طوارئ العمل هو نفسه الضمان الاجتماعي؟"},{"answer":"ليس تلقائياً في كل وثيقة. قد تُدرج بعض الشركات حوادث التنقل كتوسعة، لذا يجب التحقق من الشروط الجغرافية وشروط الرحلة عند ترتيب التغطية.","question":"س7 – هل الموظفون مشمولون أثناء التنقل من العمل وإليه؟"},{"answer":"قد تُغطّى حيث تُدرج صراحةً في الوثيقة. ينبغي التحقق بعناية من التعريف والحدود والشروط لأن التغطية قد تختلف بين شركات التأمين.","question":"س8 – هل الأمراض المهنية مغطاة؟"},{"answer":"تأكد من حصول الموظف على الرعاية الطبية اللازمة وسجّل ظروف الحادث وتواصل مع تريبل إتش سريعاً. ننسّق المستندات المطلوبة ونُبلغ شركة التأمين ونتابع المطالبة خلال التقييم والتسوية.","question":"س9 – ماذا ينبغي لشركتنا أن تفعل إذا أُصيب موظف في العمل؟"},{"answer":"قد تطلب شركة التأمين تصريح الحادث وتفاصيل الموظف والتقارير الطبية ومستندات العلاج وغيرها من الأدلة المتعلقة بالحادث. نؤكد المتطلبات وندير التقديم بالتعاون مع شركتك.","question":"س10 – ما المستندات التي قد تُطلب لمطالبة حادث عمل؟"},{"answer":"نحتاج عادةً إلى أعداد الموظفين ومهنهم ورواتبهم أو أجورهم المصرّح بها وأنشطة الأعمال ومواقع العمل، وأي مخاطر ذات صلة بالمقاولين من الباطن أو مهام أخرى أعلى خطراً.","question":"س11 – ما المعلومات المطلوبة لعرض تأمين طوارئ العمل؟"},{"answer":"نعم، يمكن إدراج فئات مختلفة من الموظفين ضمن ترتيب واحد للشركة، مع التصريح بالمهن والمخاطر منفصلةً لتتمكن شركة التأمين من تقييم كل فئة بصورة مناسبة.","question":"س12 – هل يمكن تأمين موظفي المكاتب والعاملين الأعلى خطراً في الوثيقة نفسها؟"}],"heading":"الأسئلة الشائعة حول تأمين طوارئ العمل","showArrows":true,"smoothMotion":true},"visible":true,"children":[],"settings":{"sectionType":"faq"}},{"id":"6176f498-25d6-5faa-a0dc-27da12090df0","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px"}},"content":{"intro":"استكشف تغطيات أخرى لحماية موظفيك وممتلكاتك ومخاطر أعمالك الأوسع إلى جانب تأمين طوارئ العمل.","heading":"استكشف المزيد من تأمين الأعمال","buttonHref":"/ar/solutions/business","buttonLabel":"استكشف تأمين الأعمال"},"visible":true,"children":[],"settings":{"sectionType":"callout"}},{"id":"2df29bc9-9303-5c5e-b84b-ae2adecce54f","type":"section","styles":{"mobile":{"paddingTop":"48px","paddingBottom":"48px"},"desktop":{"paddingTop":"80px","paddingBottom":"80px","backgroundColor":"var(--inverse)"}},"visible":true,"children":[{"id":"4ecd3868-7f28-5010-9d0e-3be6bc96e3bd","type":"container","visible":true,"children":[{"id":"d23149e0-5fee-5873-878b-12d195738d40","type":"heading","styles":{"mobile":{"fontSize":"32px"},"desktop":{"fontSize":"44px"}},"content":{"text":"احصل على عرض تأمين طوارئ العمل","level":2},"visible":true},{"id":"fb948bcc-f5a9-515d-8f67-0e007e29e4a0","type":"text","styles":{"desktop":{"fontSize":"17px","maxWidth":"62ch","lineHeight":"1.7"}},"content":{"text":"أرسل تفاصيل العاملين لديك وفئات الموظفين والأجور المصرّح بها وأنشطة العمل. ستقارن تريبل إتش شركات التأمين المناسبة في السوق اللبنانية وتقدم خيارات مكتوبة وواضحة لأعمالك."},"visible":true},{"id":"16d816d0-c602-560c-bb33-0852e960e47b","type":"button","content":{"href":"/ar/contact","label":"اطلب عرض سعر","variant":"inverse"},"visible":true},{"id":"cc380341-080d-501d-89bd-406384b9a15e","type":"button","content":{"href":"https://wa.me/96181891959","label":"استفسر عبر واتساب","variant":"inverse"},"visible":true}]}],"settings":{"imageAlt":"","sectionType":"call-to-action","mobileImageUrl":"","desktopImageUrl":""}}],"settings":{"headerMode":"media-overlay","footerVisible":true},"template":"builder","schemaVersion":1}');
