INSERT INTO public.site_settings ("Id", "Key", "Value", "UpdatedAt") VALUES ('30000000-0000-0000-0000-000000000001', 'site-en', '{"logoUrl": "https://triplehbroker.com/uploads/20260807150719-3b5c04a7c806483dbb8f4cb56fe84b6a.png", "tagline": "Licensed Insurance Broker Company", "documents": [{"key": "terms", "intro": "These terms explain how this website and our brokerage services may be used.", "title": "Terms of Service", "sections": [{"body": "Information on this website is general guidance and is not an insurance quotation, policy, guarantee of cover or financial advice.", "title": "Website information"}, {"body": "Cover is subject to the insurer’s quotation, underwriting approval, policy wording, limits, exclusions and payment terms. The issued policy documents always prevail.", "title": "Insurance cover"}, {"body": "You agree to provide accurate information and not misuse the website. Contacting us or submitting a form does not create insurance cover.", "title": "Using this website"}, {"body": "For questions about these terms or a specific policy, contact Triple H Insurance Broker S.A.R.L. using the phone number or email shown on this website.", "title": "Questions"}]}, {"key": "privacy", "intro": "This notice explains how information shared through this website is handled.", "title": "Privacy Policy", "sections": [{"body": "We may collect the contact and insurance-related information you submit, together with basic technical information needed to operate and protect the website.", "title": "Information we collect"}, {"body": "We use this information to respond to enquiries, prepare or manage insurance requests, support claims, maintain records and meet applicable legal obligations.", "title": "How it is used"}, {"body": "Where necessary for your request, information may be shared with insurers, assessors or service providers. We do not sell personal information.", "title": "When it is shared"}, {"body": "You may ask to review or correct your information, or raise a privacy question, by contacting us at the email address shown on this website.", "title": "Your choices"}]}], "companyName": "Triple H Insurance Broker S.A.R.L", "licenceText": "Broker Licence No. 581 · Commercial Registration No. 2077214", "copyrightText": "All rights reserved.", "footerDescription": "Independent insurance advice for individuals, families and businesses across Lebanon."}', '2026-08-22 16:41:04.447242+00');
INSERT INTO public.site_settings ("Id", "Key", "Value", "UpdatedAt") VALUES ('30000000-0000-0000-0000-000000000002', 'site-ar', '{"logoUrl":"https://triplehbroker.com/uploads/20260807150719-3b5c04a7c806483dbb8f4cb56fe84b6a.png","tagline":"شركة وساطة تأمين مرخّصة","documents":[{"key":"terms","intro":"توضح هذه الشروط كيفية استخدام هذا الموقع وخدمات الوساطة التي نقدمها.","title":"شروط الخدمة","sections":[{"body":"المعلومات الواردة في هذا الموقع للإرشاد العام، ولا تشكل عرض تأمين أو وثيقة تأمين أو ضمان تغطية أو مشورة مالية.","title":"معلومات الموقع"},{"body":"تخضع التغطية لعرض شركة التأمين وموافقة الاكتتاب ونص الوثيقة وحدودها واستثناءاتها وشروط الدفع. وتبقى مستندات الوثيقة الصادرة هي المرجع المعتمد دائماً.","title":"التغطية التأمينية"},{"body":"توافق على تقديم معلومات دقيقة وعدم إساءة استخدام الموقع. لا ينشئ التواصل معنا أو إرسال نموذج تغطية تأمينية.","title":"استخدام الموقع"},{"body":"للأسئلة حول هذه الشروط أو وثيقة محددة، تواصل مع تريبل إتش وسيط التأمين ش.م.م. عبر رقم الهاتف أو البريد الإلكتروني الظاهر في هذا الموقع.","title":"الاستفسارات"}]},{"key":"privacy","intro":"يوضح هذا الإشعار كيفية التعامل مع المعلومات التي تُشارك عبر هذا الموقع.","title":"سياسة الخصوصية","sections":[{"body":"قد نجمع معلومات الاتصال والمعلومات المتعلقة بالتأمين التي تقدمها، إلى جانب المعلومات التقنية الأساسية اللازمة لتشغيل الموقع وحمايته.","title":"المعلومات التي نجمعها"},{"body":"نستخدم هذه المعلومات للرد على الاستفسارات وإعداد طلبات التأمين أو إدارتها ودعم المطالبات وحفظ السجلات والوفاء بالالتزامات القانونية المطبّقة.","title":"كيفية استخدامها"},{"body":"عند الضرورة لتنفيذ طلبك، قد نشارك المعلومات مع شركات التأمين أو خبراء التقييم أو مقدمي الخدمات. لا نبيع المعلومات الشخصية.","title":"متى نشاركها"},{"body":"يمكنك طلب مراجعة معلوماتك أو تصحيحها أو طرح سؤال عن الخصوصية بالتواصل معنا عبر البريد الإلكتروني الظاهر في هذا الموقع.","title":"خياراتك"}]}],"companyName":"تريبل إتش وسيط التأمين ش.م.م.","licenceText":"ترخيص وسيط رقم 581 · السجل التجاري رقم 2077214","copyrightText":"جميع الحقوق محفوظة.","footerDescription":"مشورة تأمينية مستقلة للأفراد والعائلات والشركات في أنحاء لبنان."}', '2026-10-12 11:00:07+00');
